INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87803, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "王是一个国家里最大的人，管全国的人。", "primary_collocate": null, "pronunciation": "wáng", "ipa": "wɑŋ˧˥", "syllable_count": 1, "sentences": [{"text": "故事里的王有一个漂亮的女儿。", "target_word": "王", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "王管着整个国家，大家都很怕他。", "target_word": "王", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个国家的王很爱他的人民。", "target_word": "王", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "王要去别的国家，路上走了十天。", "target_word": "王", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "王今天不高兴，不想见任何人。", "target_word": "王", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国家的人都说，我们的王是个好人。", "target_word": "王", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "王在国家里的地位比所有人都高。", "target_word": "王", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小朋友在画里画了一个戴着金帽子的王。", "target_word": "王", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "王对他的人民说：“明年不用交钱。”", "target_word": "王", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "王走进房间，所有人都站了起来。", "target_word": "王", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一位王", "label": "量词"}, {"form": "国王", "label": "复合"}, {"form": "女王", "label": "复合"}], "register": "中性", "sense_fingerprint": "王：一个国家里最大的人，管全国的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '84eaa279-90ef-4dbd-b39e-63b4c5dbbc90') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87803, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "王", "is_correct": true, "explanation": "王 wáng：一个国家里最大的人，管全国的人，正确答案。"}, {"text": "往", "is_correct": false, "explanation": "往 wǎng（第三声）与 wáng（第二声）声调不同，意思是去、向。"}, {"text": "糖", "is_correct": false, "explanation": "糖 táng 与 wáng 声母不同（t 与 w），意思是糖。"}, {"text": "忙", "is_correct": false, "explanation": "忙 máng 与 wáng 声母不同（m 与 w），意思是忙碌。"}], "explanations": {"王": "王 wáng：一个国家里最大的人，管全国的人，正确答案。", "往": "往 wǎng（第三声）与 wáng（第二声）声调不同，意思是去、向。", "糖": "糖 táng 与 wáng 声母不同（t 与 w），意思是糖。", "忙": "忙 máng 与 wáng 声母不同（m 与 w），意思是忙碌。"}, "sentence_index": null, "correct_answer": "王"}, "level_3": {"options": [{"text": "电脑", "is_correct": false, "explanation": "语义：电脑没有女儿，与“故事里的……有一个漂亮的女儿”矛盾。"}, {"text": "课本", "is_correct": false, "explanation": "语义：课本不能有女儿，与句子的语境矛盾。"}, {"text": "王", "is_correct": true, "explanation": "王：国家的最高统治者，有女儿，与句子相符。"}, {"text": "书包", "is_correct": false, "explanation": "搭配：“有”的主语要是有生命的人，“书包”不能有女儿。"}], "explanations": {"电脑": "语义：电脑没有女儿，与“故事里的……有一个漂亮的女儿”矛盾。", "课本": "语义：课本不能有女儿，与句子的语境矛盾。", "王": "王：国家的最高统治者，有女儿，与句子相符。", "书包": "搭配：“有”的主语要是有生命的人，“书包”不能有女儿。"}, "sentence_index": 0, "correct_answer": "王"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我家门口住着一个王，他每天早上在市场卖菜。", "explanation": "这里应该用〈菜贩〉。王指国家的最高统治者，在市场卖菜的人不能称王。"}, {"text": "医院里来了一个王，他每天给病人打针。", "explanation": "这里应该用〈护士〉。王指国家的最高统治者，给病人打针的人要说“护士”。"}, {"text": "他在工厂里当一个王，负责修理机器。", "explanation": "这里应该用〈修理工〉。王指君主，在工厂修理机器的人不能称王。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '833ea5fc-85bc-447f-ba8f-2c270206bdec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87803, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "王", "is_correct": true, "explanation": "王 wáng：一个国家里最大的人，管全国的人，正确答案。"}, {"text": "旺", "is_correct": false, "explanation": "旺 wàng（第四声）与 wáng（第二声）声调不同，意思是旺盛。"}, {"text": "黄", "is_correct": false, "explanation": "黄 huáng 与 wáng 声母不同（h 与 w），意思是颜色黄。"}, {"text": "房", "is_correct": false, "explanation": "房 fáng 与 wáng 声母不同（f 与 w），意思是房子。"}], "explanations": {"王": "王 wáng：一个国家里最大的人，管全国的人，正确答案。", "旺": "旺 wàng（第四声）与 wáng（第二声）声调不同，意思是旺盛。", "黄": "黄 huáng 与 wáng 声母不同（h 与 w），意思是颜色黄。", "房": "房 fáng 与 wáng 声母不同（f 与 w），意思是房子。"}, "sentence_index": null, "correct_answer": "王"}, "level_3": {"options": [{"text": "老百姓", "is_correct": false, "explanation": "语义：老百姓的地位不可能比所有人都高，与句子的语境矛盾。"}, {"text": "乞丐", "is_correct": false, "explanation": "语义：乞丐的地位不可能比所有人都高，与句子的语境矛盾。"}, {"text": "王", "is_correct": true, "explanation": "王：国家的最高统治者，地位比所有人都高，与句子相符。"}, {"text": "猫", "is_correct": false, "explanation": "搭配：“地位”要求是社会中的人，“猫”不能用于国家里的地位比较。"}], "explanations": {"老百姓": "语义：老百姓的地位不可能比所有人都高，与句子的语境矛盾。", "乞丐": "语义：乞丐的地位不可能比所有人都高，与句子的语境矛盾。", "王": "王：国家的最高统治者，地位比所有人都高，与句子相符。", "猫": "搭配：“地位”要求是社会中的人，“猫”不能用于国家里的地位比较。"}, "sentence_index": 6, "correct_answer": "王"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "学校门口站着一个王，专门检查学生的书包。", "explanation": "这里应该用〈保安〉。王指国家的最高统治者，在校门口检查书包的人不能称王。"}, {"text": "这家饭店来了一个王，每天在厨房里炒菜。", "explanation": "这里应该用〈厨师〉。王指君主，在厨房里炒菜的人要说“厨师”。"}, {"text": "车站里走出来一个王，大声地喊着去机场。", "explanation": "这里应该用〈售票员〉。王指国家的最高统治者，在车站里吆喝去机场的人不能称王。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '833ea5fc-85bc-447f-ba8f-2c270206bdec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87803, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "那位王统治了过整个国家。", "corrected_sentence": "那位王统治过整个国家。", "error_description": "体标错误：“了”和“过”不能同时用在“统治”后，应说“统治过”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '833ea5fc-85bc-447f-ba8f-2c270206bdec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87803, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "很久以前，那块王关心着自己的人民。", "corrected_sentence": "很久以前，那位王关心着自己的人民。", "error_description": "量词错误：“王”指君主，是人，应用量词“位”，“块”用于块状的东西。正确说法：那位王。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '833ea5fc-85bc-447f-ba8f-2c270206bdec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
