INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87810, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "国家、团体之间为共同目的而结成的组织。", "primary_collocate": null, "pronunciation": "lián méng", "ipa": "li̯ɛn˧˥ mɤŋ˧˥", "syllable_count": 2, "sentences": [{"text": "几个国家结成了联盟，共同保护海洋。", "target_word": "联盟", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个联盟成立已经快五十年了。", "target_word": "联盟", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两家公司组成联盟，一起做新产品。", "target_word": "联盟", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们的国家加入了这个联盟。", "target_word": "联盟", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "联盟里的每个国家都要遵守规定。", "target_word": "联盟", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "为了应对大雪灾，几个城市建立了联盟。", "target_word": "联盟", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "足球联盟决定下个月开始新的比赛。", "target_word": "联盟", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些小国家联合成一个联盟，力量就大了。", "target_word": "联盟", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "联盟的代表今天在北京开会。", "target_word": "联盟", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个联盟的目的是帮助穷国发展经济。", "target_word": "联盟", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一个联盟", "label": "量词"}, {"form": "军事联盟", "label": "复合"}], "register": "中性", "sense_fingerprint": "国家或团体为共同目的结成的组织", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '410cbcc6-88e5-4dbf-9766-d970c97f3598') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87810, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "联盟", "is_correct": true, "explanation": "正确答案：联盟 lián méng，指国家或团体为共同目的结成的组织。"}, {"text": "连忙", "is_correct": false, "explanation": "lián máng 与 lián méng 的第二音节韵母不同（ang／eng），连忙意思是急忙、赶快。"}, {"text": "联名", "is_correct": false, "explanation": "míng 与 méng 的韵母不同（ing／eng），联名意思是几个人共同署名。"}, {"text": "莲蓬", "is_correct": false, "explanation": "péng 与 méng 的声母不同（p／m），莲蓬指莲花的果实外壳，与联盟无关。"}], "explanations": {"联盟": "正确答案：联盟 lián méng，指国家或团体为共同目的结成的组织。", "连忙": "lián máng 与 lián méng 的第二音节韵母不同（ang／eng），连忙意思是急忙、赶快。", "联名": "míng 与 méng 的韵母不同（ing／eng），联名意思是几个人共同署名。", "莲蓬": "péng 与 méng 的声母不同（p／m），莲蓬指莲花的果实外壳，与联盟无关。"}, "sentence_index": null, "correct_answer": "联盟"}, "level_3": {"options": [{"text": "联盟", "is_correct": true, "explanation": "正确：“结成联盟”是常用搭配，联盟指国家结成的组织，能够共同保护海洋。"}, {"text": "学校", "is_correct": false, "explanation": "语义：国家不能结成学校，学校是教育机构，与共同保护海洋无关。"}, {"text": "电脑", "is_correct": false, "explanation": "语义：电脑是电子设备，国家不能结成电脑，与共同保护海洋无关。"}, {"text": "团伙", "is_correct": false, "explanation": "语域：团伙带有贬义，不用于国家之间的正式合作。"}], "explanations": {"联盟": "正确：“结成联盟”是常用搭配，联盟指国家结成的组织，能够共同保护海洋。", "学校": "语义：国家不能结成学校，学校是教育机构，与共同保护海洋无关。", "电脑": "语义：电脑是电子设备，国家不能结成电脑，与共同保护海洋无关。", "团伙": "语域：团伙带有贬义，不用于国家之间的正式合作。"}, "sentence_index": 0, "correct_answer": "联盟"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们联盟每周六一起打篮球。", "explanation": "这里应该用〈俱乐部〉。联盟指国家或团体之间为共同目的结成的组织，几个人周末一起打球的业余小组应说俱乐部。"}, {"text": "他是我们的联盟。", "explanation": "这里应该用〈盟友〉。联盟是组织，不指个人，结盟的一方要说盟友。"}, {"text": "联盟有三百张床位。", "explanation": "这里应该用〈医院〉。医院是设有床位的场所，联盟是国家或团体结成的组织，不设床位。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3d1a9c34-0345-46ff-8cb2-0810e91fa327') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87810, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "联盟", "is_correct": true, "explanation": "正确：足球联盟是足球组织，能够作出“决定”。"}, {"text": "球衣", "is_correct": false, "explanation": "语义：球衣是服装，不能作出决定，与句中的决策语境冲突。"}, {"text": "球场", "is_correct": false, "explanation": "语义：球场是场地，不能决定比赛何时开始。"}, {"text": "饮料", "is_correct": false, "explanation": "语义：饮料是喝的东西，不能决定比赛何时开始，与句中的组织决策语境冲突。"}], "explanations": {"联盟": "正确：足球联盟是足球组织，能够作出“决定”。", "球衣": "语义：球衣是服装，不能作出决定，与句中的决策语境冲突。", "球场": "语义：球场是场地，不能决定比赛何时开始。", "饮料": "语义：饮料是喝的东西，不能决定比赛何时开始，与句中的组织决策语境冲突。"}, "sentence_index": 6, "correct_answer": "联盟"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他把联盟放进了冰箱。", "explanation": "这里应该用〈牛奶〉。牛奶是东西，可以放进冰箱；联盟是国家或团体结成的组织，不是东西，不能放进冰箱。"}, {"text": "这家公司是一个大型联盟。", "explanation": "这里应该用〈集团〉。联盟是多方结成的组织，一家公司本身是单一实体，应说“大型集团”。"}, {"text": "这个联盟很好吃。", "explanation": "这里应该用〈面包〉。面包是食物，可以说好吃；联盟是国家或团体结成的组织，不能用“好吃”形容。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3d1a9c34-0345-46ff-8cb2-0810e91fa327') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87810, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他们组成了一只新的联盟。", "corrected_sentence": "他们组成了一个新的联盟。", "error_description": "量词错误：“联盟”是抽象组织，应用量词“个”，“只”多用于动物。错误形式是“一只联盟”，正确形式是“一个联盟”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3d1a9c34-0345-46ff-8cb2-0810e91fa327') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87810, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "两家公司组成了一个新联盟们。", "corrected_sentence": "两家公司组成了一个新联盟。", "error_description": "词缀错误：“们”只用于指人的名词或代词之后，“联盟”指组织，不能加“们”。错误形式是“新联盟们”，正确形式是“新联盟”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3d1a9c34-0345-46ff-8cb2-0810e91fa327') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
