INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87811, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "合成", "is_correct": true, "explanation": "反义：“合成”是把若干部分合为一个整体，与“分为”意思相反。"}, {"text": "读书", "is_correct": false, "explanation": "与“分为”没有反义关系。"}, {"text": "画画", "is_correct": false, "explanation": "与“分为”没有反义关系。"}, {"text": "洗澡", "is_correct": false, "explanation": "与“分为”没有反义关系。"}], "correct_answer": "合成", "explanations": {"合成": "反义：“合成”是把若干部分合为一个整体，与“分为”意思相反。", "读书": "与“分为”没有反义关系。", "画画": "与“分为”没有反义关系。", "洗澡": "与“分为”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6fcd30b9-9649-49b6-a32a-d303d4af5e0e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87811, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "分为是把一个东西分开，变成几个部分。", "primary_collocate": null, "pronunciation": "fēn wéi", "ipa": "fən˥ weɪ˧˥", "syllable_count": 2, "sentences": [{"text": "他把蛋糕分为六块。", "target_word": "分为", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把这些苹果分为两堆。", "target_word": "分为", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "河水在这里分为两条小河。", "target_word": "分为", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这条路到前面分为两条。", "target_word": "分为", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我把这个月的钱分为四份。", "target_word": "分为", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板把大房间分为两个小房间。", "target_word": "分为", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们把这块地分为三块。", "target_word": "分为", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把这根绳子分为两段。", "target_word": "分为", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这张纸分为四块。", "target_word": "分为", "complexity_tier": "T3", "furigana": "zhè zhāng zhǐ fēn wéi sì kuài", "sentence_source": "generated"}, {"text": "妈妈把面包分为四份，每人一份。", "target_word": "分为", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "分為", "label": "繁体"}], "register": "中性", "sense_fingerprint": "把一个具体的东西分开成几块或几份", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '14147f2a-e52b-4b73-85e3-382a3d8c63ac') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87811, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "分为", "is_correct": true, "explanation": "正确。分为：把一个东西分开，变成几个部分。"}, {"text": "身为", "is_correct": false, "explanation": "shēn（第一声）与 fēn 只差声母（sh/f），意思是作为（身为）。"}, {"text": "分位", "is_correct": false, "explanation": "wèi（第四声）与 wéi（第二声）只差声调，意思是分位（位置、分位数）。"}, {"text": "封为", "is_correct": false, "explanation": "fēng（第一声）与 fēn 只差韵尾（-ng/-n），意思是封（授予称号）为。"}], "explanations": {"分为": "正确。分为：把一个东西分开，变成几个部分。", "身为": "shēn（第一声）与 fēn 只差声母（sh/f），意思是作为（身为）。", "分位": "wèi（第四声）与 wéi（第二声）只差声调，意思是分位（位置、分位数）。", "封为": "fēng（第一声）与 fēn 只差韵尾（-ng/-n），意思是封（授予称号）为。"}, "sentence_index": null, "correct_answer": "分为"}, "level_3": {"options": [{"text": "分为", "is_correct": true, "explanation": "正确。“分为”表示把蛋糕分开成几块，符合句意。"}, {"text": "合为", "is_correct": false, "explanation": "语义：“合为”表示合成一个整体，与“分”的意思相反，句意矛盾。"}, {"text": "拼", "is_correct": false, "explanation": "搭配：“拼”要和“成”或“起来”搭配，不能直接说“拼六块”。"}, {"text": "有", "is_correct": false, "explanation": "配价：“有”不能用于“把”字句，不能说“把蛋糕有六块”。"}], "explanations": {"分为": "正确。“分为”表示把蛋糕分开成几块，符合句意。", "合为": "语义：“合为”表示合成一个整体，与“分”的意思相反，句意矛盾。", "拼": "搭配：“拼”要和“成”或“起来”搭配，不能直接说“拼六块”。", "有": "配价：“有”不能用于“把”字句，不能说“把蛋糕有六块”。"}, "sentence_index": 0, "correct_answer": "分为"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我把这块布分为三个同学。", "explanation": "这里应该用〈分给〉。分为指把整体划分成若干部分，分给才是把东西交给人。"}, {"text": "这块冰分为了水。", "explanation": "这里应该用〈变成〉。分为表示把整体划开，不能表示物质发生变化。"}, {"text": "他把钱分为了一个人。", "explanation": "这里应该用〈交给〉。分为表示划分，不能表示把东西交给某个人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6fcd30b9-9649-49b6-a32a-d303d4af5e0e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87811, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "分为", "is_correct": true, "explanation": "正确。分为：把一个东西分开，变成几个部分。"}, {"text": "纷飞", "is_correct": false, "explanation": "fēi（第一声）与 wéi（第二声）声母不同，意思是纷纷飞舞。"}, {"text": "芬芳", "is_correct": false, "explanation": "fāng（第一声）与 wéi（第二声）声母和韵母都不同，意思是香气。"}, {"text": "分歧", "is_correct": false, "explanation": "qí（第二声）与 wéi（第二声）声母不同，意思是意见不一致。"}], "explanations": {"分为": "正确。分为：把一个东西分开，变成几个部分。", "纷飞": "fēi（第一声）与 wéi（第二声）声母不同，意思是纷纷飞舞。", "芬芳": "fāng（第一声）与 wéi（第二声）声母和韵母都不同，意思是香气。", "分歧": "qí（第二声）与 wéi（第二声）声母不同，意思是意见不一致。"}, "sentence_index": null, "correct_answer": "分为"}, "level_3": {"options": [{"text": "分为", "is_correct": true, "explanation": "正确。“分为”表示把这块地分成几块，符合句意。"}, {"text": "连", "is_correct": false, "explanation": "语义：“连”表示相连，与“分”的意思相反，不能说“连三块”。"}, {"text": "删", "is_correct": false, "explanation": "搭配：“删”一般用于文字和数据，不能用于土地。"}, {"text": "包", "is_correct": false, "explanation": "搭配：“包”是包裹的意思，不能把土地“包”成三块。"}], "explanations": {"分为": "正确。“分为”表示把这块地分成几块，符合句意。", "连": "语义：“连”表示相连，与“分”的意思相反，不能说“连三块”。", "删": "搭配：“删”一般用于文字和数据，不能用于土地。", "包": "搭配：“包”是包裹的意思，不能把土地“包”成三块。"}, "sentence_index": 6, "correct_answer": "分为"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他分为了一份奖金。", "explanation": "这里应该用〈得到〉。分为表示把整体划分成若干部分，不能表示某人获得奖金。"}, {"text": "这杯水分为了冰。", "explanation": "这里应该用〈变成〉。分为表示划分，不能表示水变成冰。"}, {"text": "我能分为这两种味道。", "explanation": "这里应该用〈分辨〉。分为表示划分整体，不能表示辨认味道。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6fcd30b9-9649-49b6-a32a-d303d4af5e0e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
