INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87812, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "把整体划分成若干部分。", "primary_collocate": null, "pronunciation": "fēn wéi", "ipa": "fən˥ weɪ˧˥", "syllable_count": 2, "sentences": [{"text": "这本书分为三个部分。", "target_word": "分为", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们班分为两个小组。", "target_word": "分为", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "一年分为春夏秋冬四个季节。", "target_word": "分为", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个故事分为上下两篇。", "target_word": "分为", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "比赛分为男子组和女子组。", "target_word": "分为", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师把学生分为五个小组。", "target_word": "分为", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次考试分为听力和阅读两部分。", "target_word": "分为", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "中国可以分为南方和北方。", "target_word": "分为", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "一天可以分为白天和晚上。", "target_word": "分为", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "公司的工作分为销售和技术两类。", "target_word": "分为", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "分為", "label": "繁体"}], "register": "中性", "sense_fingerprint": "把整体按类别或结构划分成若干部分", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '14147f2a-e52b-4b73-85e3-382a3d8c63ac') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.