INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87812, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "分为", "is_correct": true, "explanation": "正确。分为：把整体划分成若干部分。"}, {"text": "身为", "is_correct": false, "explanation": "shēn（第一声）与 fēn 只差声母（sh/f），意思是作为（身为）。"}, {"text": "分位", "is_correct": false, "explanation": "wèi（第四声）与 wéi（第二声）只差声调，意思是分位（位置、分位数）。"}, {"text": "封为", "is_correct": false, "explanation": "fēng（第一声）与 fēn 只差韵尾（-ng/-n），意思是封（授予称号）为。"}], "explanations": {"分为": "正确。分为：把整体划分成若干部分。", "身为": "shēn（第一声）与 fēn 只差声母（sh/f），意思是作为（身为）。", "分位": "wèi（第四声）与 wéi（第二声）只差声调，意思是分位（位置、分位数）。", "封为": "fēng（第一声）与 fēn 只差韵尾（-ng/-n），意思是封（授予称号）为。"}, "sentence_index": null, "correct_answer": "分为"}, "level_3": {"options": [{"text": "分为", "is_correct": true, "explanation": "正确。“分为”表示把整体分成几个部分，符合句意。"}, {"text": "合为", "is_correct": false, "explanation": "语义：“合为”表示合成一个整体，与“分”的意思相反，句意矛盾。"}, {"text": "撕", "is_correct": false, "explanation": "搭配：“撕”要带结果补语“成”，不能直接说“撕三个部分”。"}, {"text": "煮", "is_correct": false, "explanation": "搭配：“煮”的对象多为食物，不能说“煮三个部分”。"}], "explanations": {"分为": "正确。“分为”表示把整体分成几个部分，符合句意。", "合为": "语义：“合为”表示合成一个整体，与“分”的意思相反，句意矛盾。", "撕": "搭配：“撕”要带结果补语“成”，不能直接说“撕三个部分”。", "煮": "搭配：“煮”的对象多为食物，不能说“煮三个部分”。"}, "sentence_index": 0, "correct_answer": "分为"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我把这笔钱分为三个朋友。", "explanation": "这里应该用〈分给〉。分为指把整体划分成若干部分，分给才是把东西交给人。"}, {"text": "他分为了一名老师。", "explanation": "这里应该用〈成为〉。分为表示把整体划分开，不能表示人变成某种身份。"}, {"text": "我们分为了这个问题的原因。", "explanation": "这里应该用〈分析〉。分为指把整体分成部分，不能表示对问题进行研究。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6fcd30b9-9649-49b6-a32a-d303d4af5e0e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87812, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "分为", "is_correct": true, "explanation": "正确。分为：把整体划分成若干部分。"}, {"text": "分配", "is_correct": false, "explanation": "pèi（第四声）与 wéi（第二声）不同，意思是分派、配给。"}, {"text": "分辨", "is_correct": false, "explanation": "biàn（第四声）与 wéi（第二声）不同，意思是辨别、区分。"}, {"text": "芬芳", "is_correct": false, "explanation": "fāng（第一声）与 wéi（第二声）声母和韵母都不同，意思是香气。"}], "explanations": {"分为": "正确。分为：把整体划分成若干部分。", "分配": "pèi（第四声）与 wéi（第二声）不同，意思是分派、配给。", "分辨": "biàn（第四声）与 wéi（第二声）不同，意思是辨别、区分。", "芬芳": "fāng（第一声）与 wéi（第二声）声母和韵母都不同，意思是香气。"}, "sentence_index": null, "correct_answer": "分为"}, "level_3": {"options": [{"text": "分为", "is_correct": true, "explanation": "正确。“分为”表示把整体分成几个部分，符合句意。"}, {"text": "合并", "is_correct": false, "explanation": "语义：“合并”表示合在一起，与“分为”意思相反，句意矛盾。"}, {"text": "组织", "is_correct": false, "explanation": "搭配：“组织”带活动或考试作宾语，不能说“组织听力和阅读两部分”。"}, {"text": "分布", "is_correct": false, "explanation": "配价：“分布”是不及物动词，不能直接带“听力和阅读两部分”作宾语。"}], "explanations": {"分为": "正确。“分为”表示把整体分成几个部分，符合句意。", "合并": "语义：“合并”表示合在一起，与“分为”意思相反，句意矛盾。", "组织": "搭配：“组织”带活动或考试作宾语，不能说“组织听力和阅读两部分”。", "分布": "配价：“分布”是不及物动词，不能直接带“听力和阅读两部分”作宾语。"}, "sentence_index": 6, "correct_answer": "分为"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他分为了九十分。", "explanation": "这里应该用〈得〉。分为表示把整体划分成部分，不能表示考试取得分数。"}, {"text": "这块冰分为了水。", "explanation": "这里应该用〈变成〉。分为表示划分整体，不能表示物质的变化。"}, {"text": "我能分为这两种颜色。", "explanation": "这里应该用〈分辨〉。分为表示划分整体，不能表示辨认颜色。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6fcd30b9-9649-49b6-a32a-d303d4af5e0e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_war