INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87812, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这座城市分为着东区和西区。", "corrected_sentence": "这座城市分为东区和西区。", "error_description": "动态助词错误：“分为”表示划分的结果，后面不能加“着”。应说“这座城市分为东区和西区”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6fcd30b9-9649-49b6-a32a-d303d4af5e0e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87812, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个城市分为是东区和西区。", "corrected_sentence": "这个城市分为东区和西区。", "error_description": "“分为”后面不能再加“是”，“为”已经引出结果。应说“这个城市分为东区和西区”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6fcd30b9-9649-49b6-a32a-d303d4af5e0e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87817, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "轻", "is_correct": true, "explanation": "正确：“轻”与“重”在分量上相对，是反义词。"}, {"text": "快", "is_correct": false, "explanation": "无关：“快”说速度，与“重”（分量大）不构成反义关系。"}, {"text": "圆", "is_correct": false, "explanation": "无关：“圆”说形状，与“重”没有反义关系。"}, {"text": "干净", "is_correct": false, "explanation": "无关：“干净”说清洁，与“重”没有反义关系。"}], "correct_answer": "轻", "explanations": {"轻": "正确：“轻”与“重”在分量上相对，是反义词。", "快": "无关：“快”说速度，与“重”（分量大）不构成反义关系。", "圆": "无关：“圆”说形状，与“重”没有反义关系。", "干净": "无关：“干净”说清洁，与“重”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '26503c15-eeab-4ed0-8337-4c518cf997e1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
