INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87817, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "重是东西拿起来很沉，很费力。", "primary_collocate": null, "pronunciation": "zhòng", "ipa": "ʈʂʊŋ˥˩", "syllable_count": 1, "sentences": [{"text": "这个箱子很重，我一个人拿不动。", "target_word": "重", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "书包太重了，背着很累。", "target_word": "重", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这袋米不重，我可以自己拿回家。", "target_word": "重", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他搬不动这张桌子，因为桌子太重。", "target_word": "重", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你帮我拿一下，这个包有点儿重。", "target_word": "重", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "行李这么重，我们打车去车站吧。", "target_word": "重", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个行李箱比那个重得多，我拿起来很费力。", "target_word": "重", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老人手里的东西很重，我去帮他拿。", "target_word": "重", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "水桶装满水以后会很重，你一个人提不动。", "target_word": "重", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这把椅子不太重，小孩子也能搬动。", "target_word": "重", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "更重", "label": "比较"}, {"form": "最重", "label": "最高级"}], "register": "中性", "sense_fingerprint": "重：东西拿起来沉，费力", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 1 above tier T1: 3 words above tier T1 (max 2): 书包 (Zipf 3.62), 背着 (Zipf 3.75), 很累 (Zipf 3.45)']::text[], 'cd5c4b2d-97ab-40df-bb81-bfbbee817b15') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87817, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "重", "is_correct": true, "explanation": "正确：zhòng（第四声）是“重”，指东西拿起来沉、分量大。"}, {"text": "中", "is_correct": false, "explanation": "声调不同：zhōng（第一声）与 zhòng（第四声）只差声调，“中”意思是中间。"}, {"text": "种", "is_correct": false, "explanation": "声调不同：zhǒng（第三声）与 zhòng（第四声）声调不同，“种”意思是种类。"}, {"text": "正", "is_correct": false, "explanation": "韵母不同：zhèng（eng）与 zhòng（ong）韵母不同，“正”意思是正确。"}, {"text": "账", "is_correct": false, "explanation": "韵母不同：zhàng（ang）与 zhòng（ong）韵母不同，“账”意思是账目。"}], "explanations": {"重": "正确：zhòng（第四声）是“重”，指东西拿起来沉、分量大。", "中": "声调不同：zhōng（第一声）与 zhòng（第四声）只差声调，“中”意思是中间。", "种": "声调不同：zhǒng（第三声）与 zhòng（第四声）声调不同，“种”意思是种类。", "正": "韵母不同：zhèng（eng）与 zhòng（ong）韵母不同，“正”意思是正确。", "账": "韵母不同：zhàng（ang）与 zhòng（ong）韵母不同，“账”意思是账目。"}, "sentence_index": null, "correct_answer": "重"}, "level_3": {"options": [{"text": "重", "is_correct": true, "explanation": "正确：“重”说东西分量大，与后半句“拿不动”呼应。"}, {"text": "干净", "is_correct": false, "explanation": "语义：“干净”说清洁，与“拿不动”没有关系，句子读下来不通。"}, {"text": "快", "is_correct": false, "explanation": "搭配：“快”说速度，不能用来形容箱子。"}, {"text": "甜", "is_correct": false, "explanation": "搭配：“甜”说味道，不能用来形容箱子。"}], "explanations": {"重": "正确：“重”说东西分量大，与后半句“拿不动”呼应。", "干净": "语义：“干净”说清洁，与“拿不动”没有关系，句子读下来不通。", "快": "搭配：“快”说速度，不能用来形容箱子。", "甜": "搭配：“甜”说味道，不能用来形容箱子。"}, "sentence_index": 0, "correct_answer": "重"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个房间很重，我一个人住很舒服。", "explanation": "这里应该用〈大〉。“重”说东西的分量，形容房间的空间要用“大”；“房间很重”不成立。"}, {"text": "这件大衣的价格很重，我买不起。", "explanation": "这里应该用〈贵〉。“重”说东西的分量，不能用来形容价钱；价钱高要用“贵”。"}, {"text": "他的汉语水平很重，我们都很佩服他。", "explanation": "这里应该用〈高〉。“重”说东西的分量，不能用来形容水平；水平的高低要用“高”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '26503c15-eeab-4ed0-8337-4c518cf997e1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87817, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "重", "is_correct": true, "explanation": "正确：zhòng（第四声）是“重”，指东西拿起来沉、分量大。"}, {"text": "钟", "is_correct": false, "explanation": "声调不同：zhōng（第一声）与 zhòng（第四声）只差声调，“钟”意思是钟表。"}, {"text": "肿", "is_correct": false, "explanation": "声调不同：zhǒng（第三声）与 zhòng（第四声）声调不同，“肿”意思是肿胀。"}, {"text": "证", "is_correct": false, "explanation": "韵母不同：zhèng（eng）与 zhòng（ong）韵母不同，“证”意思是证件或证明。"}, {"text": "仗", "is_correct": false, "explanation": "韵母不同：zhàng（ang）与 zhòng（ong）韵母不同，“仗”意思是战斗。"}], "explanations": {"重": "正确：zhòng（第四声）是“重”，指东西拿起来沉、分量大。", "钟": "声调不同：zhōng（第一声）与 zhòng（第四声）只差声调，“钟”意思是钟表。", "肿": "声调不同：zhǒng（第三声）与 zhòng（第四声）声调不同，“肿”意思是肿胀。", "证": "韵母不同：zhèng（eng）与 zhòng（ong）韵母不同，“证”意思是证件或证明。", "仗": "韵母不同：zhàng（ang）与 zhòng（ong）韵母不同，“仗”意思是战斗。"}, "sentence_index": null, "correct_answer": "重"}, "level_3": {"options": [{"text": "重", "is_correct": true, "explanation": "正确：“重”与“得多”搭配，说行李箱的分量更大，与后半句“很费力”呼应。"}, {"text": "亮", "is_correct": false, "explanation": "语义：“亮”说光线，与后半句“拿起来很费力”无关，句子不通。"}, {"text": "贵", "is_correct": false, "explanation": "语义：“贵”说价钱，与“拿起来很费力”没有联系，句子不通。"}, {"text": "热", "is_correct": false, "explanation": "搭配：“热”说温度，不能用来比较行李箱的分量。"}], "explanations": {"重": "正确：“重”与“得多”搭配，说行李箱的分量更大，与后半句“很费力”呼应。", "亮": "语义：“亮”说光线，与后半句“拿起来很费力”无关，句子不通。", "贵": "语义：“贵”说价钱，与“拿起来很费力”没有联系，句子不通。", "热": "搭配：“热”说温度，不能用来比较行李箱的分量。"}, "sentence_index": 6, "correct_answer": "重"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的声音很重，听起来很有力量。", "explanation": "这里应该用〈沉〉。描述声音低沉要用“沉”；“重”说的是东西的分量，不说声音。"}, {"text": "这个电梯的速度很重，一分钟就到了。", "explanation": "这里应该用〈快〉。“重”说东西的分量，不能用来形容速度；速度的快慢要用“快”。"}, {"text": "这里离市中心很重，坐车要半个小时。", "explanation": "这里应该用〈远〉。“重”说东西的分量，不能用来形容距离；距离的远近要用“远”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '26503c15-eeab-4ed0-8337-4c518cf997e1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87817, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个包重背不动了。", "corrected_sentence": "这个包重得背不动了。", "error_description": "错误：“重”后漏掉了补语标记“得”。正确是“重得背不动了”，“得”引出程度补语；“重背不动”不成立。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '26503c15-eeab-4ed0-8337-4c518cf997e1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87817, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个书包比那个重多得。", "corrected_sentence": "这个书包比那个重得多。", "error_description": "错误：程度补语的语序颠倒。“重”后应先接“得”，再接“多”，正确是“重得多”；“重多得”不成立。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '26503c15-eeab-4ed0-8337-4c518cf997e1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87818, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "轻", "is_correct": true, "explanation": "正确：“轻”与“重”在分量上相对，是反义词。"}, {"text": "长", "is_correct": false, "explanation": "无关：“长”说长度，与“重”没有反义关系。"}, {"text": "圆", "is_correct": false, "explanation": "无关：“圆”说形状，与“重”没有反义关系。"}, {"text": "冷", "is_correct": false, "explanation": "无关：“冷”说温度，与“重”没有反义关系。"}], "correct_answer": "轻", "explanations": {"轻": "正确：“轻”与“重”在分量上相对，是反义词。", "长": "无关：“长”说长度，与“重”没有反义关系。", "圆": "无关：“圆”说形状，与“重”没有反义关系。", "冷": "无关：“冷”说温度，与“重”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '26503c15-eeab-4ed0-8337-4c518cf997e1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87818, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "轻", "is_correct": true, "explanation": "正确：“轻”与“重”在分量上相对，是反义词。"}, {"text": "窄", "is_correct": false, "explanation": "无关：“窄”说宽度，与“重”没有反义关系。"}, {"text": "慢", "is_correct": false, "explanation": "无关：“慢”说速度，与“重”没有反义关系。"}, {"text": "清楚", "is_correct": false, "explanation": "无关：“清楚”说明晰，与“重”没有反义关系。"}], "correct_answer": "轻", "explanations": {"轻": "正确：“轻”与“重”在分量上相对，是反义词。", "窄": "无关：“窄”说宽度，与“重”没有反义关系。", "慢": "无关：“慢”说速度，与“重”没有反义关系。", "清楚": "无关：“清楚”说明晰，与“重”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '26503c15-eeab-4ed0-8337-4c518cf997e1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87818, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "分量大；与“轻”相对。", "primary_collocate": null, "pronunciation": "zhòng", "ipa": "ʈʂʊŋ˥˩", "syllable_count": 1, "sentences": [{"text": "同样大小的铁比木头重。", "target_word": "重", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这块石头有二十公斤，很重。", "target_word": "重", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "大象很重，小鸟很轻。", "target_word": "重", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我的行李比你的重五公斤。", "target_word": "重", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "称一称，这条鱼不重，只有一斤。", "target_word": "重", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个盒子看起来很小，却很重。", "target_word": "重", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "两个西瓜哪个更重？我们称一下吧。", "target_word": "重", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这条鱼有三十公斤重，真大！", "target_word": "重", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "书包里的书越多，书包就越重。", "target_word": "重", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "同样大小的金块比铜块重得多，因为金子的密度很大。", "target_word": "重", "complexity_tier": "T3", "furigana": "tóng yàng dà xiǎo de jīn kuài bǐ tóng kuài zhòng de duō, yīn wèi jīn zi de mì dù hěn dà.", "sentence_source": "generated"}], "morphological_forms": [{"form": "更重", "label": "比较"}, {"form": "重量", "label": "复合"}, {"form": "体重", "label": "复合"}], "register": "中性", "sense_fingerprint": "重：分量大，与轻相对", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd5c4b2d-97ab-40df-bb81-bfbbee817b15') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87818, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "重", "is_correct": true, "explanation": "正确：zhòng（第四声）是“重”，指分量大。"}, {"text": "中", "is_correct": false, "explanation": "声调不同：zhōng（第一声）与 zhòng（第四声）只差声调，“中”意思是中间。"}, {"text": "肿", "is_correct": false, "explanation": "声调不同：zhǒng（第三声）与 zhòng（第四声）声调不同，“肿”意思是肿胀。"}, {"text": "政", "is_correct": false, "explanation": "韵母不同：zhèng（eng）与 zhòng（ong）韵母不同，“政”意思是政治。"}, {"text": "账", "is_correct": false, "explanation": "韵母不同：zhàng（ang）与 zhòng（ong）韵母不同，“账”意思是账目。"}], "explanations": {"重": "正确：zhòng（第四声）是“重”，指分量大。", "中": "声调不同：zhōng（第一声）与 zhòng（第四声）只差声调，“中”意思是中间。", "肿": "声调不同：zhǒng（第三声）与 zhòng（第四声）声调不同，“肿”意思是肿胀。", "政": "韵母不同：zhèng（eng）与 zhòng（ong）韵母不同，“政”意思是政治。", "账": "韵母不同：zhàng（ang）与 zhòng（ong）韵母不同，“账”意思是账目。"}, "sentence_index": null, "correct_answer": "重"}, "level_3": {"options": [{"text": "重", "is_correct": true, "explanation": "正确：“重”说铁的分量比木头大，与“比木头”的比较相符。"}, {"text": "大", "is_correct": false, "explanation": "语义：“同样大小”与“大”矛盾，“同样大小的铁比木头大”不通。"}, {"text": "快", "is_correct": false, "explanation": "搭配：“快”说速度，不能用来比较铁和木头的分量。"}, {"text": "甜", "is_correct": false, "explanation": "搭配：“甜”说味道，不能用来比较铁和木头。"}], "explanations": {"重": "正确：“重”说铁的分量比木头大，与“比木头”的比较相符。", "大": "语义：“同样大小”与“大”矛盾，“同样大小的铁比木头大”不通。", "快": "搭配：“快”说速度，不能用来比较铁和木头的分量。", "甜": "搭配：“甜”说味道，不能用来比较铁和木头。"}, "sentence_index": 0, "correct_answer": "重"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我今天的作业比你的重两页。", "explanation": "这里应该用〈多〉。“重”说分量，比较页数等数量要用“多”。"}, {"text": "他的数学水平很重，老师都夸他。", "explanation": "这里应该用〈高〉。“重”说东西的分量，不能用来形容水平；水平的高低要用“高”。"}, {"text": "这个学校离我家很重，我每天要走一个小时。", "explanation": "这里应该用〈远〉。“重”说东西的分量，不能用来形容距离；距离的远近要用“远”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '26503c15-eeab-4ed0-8337-4c518cf997e1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87818, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "重", "is_correct": true, "explanation": "正确：zhòng（第四声）是“重”，指分量大。"}, {"text": "钟", "is_correct": false, "explanation": "声调不同：zhōng（第一声）与 zhòng（第四声）只差声调，“钟”意思是钟表。"}, {"text": "种", "is_correct": false, "explanation": "声调不同：zhǒng（第三声）与 zhòng（第四声）声调不同，“种”意思是种类。"}, {"text": "正", "is_correct": false, "explanation": "韵母不同：zhèng（eng）与 zhòng（ong）韵母不同，“正”意思是正确。"}, {"text": "仗", "is_correct": false, "explanation": "韵母不同：zhàng（ang）与 zhòng（ong）韵母不同，“仗”意思是战斗。"}], "explanations": {"重": "正确：zhòng（第四声）是“重”，指分量大。", "钟": "声调不同：zhōng（第一声）与 zhòng（第四声）只差声调，“钟”意思是钟表。", "种": "声调不同：zhǒng（第三声）与 zhòng（第四声）声调不同，“种”意思是种类。", "正": "韵母不同：zhèng（eng）与 zhòng（ong）韵母不同，“正”意思是正确。", "仗": "韵母不同：zhàng（ang）与 zhòng（ong）韵母不同，“仗”意思是战斗。"}, "sentence_index": null, "correct_answer": "重"}, "level_3": {"options": [{"text": "重", "is_correct": true, "explanation": "正确：“更重”与“称一下”相符，说明要比较两个西瓜的分量。"}, {"text": "硬", "is_correct": false, "explanation": "语义：“称一下”说的是分量，“硬”说质地，句子不通。"}, {"text": "亮", "is_correct": false, "explanation": "语义：“亮”说光线，与“称一下”的分量无关。"}, {"text": "高", "is_correct": false, "explanation": "搭配：“高”说高度，不能与“称一下”搭配。"}], "explanations": {"重": "正确：“更重”与“称一下”相符，说明要比较两个西瓜的分量。", "硬": "语义：“称一下”说的是分量，“硬”说质地，句子不通。", "亮": "语义：“亮”说光线，与“称一下”的分量无关。", "高": "搭配：“高”说高度，不能与“称一下”搭配。"}, "sentence_index": 6, "correct_answer": "重"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个人的脸色很重，大家都不敢说话。", "explanation": "这里应该用〈沉〉。形容脸色阴沉要用“沉”；“重”说的是分量，不说脸色。"}, {"text": "这套房子的价钱很重，我们买不起。", "explanation": "这里应该用〈贵〉。“重”说东西的分量，不能用来形容价钱；价钱高要用“贵”。"}, {"text": "这辆车的速度很重，一小时就到了。", "explanation": "这里应该用〈快〉。“重”说东西的分量，不能用来形容速度；速度的快慢要用“快”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '26503c15-eeab-4ed0-8337-4c518cf997e1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87818, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这袋米得重我提不动。", "corrected_sentence": "这袋米重得我提不动。", "error_description": "错误：补语标记“得”的位置放错了。“得”应紧跟在形容词“重”后面，正确是“重得我提不动”；“得重”不成立。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '26503c15-eeab-4ed0-8337-4c518cf997e1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87818, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "装了太多书，箱子变重着。", "corrected_sentence": "装了太多书，箱子变重了。", "error_description": "错误：“变重”后用了“着”。“着”表示状态持续，表示变化已经完成要用“了”。正确是“箱子变重了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '26503c15-eeab-4ed0-8337-4c518cf997e1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87820, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa18be8f-33a9-4fdb-8eec-026753a094e1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87820, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa18be8f-33a9-4fdb-8eec-026753a094e1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87820, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "副词，表示出乎预料，与所说的情理相反。", "primary_collocate": null, "pronunciation": "fǎn ér", "ipa": "fan˨˩˦ ɚ˧˥", "syllable_count": 2, "sentences": [{"text": "他不但没生气，反而笑了。", "target_word": "反而", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "下了雪，天气反而没那么冷了。", "target_word": "反而", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师批评了他，他反而很高兴。", "target_word": "反而", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "吃了很多，她反而觉得更饿了。", "target_word": "反而", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "雨停了，路上的人反而少了。", "target_word": "反而", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他有钱了，生活反而不快乐了。", "target_word": "反而", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "价格降了，买的人反而少了。", "target_word": "反而", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我道歉了，她反而更生气了。", "target_word": "反而", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "比赛输了，大家反而更努力练习。", "target_word": "反而", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这家店东西很便宜，客人反而不多。", "target_word": "反而", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "通用", "sense_fingerprint": "出乎预料，与常理相反", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5e7b4bed-94d6-4b97-9460-5a5161d44bdc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87820, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "反而", "is_correct": true, "explanation": "正确：「反而」表示出乎预料，与“不但没生气”的递进语境相符。"}, {"text": "果然", "is_correct": false, "explanation": "语义：「果然」表示符合预料，与“不但没生气”的语境不符。"}, {"text": "当然", "is_correct": false, "explanation": "语义：「当然」表示理所当然，与前句的出乎意料不符。"}, {"text": "一定", "is_correct": false, "explanation": "搭配：「一定」表示必然，与“没生气”的否定语境不搭配。"}], "explanations": {"反而": "正确：「反而」表示出乎预料，与“不但没生气”的递进语境相符。", "果然": "语义：「果然」表示符合预料，与“不但没生气”的语境不符。", "当然": "语义：「当然」表示理所当然，与前句的出乎意料不符。", "一定": "搭配：「一定」表示必然，与“没生气”的否定语境不搭配。"}, "sentence_index": 0, "correct_answer": "反而"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他每天跑步，身体反而很好。", "explanation": "这里应该用〈果然〉。坚持跑步身体好是预料之中，「反而」表示相反，不能用于此。"}, {"text": "我喜欢音乐，她反而也喜欢。", "explanation": "这里不能用〈反而〉。「反而」表示结果与预料相反，这里两人喜好相同，是并列关系，没有相反的结果，所以不能用「反而」。"}, {"text": "他一直努力，成绩反而很好。", "explanation": "这里应该用〈自然〉。努力后成绩好是自然的，「反而」表示与常理相反，不能用于此。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa18be8f-33a9-4fdb-8eec-026753a094e1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87820, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "反而", "is_correct": true, "explanation": "正确：「反而」表示与“降价”的预期相反，符合语境。"}, {"text": "本来", "is_correct": false, "explanation": "语义：「本来」表示原先的情况，与“降了”之后的变化不符。"}, {"text": "一直", "is_correct": false, "explanation": "搭配：「一直」表示持续，与“少了”这种变化不搭配。"}, {"text": "正在", "is_correct": false, "explanation": "搭配：「正在」表示进行中，与“少了”这种结果不搭配。"}], "explanations": {"反而": "正确：「反而」表示与“降价”的预期相反，符合语境。", "本来": "语义：「本来」表示原先的情况，与“降了”之后的变化不符。", "一直": "搭配：「一直」表示持续，与“少了”这种变化不搭配。", "正在": "搭配：「正在」表示进行中，与“少了”这种结果不搭配。"}, "sentence_index": 6, "correct_answer": "反而"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他成绩很好，老师反而表扬了他。", "explanation": "这里应该用〈于是〉。成绩好而受表扬是顺理成章的因果，「反而」表示与预料相反，这里不能用，应表示因果的「于是」。"}, {"text": "他吃完饭，反而去洗碗了。", "explanation": "这里应该用〈随后〉。吃完饭后去洗碗是先后发生的动作，「反而」表示与预料相反，这里不能用，应表示先后的「随后」。"}, {"text": "他一向很认真，学习反而很好。", "explanation": "这里不能用〈反而〉。「反而」表示与预料相反，而认真带来好成绩是本来如此，没有相反的结果，所以应去掉「反而」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa18be8f-33a9-4fdb-8eec-026753a094e1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87820, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他越解释，我更反而越糊涂。", "corrected_sentence": "他越解释，我反而越糊涂。", "error_description": "错误：「我更反而越糊涂」中「反而」前多了程度副词「更」。应为「我反而越糊涂」，「反而」前不能加「更」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa18be8f-33a9-4fdb-8eec-026753a094e1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87820, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们努力练习，结果更反而输了。", "corrected_sentence": "他们努力练习，结果反而输了。", "error_description": "错误：「结果更反而输了」中「反而」前多了程度副词「更」。应为「结果反而输了」，「反而」前不能加「更」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa18be8f-33a9-4fdb-8eec-026753a094e1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
