INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87821, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "property", "definition": "灰色是像灰尘、像下雨天的天空那样的颜色。", "primary_collocate": null, "pronunciation": "huī sè", "ipa": "xweɪ˥ sɤ˥˩", "syllable_count": 2, "sentences": [{"text": "下雨天，天空是灰色的。", "target_word": "灰色", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他穿了一件灰色的外套。", "target_word": "灰色", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "灰色的小猫睡在椅子上。", "target_word": "灰色", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这面墙是灰色的，有点像灰尘。", "target_word": "灰色", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天空变成了灰色，快要下雨了。", "target_word": "灰色", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我喜欢灰色，不喜欢红色。", "target_word": "灰色", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "灰色的云飘过城市上空。", "target_word": "灰色", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她的灰色围巾很旧了。", "target_word": "灰色", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大雨前，河水也变成了灰色。", "target_word": "灰色", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "雨后的路面是灰色的。", "target_word": "灰色", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "浅灰色", "label": "复合"}, {"form": "深灰色", "label": "复合"}], "register": "中性", "sense_fingerprint": "像灰尘或阴雨天天空的颜色", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ac8ff967-745b-40e1-9201-f6f0972c5a6d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87821, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "灰色", "is_correct": true, "explanation": "正确：阴雨天的天空呈现的正是灰色。"}, {"text": "红色", "is_correct": false, "explanation": "语义：下雨天的天空不会是红色，与“下雨天”冲突。"}, {"text": "绿色", "is_correct": false, "explanation": "语义：天空不呈绿色，与阴雨天的颜色不符。"}, {"text": "金色", "is_correct": false, "explanation": "搭配：“金色”的天空多见于日落，不与“下雨天”搭配。"}], "explanations": {"灰色": "正确：阴雨天的天空呈现的正是灰色。", "红色": "语义：下雨天的天空不会是红色，与“下雨天”冲突。", "绿色": "语义：天空不呈绿色，与阴雨天的颜色不符。", "金色": "搭配：“金色”的天空多见于日落，不与“下雨天”搭配。"}, "sentence_index": 0, "correct_answer": "灰色"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这支笔的重量很灰色，拿在手里很轻。", "explanation": "“灰色”不能用来形容重量；这里应用〈轻〉，如「重量很轻」。"}, {"text": "这碗汤的味道很灰色，喝一口就停不下来。", "explanation": "“灰色”只用来说颜色，不能形容味道；这里应用〈鲜美〉，如「味道很鲜美」。"}, {"text": "他跑步的速度很灰色，一下子就超过了所有人。", "explanation": "“灰色”不能形容速度；这里应用〈快〉，如「速度很快」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f7b918d-c73d-4c78-b735-3ef7235ac0cb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87821, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "灰色", "is_correct": true, "explanation": "正确：阴云多呈灰色，与“飘过城市上空”的描述相符。"}, {"text": "蓝色", "is_correct": false, "explanation": "语义：云层多为灰白或灰暗，不呈蓝色，与常见的云色不符。"}, {"text": "紫色", "is_correct": false, "explanation": "语义：普通的云不会是紫色，除非特殊光照，这里不符合常识。"}, {"text": "粉色", "is_correct": false, "explanation": "搭配：“粉色”多用于花朵或装饰，不说“粉色的云”飘过城市上空。"}], "explanations": {"灰色": "正确：阴云多呈灰色，与“飘过城市上空”的描述相符。", "蓝色": "语义：云层多为灰白或灰暗，不呈蓝色，与常见的云色不符。", "紫色": "语义：普通的云不会是紫色，除非特殊光照，这里不符合常识。", "粉色": "搭配：“粉色”多用于花朵或装饰，不说“粉色的云”飘过城市上空。"}, "sentence_index": 6, "correct_answer": "灰色"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这次考试的成绩很灰色，老师很满意。", "explanation": "“灰色”是颜色词，不能用来形容成绩；这里应用〈优秀〉，如「成绩很优秀」。"}, {"text": "这道题很灰色，我一下子就做出来了。", "explanation": "“灰色”不能用来形容题目的难易；这里应用〈简单〉，如「题目很简单」。"}, {"text": "他的个子很灰色，站在人群里很显眼。", "explanation": "“灰色”不能用来形容个子；这里应用〈高〉，如「个子很高」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f7b918d-c73d-4c78-b735-3ef7235ac0cb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87821, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这是一个灰色，很特别。", "corrected_sentence": "这是一种灰色，很特别。", "error_description": "量词错误：“灰色”作名词指一种颜色，应用“种”，“个”不用于颜色，“一个灰色”应改为“一种灰色”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f7b918d-c73d-4c78-b735-3ef7235ac0cb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87821, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他最喜欢一个灰色。", "corrected_sentence": "他最喜欢一种灰色。", "error_description": "量词错误：“灰色”作名词指一种颜色，应用“种”，“个”不用于颜色，“一个灰色”应改为“一种灰色”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f7b918d-c73d-4c78-b735-3ef7235ac0cb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
