INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87822, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "property", "definition": "介于黑色和白色之间的颜色。", "primary_collocate": null, "pronunciation": "huī sè", "ipa": "xweɪ˥ sɤ˥˩", "syllable_count": 2, "sentences": [{"text": "把黑色和白色放在一起，就是灰色。", "target_word": "灰色", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "黑色加白色，会变成灰色。", "target_word": "灰色", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "画画时，我用黑色和白色调出灰色。", "target_word": "灰色", "complexity_tier": "T3", "furigana": "huà huà shí, wǒ yòng hēi sè hé bái sè tiáo chū huī sè.", "sentence_source": "generated"}, {"text": "这张照片没有彩色，只有黑色、白色和灰色。", "target_word": "灰色", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "灰色比黑色浅，比白色深。", "target_word": "灰色", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的西装是灰色的，不太黑。", "target_word": "灰色", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请在白纸上涂灰色，不要涂黑色。", "target_word": "灰色", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想买灰色的鞋，黑色的太深了。", "target_word": "灰色", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "黑白照片里有很多灰色。", "target_word": "灰色", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说，灰色在黑色和白色中间。", "target_word": "灰色", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "浅灰色", "label": "复合"}, {"form": "深灰色", "label": "复合"}], "register": "中性", "sense_fingerprint": "介于黑色和白色之间的颜色", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ac8ff967-745b-40e1-9201-f6f0972c5a6d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87822, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "灰色", "is_correct": true, "explanation": "正确：黑色和白色混合得到的正是介于两者之间的灰色。"}, {"text": "黑色", "is_correct": false, "explanation": "语义：黑色和白色放在一起不会变成黑色，与“就是”的说法矛盾。"}, {"text": "白色", "is_correct": false, "explanation": "语义：黑色和白色放在一起不会变成白色，与句子的意思不符。"}, {"text": "彩色", "is_correct": false, "explanation": "搭配：“彩色”指多种颜色并存，不与“黑色和白色”这类无彩色的组合搭配。"}], "explanations": {"灰色": "正确：黑色和白色混合得到的正是介于两者之间的灰色。", "黑色": "语义：黑色和白色放在一起不会变成黑色，与“就是”的说法矛盾。", "白色": "语义：黑色和白色放在一起不会变成白色，与句子的意思不符。", "彩色": "搭配：“彩色”指多种颜色并存，不与“黑色和白色”这类无彩色的组合搭配。"}, "sentence_index": 0, "correct_answer": "灰色"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个孩子写的字很灰色，老师一看就笑了。", "explanation": "“灰色”只用来说颜色，不能用来形容字迹；这里应用〈工整〉，如「字写得很工整」。"}, {"text": "这道菜的味道很灰色，很好吃。", "explanation": "“灰色”不能用来形容味道；这里应用〈鲜美〉，如「味道很鲜美」。"}, {"text": "这件衣服的价格很灰色，我买得起。", "explanation": "“灰色”不能用来形容价格；这里应用〈便宜〉，如「价格很便宜」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f7b918d-c73d-4c78-b735-3ef7235ac0cb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87822, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "灰色", "is_correct": true, "explanation": "正确：白纸上涂灰色，与后半句“不要涂黑色”相呼应。"}, {"text": "色调", "is_correct": false, "explanation": "搭配：“涂”后不接“色调”，色调指色彩的整体倾向，不是可以涂的颜料。"}, {"text": "墨色", "is_correct": false, "explanation": "语义：墨色就是黑色，与“不要涂黑色”矛盾。"}, {"text": "黑白", "is_correct": false, "explanation": "语义：“黑白”含有黑色，与“不要涂黑色”矛盾。"}], "explanations": {"灰色": "正确：白纸上涂灰色，与后半句“不要涂黑色”相呼应。", "色调": "搭配：“涂”后不接“色调”，色调指色彩的整体倾向，不是可以涂的颜料。", "墨色": "语义：墨色就是黑色，与“不要涂黑色”矛盾。", "黑白": "语义：“黑白”含有黑色，与“不要涂黑色”矛盾。"}, "sentence_index": 6, "correct_answer": "灰色"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个西瓜的甜度很灰色，大家都很喜欢。", "explanation": "“灰色”是颜色词，不能用来形容甜度；这里应用〈高〉，如「甜度很高」。"}, {"text": "这次考试的难度很灰色，大家都做得很顺利。", "explanation": "“灰色”不能用来形容难度；这里应用〈低〉，如「难度很低」。"}, {"text": "他的力气很灰色，一个人就能搬动大箱子。", "explanation": "“灰色”不能用来形容力气；这里应用〈大〉，如「力气很大」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f7b918d-c73d-4c78-b735-3ef7235ac0cb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87822, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这幅画的背景是一个灰色。", "corrected_sentence": "这幅画的背景是一种灰色。", "error_description": "量词错误：“灰色”作名词指一种颜色，应用“种”，“个”不用于颜色，“一个灰色”应改为“一种灰色”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f7b918d-c73d-4c78-b735-3ef7235ac0cb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87822, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "雨后的路面是一个灰色。", "corrected_sentence": "雨后的路面是一种灰色。", "error_description": "量词错误：“灰色”作名词指一种颜色，应用“种”，“个”不用于颜色，“一个灰色”应改为“一种灰色”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f7b918d-c73d-4c78-b735-3ef7235ac0cb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
