INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87834, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "横躺下来；竖立的东西横卧下来。", "primary_collocate": null, "pronunciation": "dǎo", "ipa": "tau˨˩˦", "syllable_count": 1, "sentences": [{"text": "他累得一回家就倒在沙发上了。", "target_word": "倒", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我太困了，倒在床上就睡着了。", "target_word": "倒", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子玩累了，倒在妈妈怀里睡了。", "target_word": "倒", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "夏天太热，他把凉席铺在地上，倒在上面就睡着了。", "target_word": "倒", "complexity_tier": "T3", "furigana": "Xià tiān tài rè, tā bǎ liáng xí pū zài dì shàng, dǎo zài shàng miàn jiù shuì zháo le.", "sentence_source": "generated"}, {"text": "小猫玩累了，在阳光下一倒，很快就睡着了。", "target_word": "倒", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他向后一倒，躺在草地上看天。", "target_word": "倒", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "看完比赛，他倒在椅子上，一动也不想动。", "target_word": "倒", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "稻子被雨打得倒在田里了。", "target_word": "倒", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "麦子倒在地里，农民很着急。", "target_word": "倒", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他喝了药，倒在床上休息。", "target_word": "倒", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "倒了", "label": "完成体"}, {"form": "倒下", "label": "复合词"}], "register": "通用", "sense_fingerprint": "身体或竖立的东西顺势横躺下来、横卧", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 8 above tier T1: 3 words above tier T1 (max 2): 麦子 (Zipf 3.39), 地里 (Zipf 3.34), 着急 (Zipf 3.93)']::text[], '410cbcc6-88e5-4dbf-9766-d970c97f3598') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87834, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "倒", "is_correct": true, "explanation": "正确答案：倒 dǎo，指身体或竖立的东西横躺下来。"}, {"text": "到", "is_correct": false, "explanation": "dào（第四声）与 dǎo（第三声）声调不同，到表示抵达。"}, {"text": "刀", "is_correct": false, "explanation": "dāo（第一声）与 dǎo（第三声）声调不同，刀是切割的工具。"}, {"text": "讨", "is_correct": false, "explanation": "tǎo 与 dǎo 的声母不同（送气 t／不送气 d），讨指索取或讨论。"}, {"text": "打", "is_correct": false, "explanation": "dǎ 与 dǎo 的韵母不同（少了 o），打指击打。"}], "explanations": {"倒": "正确答案：倒 dǎo，指身体或竖立的东西横躺下来。", "到": "dào（第四声）与 dǎo（第三声）声调不同，到表示抵达。", "刀": "dāo（第一声）与 dǎo（第三声）声调不同，刀是切割的工具。", "讨": "tǎo 与 dǎo 的声母不同（送气 t／不送气 d），讨指索取或讨论。", "打": "dǎ 与 dǎo 的韵母不同（少了 o），打指击打。"}, "sentence_index": null, "correct_answer": "倒"}, "level_3": {"options": [{"text": "倒", "is_correct": true, "explanation": "正确：“一回家就倒在沙发上了”中，倒指身体横躺下来。"}, {"text": "唱", "is_correct": false, "explanation": "语义：唱是唱歌，与累了回家后躺下的语境不符。"}, {"text": "写", "is_correct": false, "explanation": "语义：写是书写，与回家后躺在沙发上的语境不符。"}, {"text": "抱", "is_correct": false, "explanation": "配价：“抱”要带宾语，不能说“抱在沙发上”。"}], "explanations": {"倒": "正确：“一回家就倒在沙发上了”中，倒指身体横躺下来。", "唱": "语义：唱是唱歌，与累了回家后躺下的语境不符。", "写": "语义：写是书写，与回家后躺在沙发上的语境不符。", "抱": "配价：“抱”要带宾语，不能说“抱在沙发上”。"}, "sentence_index": 0, "correct_answer": "倒"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他倒了一句话。", "explanation": "这里应该用〈说〉。“说一句话”是固定说法，说是用语言表达；倒指横躺下来或液体倾出，不能表示说话。"}, {"text": "他把孩子倒在床上睡觉了。", "explanation": "这里应该用〈放〉。“放”表示把别人或东西安置到某处，倒指身体自己横躺下来，不能用来指使别人躺下。"}, {"text": "他倒给我一本书。", "explanation": "这里应该用〈送〉。送是把东西交给别人，“送我一本书”是正常说法；倒指横躺或倾倒，不能表示给人东西。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3d1a9c34-0345-46ff-8cb2-0810e91fa327') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87834, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "倒", "is_correct": true, "explanation": "正确答案：倒 dǎo，指身体或竖立的东西横躺下来。"}, {"text": "道", "is_correct": false, "explanation": "dào（第四声）与 dǎo（第三声）声调不同，道是道路。"}, {"text": "稻", "is_correct": false, "explanation": "dào 与 dǎo 的声调不同，稻是水稻。"}, {"text": "老", "is_correct": false, "explanation": "lǎo 与 dǎo 的声母不同（l／d），老指年纪大。"}], "explanations": {"倒": "正确答案：倒 dǎo，指身体或竖立的东西横躺下来。", "道": "dào（第四声）与 dǎo（第三声）声调不同，道是道路。", "稻": "dào 与 dǎo 的声调不同，稻是水稻。", "老": "lǎo 与 dǎo 的声母不同（l／d），老指年纪大。"}, "sentence_index": null, "correct_answer": "倒"}, "level_3": {"options": [{"text": "倒", "is_correct": true, "explanation": "正确：“看完比赛，他倒在椅子上”中，倒指身体横躺或靠下。"}, {"text": "游", "is_correct": false, "explanation": "语义：游是在水中移动，与看完比赛后坐在椅子上的语境不符。"}, {"text": "跳", "is_correct": false, "explanation": "语义：跳是跃起，与“一动也不想动”的语境矛盾。"}, {"text": "卖", "is_correct": false, "explanation": "配价：“卖”要带宾语，不能说“卖在椅子上”。"}], "explanations": {"倒": "正确：“看完比赛，他倒在椅子上”中，倒指身体横躺或靠下。", "游": "语义：游是在水中移动，与看完比赛后坐在椅子上的语境不符。", "跳": "语义：跳是跃起，与“一动也不想动”的语境矛盾。", "卖": "配价：“卖”要带宾语，不能说“卖在椅子上”。"}, "sentence_index": 6, "correct_answer": "倒"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他把手倒起来。", "explanation": "这里应该用〈举〉。举是向上抬起，手可以举起；倒指横躺下来或竖立的东西倒下，不能表示把手往上抬。"}, {"text": "他倒好了自行车。", "explanation": "这里应该用〈修〉。修是把坏了的东西弄好，自行车可以修；倒指横躺下来或液体倾出，不能表示修理。"}, {"text": "他把老人倒起来坐好。", "explanation": "这里应该用〈扶〉。扶是用手使人站起或坐正，倒不能表示用手帮人坐起。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3d1a9c34-0345-46ff-8cb2-0810e91fa327') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87834, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "孩子玩了一下午，倒了在草地上就不动了。", "corrected_sentence": "孩子玩了一下午，倒在草地上就不动了。", "error_description": "“了”位置错误：“了”不能插在“倒”和“在”之间，应放在句末。错误形式是“倒了在草地上”，正确形式是“倒在草地上”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3d1a9c34-0345-46ff-8cb2-0810e91fa327') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87834, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他喝了酒，一进门就倒椅子上了。", "corrected_sentence": "他喝了酒，一进门就倒在椅子上了。", "error_description": "介词错误：处所“椅子上”前漏掉介词“在”，应为“倒在椅子上”。错误形式是“倒椅子上了”，正确形式是“倒在椅子上了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3d1a9c34-0345-46ff-8cb2-0810e91fa327') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
