INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87835, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "安装是把设备或软件装配、设置好，使其能够正常使用。", "primary_collocate": null, "pronunciation": "ān zhuāng", "ipa": "an˥ ʈʂwɑŋ˥", "syllable_count": 2, "sentences": [{"text": "工人今天来我家安装空调。", "target_word": "安装", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想在手机上安装一个新软件。", "target_word": "安装", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "师傅安装好了热水器。", "target_word": "安装", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这台电脑还没有安装游戏。", "target_word": "安装", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把新灯安装在房间中间。", "target_word": "安装", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "安装这个书架很简单，只要十分钟。", "target_word": "安装", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你会安装这个小机器吗？", "target_word": "安装", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸安装过网络，所以他会修。", "target_word": "安装", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校门口安装了新的门。", "target_word": "安装", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "安装完以后，请试一试能不能用。", "target_word": "安装", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "安装了", "label": "体标"}, {"form": "安装过", "label": "体标"}, {"form": "安装包", "label": "复合"}, {"form": "安裝", "label": "繁体"}], "register": "中性", "sense_fingerprint": "装配设备或软件，使其能正常使用", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2629cfaa-ecb6-48f0-80ae-066a0850e85a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87835, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "安装", "is_correct": true, "explanation": "“安装”指把空调装好使其能用，工人来家里装空调符合语境。"}, {"text": "唱", "is_correct": false, "explanation": "搭配：“唱”接歌曲，不接家电。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：“吃”不接家电作宾语。"}, {"text": "说", "is_correct": false, "explanation": "配价：“说”接话语，不能以空调为对象。"}], "explanations": {"安装": "“安装”指把空调装好使其能用，工人来家里装空调符合语境。", "唱": "搭配：“唱”接歌曲，不接家电。", "吃": "搭配：“吃”不接家电作宾语。", "说": "配价：“说”接话语，不能以空调为对象。"}, "sentence_index": 0, "correct_answer": "安装"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他把书安装在书架上。", "explanation": "这里应该用〈放〉。“安装”指把设备装好使其能用，书放在书架上只需“放”。"}, {"text": "我在电脑上安装了密码。", "explanation": "这里应该用〈设置〉。“安装”用于设备或程序，密码要用“设置”。"}, {"text": "电脑把文件安装在硬盘里。", "explanation": "这里应该用〈储存〉。“安装”针对设备，文件存入硬盘要用“储存”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '02715c0c-42fc-4b33-851a-a1d47916bb2f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87835, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "安装", "is_correct": true, "explanation": "“安装”指把东西装好使其能用，“你会安装这个小机器吗”符合语境。"}, {"text": "跳", "is_correct": false, "explanation": "搭配：“跳”不以机器作宾语，“跳这个小机器”不成立。"}, {"text": "笑", "is_correct": false, "explanation": "配价：“笑”是不及物动词，不能带“机器”作宾语。"}, {"text": "哭", "is_correct": false, "explanation": "配价：“哭”是不及物动词，不能带“机器”作宾语。"}], "explanations": {"安装": "“安装”指把东西装好使其能用，“你会安装这个小机器吗”符合语境。", "跳": "搭配：“跳”不以机器作宾语，“跳这个小机器”不成立。", "笑": "配价：“笑”是不及物动词，不能带“机器”作宾语。", "哭": "配价：“哭”是不及物动词，不能带“机器”作宾语。"}, "sentence_index": 6, "correct_answer": "安装"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "请把水安装进杯子里。", "explanation": "这里应该用〈倒〉。“安装”针对设备器材，把水倒进杯子要用“倒”。"}, {"text": "他把衣服安装好，放进柜子里。", "explanation": "这里应该用〈整理〉。“安装”针对设备器材，衣服要用“整理”。"}, {"text": "他每天早上安装房间。", "explanation": "这里应该用〈打扫〉。“安装”针对设备器材，房间要用“打扫”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '02715c0c-42fc-4b33-851a-a1d47916bb2f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87835, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这台机器已经安装了好。", "corrected_sentence": "这台机器已经安装好了。", "error_description": "错误：结果补语“好”应紧跟动词，“了”放在句末，应说“安装好了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '02715c0c-42fc-4b33-851a-a1d47916bb2f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87835, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个软件我安装着三次。", "corrected_sentence": "这个软件我安装过三次。", "error_description": "错误：表示经历过几次时要用“过”，不能用“着”。“着”表示动作的持续或状态，不能与次数连用，应说“安装过三次”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '02715c0c-42fc-4b33-851a-a1d47916bb2f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87836, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "拆卸", "is_correct": true, "explanation": "“拆卸”与“安装”相反，指把设备从某处拆下来。"}, {"text": "修理", "is_correct": false, "explanation": "修理是把坏的东西弄好，与安装不是反义关系。"}, {"text": "制造", "is_correct": false, "explanation": "制造是做出产品，与安装不是反义关系。"}, {"text": "购买", "is_correct": false, "explanation": "购买是付钱得到东西，与安装不是反义关系。"}], "correct_answer": "拆卸", "explanations": {"拆卸": "“拆卸”与“安装”相反，指把设备从某处拆下来。", "修理": "修理是把坏的东西弄好，与安装不是反义关系。", "制造": "制造是做出产品，与安装不是反义关系。", "购买": "购买是付钱得到东西，与安装不是反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '02715c0c-42fc-4b33-851a-a1d47916bb2f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87836, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "拆卸", "is_correct": true, "explanation": "“拆卸”与“安装”相反，指把设备从某处拆下来。"}, {"text": "生产", "is_correct": false, "explanation": "生产是造出产品，与安装不是反义关系。"}, {"text": "出售", "is_correct": false, "explanation": "出售是卖出东西，与安装不是反义关系。"}, {"text": "搬运", "is_correct": false, "explanation": "搬运是移动东西，与安装不是反义关系。"}], "correct_answer": "拆卸", "explanations": {"拆卸": "“拆卸”与“安装”相反，指把设备从某处拆下来。", "生产": "生产是造出产品，与安装不是反义关系。", "出售": "出售是卖出东西，与安装不是反义关系。", "搬运": "搬运是移动东西，与安装不是反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '02715c0c-42fc-4b33-851a-a1d47916bb2f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87836, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "把机器、器材等按一定的方法固定在某处。", "primary_collocate": null, "pronunciation": "ān zhuāng", "ipa": "an˥ ʈʂwɑŋ˥", "syllable_count": 2, "sentences": [{"text": "工人在楼顶安装太阳能板。", "target_word": "安装", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司在每层楼都安装了灭火器。", "target_word": "安装", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们正在安装新的机器。", "target_word": "安装", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "按图纸安装这台设备很重要。", "target_word": "安装", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "师傅安装窗户时要很小心。", "target_word": "安装", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工厂里安装着十台大机器。", "target_word": "安装", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请按说明书的方法安装电池。", "target_word": "安装", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "安装电梯需要专业的工人。", "target_word": "安装", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们在路边安装了新路灯。", "target_word": "安装", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个摄像头安装在门口的墙上。", "target_word": "安装", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "安装了", "label": "体标"}, {"form": "安装过", "label": "体标"}, {"form": "安装工", "label": "复合"}, {"form": "安裝", "label": "繁体"}], "register": "中性", "sense_fingerprint": "把机器、器材按一定方法固定在某处", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2629cfaa-ecb6-48f0-80ae-066a0850e85a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87836, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "安装", "is_correct": true, "explanation": "“安装”指把太阳能板固定在某处使用，工人在楼顶装太阳能板符合语境。"}, {"text": "写", "is_correct": false, "explanation": "语义：“写”的对象是文字，太阳能板不能写。"}, {"text": "弹", "is_correct": false, "explanation": "搭配：“弹”接乐器，不接太阳能板。"}, {"text": "唱", "is_correct": false, "explanation": "搭配：“唱”接歌曲，不接设备。"}], "explanations": {"安装": "“安装”指把太阳能板固定在某处使用，工人在楼顶装太阳能板符合语境。", "写": "语义：“写”的对象是文字，太阳能板不能写。", "弹": "搭配：“弹”接乐器，不接太阳能板。", "唱": "搭配：“唱”接歌曲，不接设备。"}, "sentence_index": 0, "correct_answer": "安装"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "政府把灾民安装在临时帐篷里。", "explanation": "这里应该用〈安置〉。“安装”指固定机器器材，安排灾民的住处要用“安置”。"}, {"text": "他们用彩纸安装房间，让晚会很热闹。", "explanation": "这里应该用〈装饰〉。“安装”指固定机器器材，布置房间要用“装饰”。"}, {"text": "他把花安装在桌子上。", "explanation": "这里应该用〈摆〉。“安装”指固定机器器材，花放在桌上只需“摆”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '02715c0c-42fc-4b33-851a-a1d47916bb2f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87836, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "安装", "is_correct": true, "explanation": "“安装”指按方法把电池装好使其能用，“请按说明书的方法安装电池”符合语境。"}, {"text": "点", "is_correct": false, "explanation": "语义：“点”指点燃，电池不能这样处理，与按说明书安装不符。"}, {"text": "煮", "is_correct": false, "explanation": "语义：电池不能煮，与按说明书安装不符。"}, {"text": "浇", "is_correct": false, "explanation": "搭配：“浇”接植物或液体，不接电池。"}], "explanations": {"安装": "“安装”指按方法把电池装好使其能用，“请按说明书的方法安装电池”符合语境。", "点": "语义：“点”指点燃，电池不能这样处理，与按说明书安装不符。", "煮": "语义：电池不能煮，与按说明书安装不符。", "浇": "搭配：“浇”接植物或液体，不接电池。"}, "sentence_index": 6, "correct_answer": "安装"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "农民在田里安装了很多玉米。", "explanation": "这里应该用〈种〉。“安装”指固定机器器材，玉米要用“种”。"}, {"text": "他在黑板上安装了三行字。", "explanation": "这里应该用〈写〉。“安装”指固定机器器材，字要用“写”。"}, {"text": "我把毛巾安装在浴室的门上。", "explanation": "这里应该用〈挂〉。“安装”针对机器器材，毛巾挂在门上要用“挂”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '02715c0c-42fc-4b33-851a-a1d47916bb2f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87836, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "工人把灯安装天花板上。", "corrected_sentence": "工人把灯安装在天花板上。", "error_description": "错误：“安装”后缺介词“在”，应说“安装在天花板上”，用“在”引出安装的处所。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '02715c0c-42fc-4b33-851a-a1d47916bb2f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87836, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这家工厂安装过很多只机器。", "corrected_sentence": "这家工厂安装过很多台机器。", "error_description": "量词错误：“机器”的量词应用“台”，不用“只”（“只”多用于动物或小东西）。错误形式“很多只机器”，正确形式“很多台机器”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '02715c0c-42fc-4b33-851a-a1d47916bb2f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
