INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87858, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "没有固定形状和体积的物质；也指空气。", "primary_collocate": null, "pronunciation": "qì", "ipa": "tɕʰi˥˩", "syllable_count": 1, "sentences": [{"text": "自行车的轮胎里没有气了。", "target_word": "气", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "车胎漏了，里面的气慢慢跑光了。", "target_word": "气", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "皮球里的气太少，跳不起来。", "target_word": "气", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我去加油站给轮胎打气。", "target_word": "气", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个瓶子里装的是气，不是水。", "target_word": "气", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "气没有固定的形状，会跑满整个房间。", "target_word": "气", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他把游泳圈里的气放掉了。", "target_word": "气", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "打开瓶盖，里面的气就跑出来了。", "target_word": "气", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "固体、液体、气，是物质的三种样子。", "target_word": "气", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "给篮球多充点气，它才跳得高。", "target_word": "气", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "气体", "label": "复合"}, {"form": "氣", "label": "繁体"}], "register": "中性", "sense_fingerprint": "气·没有固定形状的气体物质", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a298fe30-4cb1-44d1-ba83-8e5984f2584b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87858, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "气", "is_correct": true, "explanation": "气（qì）指没有固定形状和体积的气体物质，是正确答案。"}, {"text": "七", "is_correct": false, "explanation": "qī（第一声）与 qì（第四声）声调不同，意思是数字七。"}, {"text": "起", "is_correct": false, "explanation": "qǐ（第三声）与 qì（第四声）声调不同，意思是起来、站起。"}, {"text": "其", "is_correct": false, "explanation": "qí（第二声）与 qì（第四声）声调不同，意思是其他、他的。"}, {"text": "去", "is_correct": false, "explanation": "qù（第四声）与 qì（第四声）韵母不同，意思是去、离开。"}], "explanations": {"气": "气（qì）指没有固定形状和体积的气体物质，是正确答案。", "七": "qī（第一声）与 qì（第四声）声调不同，意思是数字七。", "起": "qǐ（第三声）与 qì（第四声）声调不同，意思是起来、站起。", "其": "qí（第二声）与 qì（第四声）声调不同，意思是其他、他的。", "去": "qù（第四声）与 qì（第四声）韵母不同，意思是去、离开。"}, "sentence_index": null, "correct_answer": "气"}, "level_3": {"options": [{"text": "气", "is_correct": true, "explanation": "正确。“没有气”指轮胎里的气体已经没有了。"}, {"text": "电", "is_correct": false, "explanation": "语义：轮胎里装的是气，不装电，句子说的是没有气。"}, {"text": "盐", "is_correct": false, "explanation": "语义：轮胎里不会装盐，句子说的是轮胎里的气体。"}, {"text": "字", "is_correct": false, "explanation": "搭配：“轮胎里没有……”后面要跟能充进轮胎的东西，“字”不能搭配。"}], "explanations": {"气": "正确。“没有气”指轮胎里的气体已经没有了。", "电": "语义：轮胎里装的是气，不装电，句子说的是没有气。", "盐": "语义：轮胎里不会装盐，句子说的是轮胎里的气体。", "字": "搭配：“轮胎里没有……”后面要跟能充进轮胎的东西，“字”不能搭配。"}, "sentence_index": 0, "correct_answer": "气"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "医生给病人输的是气，不是水。", "explanation": "这里应该用〈氧气〉。输给病人的气体要说“氧气”，“气”单独不能指氧气。"}, {"text": "这场演唱会的气很热烈，观众一直在尖叫。", "explanation": "这里应该用〈气氛〉。形容现场热烈的氛围要说“气氛”，“气”在这里不指这种氛围。"}, {"text": "他用了很大的气才把箱子抬起来。", "explanation": "这里应该用〈力气〉。表示用力的劲儿要说“力气”，“气”不能这样指力量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '73ed49ee-02fe-4815-a4f8-121fa8aa9f1c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87858, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "气", "is_correct": true, "explanation": "气（qì）指没有固定形状和体积的气体物质，是正确答案。"}, {"text": "戏", "is_correct": false, "explanation": "xì（第四声）与 qì（第四声）声母不同，意思是戏剧。"}, {"text": "期", "is_correct": false, "explanation": "qī（第一声）与 qì（第四声）声调不同，意思是时期。"}, {"text": "旗", "is_correct": false, "explanation": "qí（第二声）与 qì（第四声）声调不同，意思是旗子。"}, {"text": "趣", "is_correct": false, "explanation": "qù（第四声）与 qì（第四声）韵母不同，意思是趣味。"}], "explanations": {"气": "气（qì）指没有固定形状和体积的气体物质，是正确答案。", "戏": "xì（第四声）与 qì（第四声）声母不同，意思是戏剧。", "期": "qī（第一声）与 qì（第四声）声调不同，意思是时期。", "旗": "qí（第二声）与 qì（第四声）声调不同，意思是旗子。", "趣": "qù（第四声）与 qì（第四声）韵母不同，意思是趣味。"}, "sentence_index": null, "correct_answer": "气"}, "level_3": {"options": [{"text": "气", "is_correct": true, "explanation": "正确。“放掉的气”指游泳圈里的气体。"}, {"text": "书", "is_correct": false, "explanation": "语义：游泳圈里装的是气，不装书，句子说的是放掉的气。"}, {"text": "糖", "is_correct": false, "explanation": "语义：游泳圈里不会装糖，句子说的是放掉的是气体。"}, {"text": "歌", "is_correct": false, "explanation": "搭配：“放掉”的对象是能放出的东西，“歌”不能搭配“放掉”。"}], "explanations": {"气": "正确。“放掉的气”指游泳圈里的气体。", "书": "语义：游泳圈里装的是气，不装书，句子说的是放掉的气。", "糖": "语义：游泳圈里不会装糖，句子说的是放掉的是气体。", "歌": "搭配：“放掉”的对象是能放出的东西，“歌”不能搭配“放掉”。"}, "sentence_index": 6, "correct_answer": "气"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这锅汤的气很鲜，大家都喝光了。", "explanation": "这里应该用〈味道〉。汤的滋味要说“味道”，“气”不能这样形容汤的鲜美。"}, {"text": "他的气很温和，说话很慢。", "explanation": "这里应该用〈语气〉。说话的口吻要说“语气”，“气”单独不这样表示说话的温和。"}, {"text": "厨房里飘来阵阵气，很好闻。", "explanation": "这里应该用〈香气〉。食物的香味要说“香气”，“气”单独不表示这种香味。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '73ed49ee-02fe-4815-a4f8-121fa8aa9f1c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87858, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我给轮胎打了一只气。", "corrected_sentence": "我给轮胎打了一点气。", "error_description": "量词错误：“气”不能用个体量词“只”（“只”用于动物、器官等个体），应说“打了一点气”，不能说“打了一只气”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '73ed49ee-02fe-4815-a4f8-121fa8aa9f1c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87858, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他把游泳圈里的气吃掉了。", "corrected_sentence": "他把游泳圈里的气全放掉了。", "error_description": "搭配错误：“气”要说“放掉”，不能说“吃掉”，“吃掉气”说不通。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '73ed49ee-02fe-4815-a4f8-121fa8aa9f1c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87869, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "冷淡", "is_correct": true, "explanation": "冷淡：待人不热心、不亲切，与“热情”相对，是这个义项的反义词。"}, {"text": "清楚", "is_correct": false, "explanation": "清楚：形容清晰明白，与“热情”没有反义关系。"}, {"text": "平凡", "is_correct": false, "explanation": "平凡：形容普通、不出众，与“热情”没有反义关系。"}, {"text": "辛苦", "is_correct": false, "explanation": "辛苦：形容劳累、费力，与“热情”没有反义关系。"}], "correct_answer": "冷淡", "explanations": {"冷淡": "冷淡：待人不热心、不亲切，与“热情”相对，是这个义项的反义词。", "清楚": "清楚：形容清晰明白，与“热情”没有反义关系。", "平凡": "平凡：形容普通、不出众，与“热情”没有反义关系。", "辛苦": "辛苦：形容劳累、费力，与“热情”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '73ed49ee-02fe-4815-a4f8-121fa8aa9f1c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87869, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "冷淡", "is_correct": true, "explanation": "冷淡：待人不热心、不亲切，与“热情”相对，是这个义项的反义词。"}, {"text": "整齐", "is_correct": false, "explanation": "整齐：形容排列有序、不乱，与“热情”没有反义关系。"}, {"text": "狡猾", "is_correct": false, "explanation": "狡猾：形容人心眼多、不老实，与“热情”不是反义关系。"}, {"text": "明亮", "is_correct": false, "explanation": "明亮：形容光线充足或眼睛有神，与“热情”没有反义关系。"}], "correct_answer": "冷淡", "explanations": {"冷淡": "冷淡：待人不热心、不亲切，与“热情”相对，是这个义项的反义词。", "整齐": "整齐：形容排列有序、不乱，与“热情”没有反义关系。", "狡猾": "狡猾：形容人心眼多、不老实，与“热情”不是反义关系。", "明亮": "明亮：形容光线充足或眼睛有神，与“热情”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '73ed49ee-02fe-4815-a4f8-121fa8aa9f1c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87869, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "热情是对别人很好，让人觉得暖和。", "primary_collocate": null, "pronunciation": "rè qíng", "ipa": "ʐɤ˥˩ tɕʰiŋ˧˥", "syllable_count": 2, "sentences": [{"text": "他热情的话让我心里暖暖的。", "target_word": "热情", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老奶奶很热情，给我们倒了热茶。", "target_word": "热情", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他们一家人都很热情，我一点也不紧张。", "target_word": "热情", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她热情地抱了抱我，我觉得很温暖。", "target_word": "热情", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "在陌生的城市，大家都很热情，我很感动。", "target_word": "热情", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "邻居热情地请我们吃饭。", "target_word": "热情", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她说话很热情，像朋友一样。", "target_word": "热情", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "冬天里，他热情的问候让人觉得暖和。", "target_word": "热情", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "店员热情地给我们介绍了菜。", "target_word": "热情", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "朋友很热情，把最好的房间给了我。", "target_word": "热情", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "热情地", "label": "副词形式"}, {"form": "熱情", "label": "繁体"}], "register": "中性", "sense_fingerprint": "热情·对人很好、让人感到温暖", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a298fe30-4cb1-44d1-ba83-8e5984f2584b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87869, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "热情", "is_correct": true, "explanation": "正确。“热情的话”指对人亲切、让人感到温暖的话。"}, {"text": "冰冷", "is_correct": false, "explanation": "语义：冰冷的话不会让人心里暖，与“心里暖暖的”矛盾。"}, {"text": "粗鲁", "is_correct": false, "explanation": "语义：粗鲁的话让人不舒服，与“心里暖暖的”不合。"}, {"text": "高大", "is_correct": false, "explanation": "搭配：“高大”形容体型，不能修饰“话”。"}], "explanations": {"热情": "正确。“热情的话”指对人亲切、让人感到温暖的话。", "冰冷": "语义：冰冷的话不会让人心里暖，与“心里暖暖的”矛盾。", "粗鲁": "语义：粗鲁的话让人不舒服，与“心里暖暖的”不合。", "高大": "搭配：“高大”形容体型，不能修饰“话”。"}, "sentence_index": 0, "correct_answer": "热情"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "屋里生着火，很热情，我脱掉了外套。", "explanation": "这里应该用〈暖和〉。形容温度要说“暖和”，“热情”只形容人待人的态度。"}, {"text": "这条街晚上很热情，大家都来散步。", "explanation": "这里应该用〈热闹〉。形容街道人多、有生气要说“热闹”，“热情”不能形容街道。"}, {"text": "她的眼眶里涌出了热情，我也哭了。", "explanation": "这里应该用〈热泪〉。眼眶里流出的泪水要说“热泪”，“热情”不能指泪水。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '73ed49ee-02fe-4815-a4f8-121fa8aa9f1c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87869, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "热情", "is_correct": true, "explanation": "正确。“她说话很热情，像朋友一样”说明她说话亲切。"}, {"text": "生硬", "is_correct": false, "explanation": "语义：生硬的说话方式与“像朋友一样”不协调。"}, {"text": "瘦弱", "is_correct": false, "explanation": "体貌：“瘦弱”形容身体，不能用来形容说话的态度。"}, {"text": "呆板", "is_correct": false, "explanation": "语义：呆板和“像朋友一样”矛盾，说话不亲切。"}], "explanations": {"热情": "正确。“她说话很热情，像朋友一样”说明她说话亲切。", "生硬": "语义：生硬的说话方式与“像朋友一样”不协调。", "瘦弱": "体貌：“瘦弱”形容身体，不能用来形容说话的态度。", "呆板": "语义：呆板和“像朋友一样”矛盾，说话不亲切。"}, "sentence_index": 6, "correct_answer": "热情"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这场争论很热情，双方都不肯让步。", "explanation": "这里应该用〈激烈〉。争论的紧张程度要说“激烈”，“热情”只形容人的态度。"}, {"text": "天气很热情，我们都想去游泳。", "explanation": "这里应该用〈炎热〉。形容天气的热要说“炎热”，“热情”不能形容天气。"}, {"text": "他热情地咳嗽了几声，大家都很担心。", "explanation": "这里应该用〈剧烈〉。咳嗽的程度要说“剧烈”，“热情”不能形容身体的动作。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '73ed49ee-02fe-4815-a4f8-121fa8aa9f1c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87869, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这位大叔热情的给我们指了路。", "corrected_sentence": "这位大叔热情地给我们指了路。", "error_description": "结构助词错误：“热情”修饰动词“指”时要用“地”，应说“热情地给我们指路”，不说“热情的给我们指路”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '73ed49ee-02fe-4815-a4f8-121fa8aa9f1c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87869, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这家民宿的主人很特别热情，还帮我们搬行李。", "corrected_sentence": "这家民宿的主人特别热情，还帮我们搬行李。", "error_description": "程度副词重复错误：“特别”本身已表示程度，前面不能再加“很”；应说“特别热情”，不说“很特别热情”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '73ed49ee-02fe-4815-a4f8-121fa8aa9f1c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
