INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87882, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "职务", "is_correct": true, "explanation": "正确。职务：职位规定应做的工作，或所担任的工作岗位。"}, {"text": "迟误", "is_correct": false, "explanation": "chí（第二声）与 zhí（第二声）声母不同，意思是耽误。"}, {"text": "食物", "is_correct": false, "explanation": "shí（第二声）与 zhí（第二声）声母不同，意思是可以吃的东西。"}, {"text": "织物", "is_correct": false, "explanation": "zhī（第一声）与 zhí（第二声）声调不同，意思是纺织品。"}, {"text": "质物", "is_correct": false, "explanation": "zhì（第四声）与 zhí（第二声）声调不同，意思是抵押的东西。"}], "explanations": {"职务": "正确。职务：职位规定应做的工作，或所担任的工作岗位。", "迟误": "chí（第二声）与 zhí（第二声）声母不同，意思是耽误。", "食物": "shí（第二声）与 zhí（第二声）声母不同，意思是可以吃的东西。", "织物": "zhī（第一声）与 zhí（第二声）声调不同，意思是纺织品。", "质物": "zhì（第四声）与 zhí（第二声）声调不同，意思是抵押的东西。"}, "sentence_index": null, "correct_answer": "职务"}, "level_3": {"options": [{"text": "职务", "is_correct": true, "explanation": "正确。“履行自己的职务”指履行工作上应做的事，符合句意。"}, {"text": "工资", "is_correct": false, "explanation": "搭配：“履行”要与“职责”“义务”等搭配，不能说“履行工资”。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气不是人要履行的事，句意不通。"}, {"text": "座位", "is_correct": false, "explanation": "语义：座位不能被履行，句意不通。"}], "explanations": {"职务": "正确。“履行自己的职务”指履行工作上应做的事，符合句意。", "工资": "搭配：“履行”要与“职责”“义务”等搭配，不能说“履行工资”。", "天气": "语义：天气不是人要履行的事，句意不通。", "座位": "语义：座位不能被履行，句意不通。"}, "sentence_index": 0, "correct_answer": "职务"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这件衣服的职务是红色。", "explanation": "这里应该用〈颜色〉。职务指工作要做的事或岗位，不能表示颜色。"}, {"text": "他的职务是五千元。", "explanation": "这里应该用〈工资〉。职务指职位规定应做的工作或所担任的岗位，不能用来表示收入金额。"}, {"text": "这栋楼的职务是北京。", "explanation": "这里应该用〈住址〉。职务是工作上的事或岗位，不能表示地址。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6fcd30b9-9649-49b6-a32a-d303d4af5e0e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87882, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "职务", "is_correct": true, "explanation": "正确。职务：职位规定应做的工作，或所担任的工作岗位。"}, {"text": "实物", "is_correct": false, "explanation": "shí（第二声）与 zhí（第二声）声母不同，意思是实际的物品。"}, {"text": "时务", "is_correct": false, "explanation": "shí（第二声）与 zhí（第二声）只差声母（sh/zh），意思是当前的要务。"}, {"text": "织物", "is_correct": false, "explanation": "zhī（第一声）与 zhí（第二声）只差声调，意思是纺织品。"}], "explanations": {"职务": "正确。职务：职位规定应做的工作，或所担任的工作岗位。", "实物": "shí（第二声）与 zhí（第二声）声母不同，意思是实际的物品。", "时务": "shí（第二声）与 zhí（第二声）只差声母（sh/zh），意思是当前的要务。", "织物": "zhī（第一声）与 zhí（第二声）只差声调，意思是纺织品。"}, "sentence_index": null, "correct_answer": "职务"}, "level_3": {"options": [{"text": "职务", "is_correct": true, "explanation": "正确。“新的职务安排”指对工作岗位的安排，符合句意。"}, {"text": "体重", "is_correct": false, "explanation": "语义：“体重”是重量，不能用来安排，句意不通。"}, {"text": "鞋子", "is_correct": false, "explanation": "语义：“鞋子”是物品，不能作“安排”的对象。"}, {"text": "心情", "is_correct": false, "explanation": "搭配：“心情”一般不与“安排”搭配，不能说“新的心情安排”。"}], "explanations": {"职务": "正确。“新的职务安排”指对工作岗位的安排，符合句意。", "体重": "语义：“体重”是重量，不能用来安排，句意不通。", "鞋子": "语义：“鞋子”是物品，不能作“安排”的对象。", "心情": "搭配：“心情”一般不与“安排”搭配，不能说“新的心情安排”。"}, "sentence_index": 6, "correct_answer": "职务"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的职务是硕士。", "explanation": "这里应该用〈学历〉。职务指工作上要做的事或岗位，硕士是学历。"}, {"text": "他的职务是三十岁。", "explanation": "这里应该用〈年龄〉。职务不能用来表示岁数。"}, {"text": "他的职务是七十公斤。", "explanation": "这里应该用〈体重〉。职务不能用来表示体重。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6fcd30b9-9649-49b6-a32a-d303d4af5e0e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87882, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他担任了一把职务。", "corrected_sentence": "他担任了一个职务。", "error_description": "量词错误：“职务”的量词应为“个”，“把”多用于有柄的器物。应说“担任了一个职务”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6fcd30b9-9649-49b6-a32a-d303d4af5e0e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87882, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他担任这条职务已经五年了。", "corrected_sentence": "他担任这个职务已经五年了。", "error_description": "量词错误：“职务”的量词应为“个”，“条”用于细长的东西，“这条职务”应改为“这个职务”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6fcd30b9-9649-49b6-a32a-d303d4af5e0e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
