INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87884, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "副词，表示程度很深；大大。", "primary_collocate": null, "pronunciation": "dà wéi", "ipa": "ta˥˩ weɪ˧˥", "syllable_count": 2, "sentences": [{"text": "听到这个好消息，大家都大为高兴。", "target_word": "大为", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "看到考试成绩，老师大为吃惊。", "target_word": "大为", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "修了新路以后，这里的交通大为方便。", "target_word": "大为", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "吃了药以后，病人的情况大为好转。", "target_word": "大为", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "听了这句话，他心里大为不满。", "target_word": "大为", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "地铁开通后，路上的车大为减少。", "target_word": "大为", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "新工人来了以后，工作效率大为提高。", "target_word": "大为", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子哭个不停，客人大为不快。", "target_word": "大为", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "看到女儿考上大学，父母大为欣慰。", "target_word": "大为", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "长时间工作以后，他大为疲惫。", "target_word": "大为", "complexity_tier": "T3", "furigana": "cháng shíjiān gōngzuò yǐhòu, tā dà wéi pí bèi.", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面语", "sense_fingerprint": "程度副词，用在双音节动词或形容词前，表示程度很深、变化很大", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f8530ce5-0286-4987-b867-f019ea50f76c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87884, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "大为", "is_correct": true, "explanation": "正确：“大为”表示程度很深，修饰“高兴”，与原句一致。"}, {"text": "反而", "is_correct": false, "explanation": "语义：“反而”表示出乎意料的相反结果，与“好消息”引起高兴的语境矛盾。"}, {"text": "不", "is_correct": false, "explanation": "语义：“不”否定了“高兴”，与“听到这个好消息”的积极语境矛盾。"}, {"text": "极力", "is_correct": false, "explanation": "搭配：“极力”修饰努力去做的动作，不能修饰“高兴”这类心理状态。"}], "explanations": {"大为": "正确：“大为”表示程度很深，修饰“高兴”，与原句一致。", "反而": "语义：“反而”表示出乎意料的相反结果，与“好消息”引起高兴的语境矛盾。", "不": "语义：“不”否定了“高兴”，与“听到这个好消息”的积极语境矛盾。", "极力": "搭配：“极力”修饰努力去做的动作，不能修饰“高兴”这类心理状态。"}, "sentence_index": 0, "correct_answer": "大为"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他大为住在北京。", "explanation": "这里应该用〈长期〉。“大为”表示程度很深，不能修饰“住在北京”这样的状态；表示时间长要说“长期”。"}, {"text": "我周末大为去超市买东西。", "explanation": "这里应该用〈常常〉。“大为”表示程度很深，不修饰“去超市买东西”这类一般行为。"}, {"text": "他大为吃了三碗饭。", "explanation": "这里应该改为“吃得很多”，用补语表示数量多。“大为”表示程度很深，多用于变化或感受，不修饰“吃了三碗饭”这类动作。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '48c93dd2-8733-4a1a-82c1-dc57833b3687') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87884, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "大为", "is_correct": true, "explanation": "正确：“大为”表示效率提高的幅度很大，与原句一致。"}, {"text": "从不", "is_correct": false, "explanation": "语义：“从不”表示长期都不如此，与“新工人来了以后”这一事件矛盾。"}, {"text": "严格地", "is_correct": false, "explanation": "搭配：“严格地”强调按规范办事，不能修饰“提高”这种结果变化。"}, {"text": "处处", "is_correct": false, "explanation": "搭配：“处处”指各个地方，不能修饰“工作效率”这种抽象结果。"}], "explanations": {"大为": "正确：“大为”表示效率提高的幅度很大，与原句一致。", "从不": "语义：“从不”表示长期都不如此，与“新工人来了以后”这一事件矛盾。", "严格地": "搭配：“严格地”强调按规范办事，不能修饰“提高”这种结果变化。", "处处": "搭配：“处处”指各个地方，不能修饰“工作效率”这种抽象结果。"}, "sentence_index": 6, "correct_answer": "大为"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这几年，学校大为建了一座小楼。", "explanation": "这里应该用〈只〉。“大为”表示程度很深，不能修饰“建一座小楼”这样规模很小的事。"}, {"text": "他的病大为好了一点。", "explanation": "这里应该用〈稍微〉。“大为”表示程度很深，与“一点”表示的轻微程度相矛盾。"}, {"text": "这次活动大为来了几个观众。", "explanation": "这里应该用〈仅仅〉。“大为”表示程度很深，不能说明“来了几个”这样人数很少的情况。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '48c93dd2-8733-4a1a-82c1-dc57833b3687') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87884, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "会议以后，大家的想法大为的改变。", "corrected_sentence": "会议以后，大家的想法大为改变。", "error_description": "“大为”是副词，不能加“的”修饰动词“改变”：应说“大为改变”，不说“大为的改变”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '48c93dd2-8733-4a1a-82c1-dc57833b3687') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87884, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "新政策实施后，市场的价格很大为下降。", "corrected_sentence": "新政策实施后，市场的价格大为下降。", "error_description": "“大为”与“很”都表示程度，不能叠加使用：应说“大为下降”，不说“很大为下降”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '48c93dd2-8733-4a1a-82c1-dc57833b3687') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
