INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87887, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "态度是对人或事表现出来的样子、神情和做法。", "primary_collocate": null, "pronunciation": "tài dù", "ipa": "tʰaɪ̯˥˩ tu˥˩", "syllable_count": 2, "sentences": [{"text": "服务员的态度很好，我们都很满意。", "target_word": "态度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他说话的态度让我不高兴。", "target_word": "态度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师对学生的态度很和气。", "target_word": "态度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你这是什么态度？我在跟你说话呢！", "target_word": "态度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他笑着说话，态度非常友好。", "target_word": "态度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "店员态度不好，我就没买东西。", "target_word": "态度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她的态度一下子变冷了。", "target_word": "态度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你用友好的态度跟客人说话。", "target_word": "态度", "complexity_tier": "T3", "furigana": "Qǐng nǐ yòng yǒuhǎo de tàidu gēn kèrén shuōhuà.", "sentence_source": "generated"}, {"text": "医生的态度很认真，病人很放心。", "target_word": "态度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "弟弟态度不好，妈妈有点生气。", "target_word": "态度", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一种态度", "label": "量词"}, {"form": "態度", "label": "繁体"}, {"form": "工作态度", "label": "复合"}, {"form": "服务态度", "label": "复合"}], "register": "通用", "sense_fingerprint": "态度：对人对事表现出来的样子、神情和做法", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '84eaa279-90ef-4dbd-b39e-63b4c5dbbc90') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87887, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "态度", "is_correct": true, "explanation": "“态度”指对人对事表现出来的样子和做法，与“服务员的……很好，我们都很满意”相符。"}, {"text": "味道", "is_correct": false, "explanation": "语义：“味道”指食物或气味，不能说服务员的味道很好。"}, {"text": "身高", "is_correct": false, "explanation": "体貌：身高是人的外形特征，与“让人满意”的服务不搭。"}, {"text": "价格", "is_correct": false, "explanation": "语义：“价格”指钱数，不能说服务员的价格很好。"}], "explanations": {"态度": "“态度”指对人对事表现出来的样子和做法，与“服务员的……很好，我们都很满意”相符。", "味道": "语义：“味道”指食物或气味，不能说服务员的味道很好。", "身高": "体貌：身高是人的外形特征，与“让人满意”的服务不搭。", "价格": "语义：“价格”指钱数，不能说服务员的价格很好。"}, "sentence_index": 0, "correct_answer": "态度"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他脸上的态度很严肃，大家都不敢说话。", "explanation": "这里应该用〈神情〉。态度指对人或事的做法和立场，不指脸上的样子。"}, {"text": "她跳舞的态度很优美，大家都看呆了。", "explanation": "这里应该用〈姿态〉。态度不指动作的样子，优美的动作要用“姿态”。"}, {"text": "看到这幅画，我心里有一种说不出的态度，很舒服。", "explanation": "这里应该用〈感觉〉。态度指对一件事表现出来的样子，心里的感受要用“感觉”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '833ea5fc-85bc-447f-ba8f-2c270206bdec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87887, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "态度", "is_correct": true, "explanation": "“态度”指表现出来的样子和做法，与“她的……一下子变冷了”相符。"}, {"text": "体重", "is_correct": false, "explanation": "语义：体重是身体的重量，不会“一下子变冷”。"}, {"text": "年龄", "is_correct": false, "explanation": "搭配：“年龄”不能用“变冷”来描述。"}, {"text": "面积", "is_correct": false, "explanation": "语义：面积指大小，不会“一下子变冷”。"}], "explanations": {"态度": "“态度”指表现出来的样子和做法，与“她的……一下子变冷了”相符。", "体重": "语义：体重是身体的重量，不会“一下子变冷”。", "年龄": "搭配：“年龄”不能用“变冷”来描述。", "面积": "语义：面积指大小，不会“一下子变冷”。"}, "sentence_index": 6, "correct_answer": "态度"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我的态度很好听，大家都记得。", "explanation": "这里应该用〈名字〉。态度不指人的称呼，好听的称呼要用“名字”。"}, {"text": "这件衣服的态度很鲜艳。", "explanation": "这里应该用〈颜色〉。态度不指衣服的颜色，鲜艳要用“颜色”。"}, {"text": "这首歌的态度很好听，大家都爱唱。", "explanation": "这里应该用〈歌声〉。态度不指声音，好听的声音要用“歌声”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '833ea5fc-85bc-447f-ba8f-2c270206bdec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87887, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他对工作有一块认真的态度，大家都很佩服。", "corrected_sentence": "他对工作有一种认真的态度，大家都很佩服。", "error_description": "错误在量词：“态度”应使用量词“种”，不能用“块”（块多用于块状的东西）。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '833ea5fc-85bc-447f-ba8f-2c270206bdec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87887, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他的工作地态度很认真，老板很满意。", "corrected_sentence": "他的工作态度很认真，老板很满意。", "error_description": "结构助词错误：“工作态度”是复合词，中间不能插入“地”（“地”用于修饰动词），应说“他的工作态度”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '833ea5fc-85bc-447f-ba8f-2c270206bdec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
