INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87888, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "对人或事物所持的看法及行为表现。", "primary_collocate": null, "pronunciation": "tài dù", "ipa": "tʰaɪ̯˥˩ tu˥˩", "syllable_count": 2, "sentences": [{"text": "对这个计划，大家的态度不一样。", "target_word": "态度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经理对我们的建议态度很明确。", "target_word": "态度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他对结婚的态度很开放。", "target_word": "态度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我不知道妈妈是什么态度。", "target_word": "态度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "对这件事，学校的态度是支持。", "target_word": "态度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他对学习的态度一直很积极。", "target_word": "态度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司对加班是什么态度？", "target_word": "态度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我先看看老板的态度，再做决定。", "target_word": "态度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他对那件事的态度，我们都不清楚。", "target_word": "态度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她对环保的态度很认真，天天分类垃圾。", "target_word": "态度", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一种态度", "label": "量词"}, {"form": "態度", "label": "繁体"}, {"form": "工作态度", "label": "复合"}, {"form": "学习态度", "label": "复合"}], "register": "通用", "sense_fingerprint": "态度：对某人某事所持的立场、看法和相应的做法", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '84eaa279-90ef-4dbd-b39e-63b4c5dbbc90') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87888, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "态度", "is_correct": true, "explanation": "“态度”指对某人某事所持的立场和看法，与“对这个计划，大家的……不一样”相符。"}, {"text": "味道", "is_correct": false, "explanation": "语义：“味道”指食物的口感，不能说大家对计划的味道不一样。"}, {"text": "身高", "is_correct": false, "explanation": "体貌：身高是人的外形特征，与“对计划的看法”无关。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：“颜色”是外表的色彩，不能说大家对计划的颜色不一样。"}], "explanations": {"态度": "“态度”指对某人某事所持的立场和看法，与“对这个计划，大家的……不一样”相符。", "味道": "语义：“味道”指食物的口感，不能说大家对计划的味道不一样。", "身高": "体貌：身高是人的外形特征，与“对计划的看法”无关。", "颜色": "语义：“颜色”是外表的色彩，不能说大家对计划的颜色不一样。"}, "sentence_index": 0, "correct_answer": "态度"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他脸上的态度很紧张，大家都看出来了。", "explanation": "这里应该用〈神色〉。态度指对人或事的看法和做法，不指脸上的神色。"}, {"text": "这道题的态度是三。", "explanation": "这里应该用〈答案〉。态度不指题目的结果，题目的结果要用“答案”。"}, {"text": "我想到一个好态度，就告诉了老师。", "explanation": "这里应该用〈办法〉。态度指对人或事物所持的看法及行为表现，想出的解决方法要用“办法”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '833ea5fc-85bc-447f-ba8f-2c270206bdec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87888, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "态度", "is_correct": true, "explanation": "“态度”指对某事所持的立场和做法，与“公司对加班是什么……？”相符。"}, {"text": "形状", "is_correct": false, "explanation": "语义：“形状”指外形，不能说公司对加班是什么形状。"}, {"text": "价格", "is_correct": false, "explanation": "搭配：“价格”不能用于“对加班是什么……”这样的提问。"}, {"text": "重量", "is_correct": false, "explanation": "语义：“重量”指轻重，不能说公司对加班是什么重量。"}], "explanations": {"态度": "“态度”指对某事所持的立场和做法，与“公司对加班是什么……？”相符。", "形状": "语义：“形状”指外形，不能说公司对加班是什么形状。", "价格": "搭配：“价格”不能用于“对加班是什么……”这样的提问。", "重量": "语义：“重量”指轻重，不能说公司对加班是什么重量。"}, "sentence_index": 6, "correct_answer": "态度"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这张照片里，她的态度很可爱，大家都喜欢。", "explanation": "这里应该用〈表情〉。照片里外在的样子要用“表情”，态度不指外在表情。"}, {"text": "这首歌的态度很好听，大家都爱唱。", "explanation": "这里应该用〈歌声〉。态度不指声音，好听的声音要用“歌声”。"}, {"text": "今天的态度很好，适合出门散步。", "explanation": "这里应该用〈天气〉。态度不指天气，适合出门的情况要用“天气”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '833ea5fc-85bc-447f-ba8f-2c270206bdec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87888, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她的学习地态度一直很积极。", "corrected_sentence": "她的学习态度一直很积极。", "error_description": "结构助词错误：“学习态度”是复合词，中间不能插入“地”（“地”用于修饰动词），应说“她的学习态度”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '833ea5fc-85bc-447f-ba8f-2c270206bdec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87888, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他对这次比赛有一把积极的态度，大家都很支持。", "corrected_sentence": "他对这次比赛有一种积极的态度，大家都很支持。", "error_description": "错误在量词：“态度”应使用量词“种”，不能用“把”（把多用于有柄的器具）。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '833ea5fc-85bc-447f-ba8f-2c270206bdec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
