INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87893, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "政权是管一个国家的大权力。", "primary_collocate": null, "pronunciation": "zhèng quán", "ipa": "ʈʂɤŋ˥˩ tɕʰɥɛn˧˥", "syllable_count": 2, "sentences": [{"text": "他想拿到这个国家的政权。", "target_word": "政权", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "国王死后，政权到了他儿子手里。", "target_word": "政权", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "那个国家的政权一直不稳。", "target_word": "政权", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "军人想用枪夺取政权。", "target_word": "政权", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他们成功地建立了新的政权。", "target_word": "政权", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "政权不稳的时候，人民的生活很苦。", "target_word": "政权", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "皇帝牢牢地掌握着政权。", "target_word": "政权", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在那一年失去了政权，离开了国家。", "target_word": "政权", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "很多人为了政权互相打仗。", "target_word": "政权", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他得到政权后，开始管理整个国家。", "target_word": "政权", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "一个政权", "label": "量词"}, {"form": "地方政权", "label": "复合词"}, {"form": "政權", "label": "繁体"}], "register": "书面", "sense_fingerprint": "管理一个国家的大权力，可以夺取、掌握或失去", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3a1b6033-d2c6-4adf-8a03-9e18bc04078f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87893, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "政权", "is_correct": true, "explanation": "本词：管理一个国家的大权力。"}, {"text": "争权", "is_correct": false, "explanation": "zhèng（第四声）与 zhēng（第一声）声调不同，意思是争夺权力。"}, {"text": "证券", "is_correct": false, "explanation": "quán（第二声）与 quàn（第四声）声调不同，意思是证券。"}, {"text": "挣钱", "is_correct": false, "explanation": "quán 与 qián 韵母不同（üan / ian），意思是赚钱。"}], "explanations": {"政权": "本词：管理一个国家的大权力。", "争权": "zhèng（第四声）与 zhēng（第一声）声调不同，意思是争夺权力。", "证券": "quán（第二声）与 quàn（第四声）声调不同，意思是证券。", "挣钱": "quán 与 qián 韵母不同（üan / ian），意思是赚钱。"}, "sentence_index": null, "correct_answer": "政权"}, "level_3": {"options": [{"text": "政权", "is_correct": true, "explanation": "正确：「这个国家的政权」指管理国家的大权力，符合句意。"}, {"text": "天空", "is_correct": false, "explanation": "语义：天空不是国家的权力，句意不通。"}, {"text": "海洋", "is_correct": false, "explanation": "语义：海洋不是国家的权力，不能被拿到。"}, {"text": "温度", "is_correct": false, "explanation": "搭配：「拿到」不搭配温度，温度不是可以拿到的东西。"}], "explanations": {"政权": "正确：「这个国家的政权」指管理国家的大权力，符合句意。", "天空": "语义：天空不是国家的权力，句意不通。", "海洋": "语义：海洋不是国家的权力，不能被拿到。", "温度": "搭配：「拿到」不搭配温度，温度不是可以拿到的东西。"}, "sentence_index": 0, "correct_answer": "政权"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "军人想用枪打扫政权。", "explanation": "这里应该用〈房间〉。打扫的是房间，政权不能打扫。"}, {"text": "军人想用枪唱政权。", "explanation": "这里应该用〈歌〉。唱的是歌，政权不能唱。"}, {"text": "军人想用枪擦政权。", "explanation": "这里应该用〈桌子〉。擦的是桌子，政权不能擦。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f0882abe-bb72-4758-a4df-173b86a28d89') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87893, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "政权", "is_correct": true, "explanation": "正确：皇帝掌握的是国家的统治权力，符合句意。"}, {"text": "空气", "is_correct": false, "explanation": "语义：空气无法被皇帝牢牢掌握，句意不通。"}, {"text": "脚步", "is_correct": false, "explanation": "搭配：「掌握」不搭配脚步，应说「迈开脚步」之类。"}, {"text": "月亮", "is_correct": false, "explanation": "配价：「掌握」的宾语须是可控制的对象，月亮不能被掌握。"}], "explanations": {"政权": "正确：皇帝掌握的是国家的统治权力，符合句意。", "空气": "语义：空气无法被皇帝牢牢掌握，句意不通。", "脚步": "搭配：「掌握」不搭配脚步，应说「迈开脚步」之类。", "月亮": "配价：「掌握」的宾语须是可控制的对象，月亮不能被掌握。"}, "sentence_index": 6, "correct_answer": "政权"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "政府制定了一个新政权，帮助农民。", "explanation": "这里应该用〈计划〉。制定的是计划，政权是统治权力，不能制定。"}, {"text": "学校举办了政权，很多同学参加。", "explanation": "这里应该用〈比赛〉。举办的是比赛，政权不能举办。"}, {"text": "学校开设了新的政权，大家都很喜欢。", "explanation": "这里应该用〈课程〉。开设的是课程，政权不能开设。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f0882abe-bb72-4758-a4df-173b86a28d89') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87893, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "那张政权被他夺走了。", "corrected_sentence": "那个政权被他夺走了。", "error_description": "量词错误：「政权」应用「个」计量，「张」多用于平面的事物。应说「那个政权被他夺走了」，不能说「那张政权被他夺走了」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f0882abe-bb72-4758-a4df-173b86a28d89') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87893, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他夺得这份政权后，开始管理整个国家。", "corrected_sentence": "他夺得这个政权后，开始管理整个国家。", "error_description": "量词错误：「政权」应用「个」计量，「份」用于工作、礼物等具体事物，不能用于政权。应说「他夺得这个政权后，开始管理整个国家」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f0882abe-bb72-4758-a4df-173b86a28d89') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
