INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87894, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "国家统治的权力；也指掌握国家权力的机关。", "primary_collocate": null, "pronunciation": "zhèng quán", "ipa": "ʈʂɤŋ˥˩ tɕʰɥɛn˧˥", "syllable_count": 2, "sentences": [{"text": "他们推翻了旧政权。", "target_word": "政权", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "新政权成立以后，国家慢慢安定下来。", "target_word": "政权", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个政权只维持了十年。", "target_word": "政权", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "政府要想巩固政权，必须得到人民的支持。", "target_word": "政权", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "很多国家不承认这个新政权。", "target_word": "政权", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个政权靠军队才能统治国家。", "target_word": "政权", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他在旧政权的机关里工作过很多年。", "target_word": "政权", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国家的政权应该属于人民。", "target_word": "政权", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "战争结束后，这个政权很快垮台了。", "target_word": "政权", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他们成立了一个临时政权，管理这个地区。", "target_word": "政权", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一个政权", "label": "量词"}, {"form": "地方政权", "label": "复合词"}, {"form": "政權", "label": "繁体"}], "register": "书面", "sense_fingerprint": "国家统治权力，也指掌握这种权力的政权机构", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3a1b6033-d2c6-4adf-8a03-9e18bc04078f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87894, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "政权", "is_correct": true, "explanation": "本词：国家统治的权力，也指掌握国家权力的机关。"}, {"text": "争权", "is_correct": false, "explanation": "zhèng（第四声）与 zhēng（第一声）声调不同，意思是争夺权力。"}, {"text": "证券", "is_correct": false, "explanation": "quán（第二声）与 quàn（第四声）声调不同，意思是证券。"}, {"text": "挣钱", "is_correct": false, "explanation": "quán 与 qián 韵母不同（üan / ian），意思是赚钱。"}], "explanations": {"政权": "本词：国家统治的权力，也指掌握国家权力的机关。", "争权": "zhèng（第四声）与 zhēng（第一声）声调不同，意思是争夺权力。", "证券": "quán（第二声）与 quàn（第四声）声调不同，意思是证券。", "挣钱": "quán 与 qián 韵母不同（üan / ian），意思是赚钱。"}, "sentence_index": null, "correct_answer": "政权"}, "level_3": {"options": [{"text": "政权", "is_correct": true, "explanation": "正确：推翻的是旧的政权，符合句意。"}, {"text": "书", "is_correct": false, "explanation": "搭配：「推翻」不搭配书，书不能被推翻。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气不是可以被推翻的制度。"}, {"text": "朋友", "is_correct": false, "explanation": "配价：「推翻」的宾语须是政权、制度等，朋友不能被推翻。"}], "explanations": {"政权": "正确：推翻的是旧的政权，符合句意。", "书": "搭配：「推翻」不搭配书，书不能被推翻。", "天气": "语义：天气不是可以被推翻的制度。", "朋友": "配价：「推翻」的宾语须是政权、制度等，朋友不能被推翻。"}, "sentence_index": 0, "correct_answer": "政权"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "政府要想推行好政权，必须得到人民的支持。", "explanation": "这里应该用〈政策〉。推行的是政策，政权是国家的统治权力，不能推行。"}, {"text": "政府召开政权，讨论教育问题。", "explanation": "这里应该用〈会议〉。召开的是会议，政权不能召开。"}, {"text": "政府公布了最新的政权。", "explanation": "这里应该用〈数据〉。公布的是数据，政权不能公布。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f0882abe-bb72-4758-a4df-173b86a28d89') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87894, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "政权", "is_correct": true, "explanation": "正确：「旧政权的机关」指旧政府的国家机关，符合句意。"}, {"text": "海洋", "is_correct": false, "explanation": "语义：海洋不是国家机关，不能说「旧海洋的机关」。"}, {"text": "天空", "is_correct": false, "explanation": "语义：天空不是国家机关，句意不通。"}, {"text": "粮食", "is_correct": false, "explanation": "搭配：「机关」是机构，「粮食」不能修饰机关。"}], "explanations": {"政权": "正确：「旧政权的机关」指旧政府的国家机关，符合句意。", "海洋": "语义：海洋不是国家机关，不能说「旧海洋的机关」。", "天空": "语义：天空不是国家机关，句意不通。", "粮食": "搭配：「机关」是机构，「粮食」不能修饰机关。"}, "sentence_index": 6, "correct_answer": "政权"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他们正在厨房里煮政权。", "explanation": "这里应该用〈汤〉。煮的是汤，政权不能煮。"}, {"text": "他戴着政权去上班。", "explanation": "这里应该用〈帽子〉。戴的是帽子，政权不能戴。"}, {"text": "他正在剪政权。", "explanation": "这里应该用〈头发〉。剪的是头发，政权不能剪。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f0882abe-bb72-4758-a4df-173b86a28d89') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87894, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这本旧政权被人民推翻了。", "corrected_sentence": "这个旧政权被人民推翻了。", "error_description": "量词错误：「政权」应用「个」计量，「本」用于书籍等。应说「这个旧政权被人民推翻了」，不能说「这本旧政权被人民推翻了」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f0882abe-bb72-4758-a4df-173b86a28d89') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87894, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "新政府接管了这本政权。", "corrected_sentence": "新政府接管了这个政权。", "error_description": "量词错误：「政权」应用「个」计量，「本」用于书籍等。应说「新政府接管了这个政权」，不能说「新政府接管了这本政权」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f0882abe-bb72-4758-a4df-173b86a28d89') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
