INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87898, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "城镇中两侧有房屋的、供人车通行的道路。", "primary_collocate": null, "pronunciation": "jiē dào", "ipa": "tɕjɛ˥ tɑʊ˥˩", "syllable_count": 2, "sentences": [{"text": "这座小镇的街道又窄又长。", "target_word": "街道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "街道两侧是老房子。", "target_word": "街道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "汽车慢慢开过窄窄的街道。", "target_word": "街道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "城里的主要街道晚上也很亮。", "target_word": "街道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "市政府新修了几条街道。", "target_word": "街道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条街道禁止车辆通行。", "target_word": "街道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老城区的街道是石头铺成的。", "target_word": "街道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "街道上有人在走路，也有车在跑。", "target_word": "街道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地图上能找到这几条街道的名字。", "target_word": "街道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个路口连着两条街道。", "target_word": "街道", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "条", "label": "量词"}], "register": "中性", "sense_fingerprint": "城镇中两侧有房屋、供人车通行的道路", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2629cfaa-ecb6-48f0-80ae-066a0850e85a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings 