INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87898, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "街道", "is_correct": true, "explanation": "正确：街道（jiē dào）是城镇中两侧有房屋、供人车通行的道路，就是这个词。"}, {"text": "接待", "is_correct": false, "explanation": "dài（第四声）与 dào（第四声）韵母不同（ai 与 ao），意思是接待客人。"}, {"text": "借道", "is_correct": false, "explanation": "jiè（第四声）与 jiē（第一声）声调不同，意思是借用道路通过。"}, {"text": "阶段", "is_correct": false, "explanation": "duàn 与 dào 韵母不同（uan 与 ao），意思是事情发展的一个阶段。"}], "explanations": {"街道": "正确：街道（jiē dào）是城镇中两侧有房屋、供人车通行的道路，就是这个词。", "接待": "dài（第四声）与 dào（第四声）韵母不同（ai 与 ao），意思是接待客人。", "借道": "jiè（第四声）与 jiē（第一声）声调不同，意思是借用道路通过。", "阶段": "duàn 与 dào 韵母不同（uan 与 ao），意思是事情发展的一个阶段。"}, "sentence_index": null, "correct_answer": "街道"}, "level_3": {"options": [{"text": "街道", "is_correct": true, "explanation": "正确：“街道”是城镇中两侧有房屋的道路，与“又窄又长”相符。"}, {"text": "声音", "is_correct": false, "explanation": "语义：“又窄又长”形容道路等空间，“声音”不能这样描述，句意不通。"}, {"text": "饭菜", "is_correct": false, "explanation": "语义：“饭菜”不能说又窄又长，句意不通。"}, {"text": "歌曲", "is_correct": false, "explanation": "语义：“歌曲”不能说又窄又长，句意不通。"}], "explanations": {"街道": "正确：“街道”是城镇中两侧有房屋的道路，与“又窄又长”相符。", "声音": "语义：“又窄又长”形容道路等空间，“声音”不能这样描述，句意不通。", "饭菜": "语义：“饭菜”不能说又窄又长，句意不通。", "歌曲": "语义：“歌曲”不能说又窄又长，句意不通。"}, "sentence_index": 0, "correct_answer": "街道"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这条街道连接北京和天津，车很多。", "explanation": "这里应该用〈公路〉。街道指城镇中两侧有房屋、供人车通行的道路，连接两座城市的路要说〈公路〉。"}, {"text": "这条街道每五十公里设一个收费站。", "explanation": "这里应该用〈高速公路〉。街道在城镇中，不设收费站；每隔几十公里设收费站的是〈高速公路〉。"}, {"text": "这条街道穿过一大片庄稼地，离城很远。", "explanation": "这里应该用〈小路〉。街道指城镇中两侧有房屋的路，穿过田野、远离城镇的路要说〈小路〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '02715c0c-42fc-4b33-851a-a1d47916bb2f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87898, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "街道", "is_correct": true, "explanation": "正确：街道（jiē dào）是城镇中两侧有房屋、供人车通行的道路，就是这个词。"}, {"text": "切到", "is_correct": false, "explanation": "qiē 与 jiē 声母不同（q 与 j），意思是刀子等切到（手）。"}, {"text": "借到", "is_correct": false, "explanation": "jiè（第四声）与 jiē（第一声）声调不同，意思是借得到东西。"}, {"text": "加到", "is_correct": false, "explanation": "jiā 与 jiē 韵母不同（a 与 ie），意思是加入到某处。"}], "explanations": {"街道": "正确：街道（jiē dào）是城镇中两侧有房屋、供人车通行的道路，就是这个词。", "切到": "qiē 与 jiē 声母不同（q 与 j），意思是刀子等切到（手）。", "借到": "jiè（第四声）与 jiē（第一声）声调不同，意思是借得到东西。", "加到": "jiā 与 jiē 韵母不同（a 与 ie），意思是加入到某处。"}, "sentence_index": null, "correct_answer": "街道"}, "level_3": {"options": [{"text": "街道", "is_correct": true, "explanation": "正确：“街道”是城镇中两侧有房屋的道路，与“石头铺成”相符。"}, {"text": "歌词", "is_correct": false, "explanation": "语义：“歌词”不是用石头铺成的东西，句意不通。"}, {"text": "信件", "is_correct": false, "explanation": "语义：“信件”不能用石头铺成，句意不通。"}, {"text": "草地", "is_correct": false, "explanation": "搭配：说“铺成”多用于道路、地面，草地一般说“长满”，与“石头铺成”不搭配。"}], "explanations": {"街道": "正确：“街道”是城镇中两侧有房屋的道路，与“石头铺成”相符。", "歌词": "语义：“歌词”不是用石头铺成的东西，句意不通。", "信件": "语义：“信件”不能用石头铺成，句意不通。", "草地": "搭配：说“铺成”多用于道路、地面，草地一般说“长满”，与“石头铺成”不搭配。"}, "sentence_index": 6, "correct_answer": "街道"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他把街道装进了书包。", "explanation": "这里把〈街道〉当成了能装进书包的小物件，应该用〈模型〉或〈玩具〉这类指小物体的词；街道是城镇中供人车通行的道路，不能装进书包。"}, {"text": "他用街道写了一封信。", "explanation": "这里把〈街道〉当成了书写工具，应该用〈笔〉；街道是供人车通行的道路，不能用来写字。"}, {"text": "教室里铺着一条街道。", "explanation": "这里把〈街道〉当成了可以铺在地上的〈地毯〉这类东西；街道是城镇中供人车通行的道路，不能铺在教室里。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '02715c0c-42fc-4b33-851a-a1d47916bb2f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87898, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我家门口有一只街道。", "corrected_sentence": "我家门口有一条街道。", "error_description": "量词错误：“街道”的量词应为“条”，不能用“只”（“只”用于动物或成对的东西）。错误形式“一只街道”，正确形式“一条街道”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '02715c0c-42fc-4b33-851a-a1d47916bb2f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87898, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这几条街道们都很热闹，有很多商店。", "corrected_sentence": "这几条街道都很热闹，有很多商店。", "error_description": "加“们”错误：“们”只用于人，不能用于“街道”。错误形式“街道们”，正确形式“街道”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '02715c0c-42fc-4b33-851a-a1d47916bb2f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
