INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87900, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "公司、银行等机构经营的专业事务。", "primary_collocate": null, "pronunciation": "yè wù", "ipa": "jɛ˥˩ u˥˩", "syllable_count": 2, "sentences": [{"text": "这家公司的业务是卖电脑。", "target_word": "业务", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们公司在中国的业务越来越大。", "target_word": "业务", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家银行的业务很多。", "target_word": "业务", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们的业务不只在北京，还在上海。", "target_word": "业务", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司想把业务做到国外去。", "target_word": "业务", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家店的主要业务是修手机。", "target_word": "业务", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医院新开了一项业务。", "target_word": "业务", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今年银行的业务增加了不少。", "target_word": "业务", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他开了公司，业务做得很好。", "target_word": "业务", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个公司的业务范围很广。", "target_word": "业务", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一项业务", "label": "量词"}, {"form": "業務", "label": "繁体"}, {"form": "业务员", "label": "复合"}, {"form": "业务范围", "label": "复合"}], "register": "通用", "sense_fingerprint": "业务：公司、银行等机构经营的专业事务", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '84eaa279-90ef-4dbd-b39e-63b4c5dbbc90') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87900, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "业务", "is_correct": true, "explanation": "正确：业务，指公司、银行等机构经营的专业事务。"}, {"text": "夜路", "is_correct": false, "explanation": "第二个音节 lù（第四声）与 wù 只差声母，意思是夜里走的路。"}, {"text": "夜幕", "is_correct": false, "explanation": "第二个音节 mù（第四声）与 wù 声母不同，意思是笼罩夜空的样子。"}, {"text": "夜露", "is_correct": false, "explanation": "第二个音节 lù（第四声）与 wù 只差声母，意思是夜间的露水。"}, {"text": "业余", "is_correct": false, "explanation": "第二个音节 yú（第二声）与 wù（第四声）韵母和声调都不同，意思是业余。"}], "explanations": {"业务": "正确：业务，指公司、银行等机构经营的专业事务。", "夜路": "第二个音节 lù（第四声）与 wù 只差声母，意思是夜里走的路。", "夜幕": "第二个音节 mù（第四声）与 wù 声母不同，意思是笼罩夜空的样子。", "夜露": "第二个音节 lù（第四声）与 wù 只差声母，意思是夜间的露水。", "业余": "第二个音节 yú（第二声）与 wù（第四声）韵母和声调都不同，意思是业余。"}, "sentence_index": null, "correct_answer": "业务"}, "level_3": {"options": [{"text": "业务", "is_correct": true, "explanation": "正确：业务，指公司经营的专业事务，卖电脑正是它的业务。"}, {"text": "身材", "is_correct": false, "explanation": "体貌：身材说的是人的体形，不能用来说公司的经营内容。"}, {"text": "学历", "is_correct": false, "explanation": "语义：学历是人的受教育程度，公司不能有学历。"}, {"text": "年龄", "is_correct": false, "explanation": "语义：年龄指人或事物存在的时间，与公司卖什么电脑无关。"}], "explanations": {"业务": "正确：业务，指公司经营的专业事务，卖电脑正是它的业务。", "身材": "体貌：身材说的是人的体形，不能用来说公司的经营内容。", "学历": "语义：学历是人的受教育程度，公司不能有学历。", "年龄": "语义：年龄指人或事物存在的时间，与公司卖什么电脑无关。"}, "sentence_index": 0, "correct_answer": "业务"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他把一生都献给了教育业务。", "explanation": "这里应该用〈事业〉。“事业”指长期为之奋斗的理想性工作，常与“献身”“奋斗”搭配；业务指日常的专业工作事务，不能说“献给……的业务”。"}, {"text": "这家公司接了三本业务。", "explanation": "这里应该用〈项〉。“本”用于书、本子等，不用于业务。"}, {"text": "这家公司有三百名业务。", "explanation": "这里应该用〈业务员〉。业务指经营的事务，不能用“名”来数，指人要用“业务员”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '833ea5fc-85bc-447f-ba8f-2c270206bdec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87900, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "业务", "is_correct": true, "explanation": "正确：业务，指公司、银行等机构经营的专业事务。"}, {"text": "异物", "is_correct": false, "explanation": "第一个音节 yì（第四声）与 yè 只差韵母，意思是不该出现的外来物。"}, {"text": "野物", "is_correct": false, "explanation": "第一个音节 yě（第三声）与 yè（第四声）只差声调，意思是野生的动物。"}, {"text": "衣物", "is_correct": false, "explanation": "第一个音节 yī（第一声）与 yè（第四声）只差声调，意思是衣服等物品。"}, {"text": "遗物", "is_correct": false, "explanation": "第一个音节 yí（第二声）与 yè 声调和韵母都不同，意思是死者留下的物品。"}], "explanations": {"业务": "正确：业务，指公司、银行等机构经营的专业事务。", "异物": "第一个音节 yì（第四声）与 yè 只差韵母，意思是不该出现的外来物。", "野物": "第一个音节 yě（第三声）与 yè（第四声）只差声调，意思是野生的动物。", "衣物": "第一个音节 yī（第一声）与 yè（第四声）只差声调，意思是衣服等物品。", "遗物": "第一个音节 yí（第二声）与 yè 声调和韵母都不同，意思是死者留下的物品。"}, "sentence_index": null, "correct_answer": "业务"}, "level_3": {"options": [{"text": "业务", "is_correct": true, "explanation": "正确：业务，指医院提供的一项服务或经营事务。"}, {"text": "能力", "is_correct": false, "explanation": "搭配：“新开”多接“业务、服务、诊室”等，不说“新开一项能力”。"}, {"text": "荣誉", "is_correct": false, "explanation": "语义：荣誉是获得的称号，不能“新开”。"}, {"text": "技能", "is_correct": false, "explanation": "搭配：“技能”要学会、掌握，不说“新开一项技能”。"}], "explanations": {"业务": "正确：业务，指医院提供的一项服务或经营事务。", "能力": "搭配：“新开”多接“业务、服务、诊室”等，不说“新开一项能力”。", "荣誉": "语义：荣誉是获得的称号，不能“新开”。", "技能": "搭配：“技能”要学会、掌握，不说“新开一项技能”。"}, "sentence_index": 6, "correct_answer": "业务"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "医院开了一杯业务。", "explanation": "这里应该用〈项〉。“杯”用于盛装的饮料，业务要用“项”来数。"}, {"text": "医院有五十名业务。", "explanation": "这里应该用〈员工〉。“名”可以数人，但业务指事务，不能用来数人。"}, {"text": "他周末最喜欢的业务是散步。", "explanation": "这里应该用〈爱好〉。“业务”指个人或机构的专业工作，不指闲暇时喜欢做的事，散步属于爱好。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '833ea5fc-85bc-447f-ba8f-2c270206bdec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87900, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这家公司今年有几座新业务。", "corrected_sentence": "这家公司今年有几项新业务。", "error_description": "“业务”的量词应用“项”，不用“座”。“座”用于山、桥、楼等大型固定物，应改为“几项新业务”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '833ea5fc-85bc-447f-ba8f-2c270206bdec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87900, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这家网站的业务做很好。", "corrected_sentence": "这家网站的业务做得很好。", "error_description": "“做得很好”中的“得”是情态补语的标记，不能省。省去“得”是错误，应改为“这家网站的业务做得很好”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '833ea5fc-85bc-447f-ba8f-2c270206bdec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
