is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87906, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "武器", "is_correct": true, "explanation": "本词：指用于攻击或防卫的器械。"}, {"text": "雾气", "is_correct": false, "explanation": "wù（第四声）与 wǔ（第三声）声调不同，意思是雾气，不是武器。"}, {"text": "舞技", "is_correct": false, "explanation": "qì 与 jì 声母不同（q / j），意思是舞蹈的技艺。"}, {"text": "五七", "is_correct": false, "explanation": "qì（第四声）与 qī（第一声）声调不同，意思是数字五和七。"}, {"text": "无奇", "is_correct": false, "explanation": "wǔ（第三声）与 wú（第二声）、qì（第四声）与 qí（第二声）声调不同，意思是不出众。"}], "explanations": {"武器": "本词：指用于攻击或防卫的器械。", "雾气": "wù（第四声）与 wǔ（第三声）声调不同，意思是雾气，不是武器。", "舞技": "qì 与 jì 声母不同（q / j），意思是舞蹈的技艺。", "五七": "qì（第四声）与 qī（第一声）声调不同，意思是数字五和七。", "无奇": "wǔ（第三声）与 wú（第二声）、qì（第四声）与 qí（第二声）声调不同，意思是不出众。"}, "sentence_index": null, "correct_answer": "武器"}, "level_3": {"options": [{"text": "武器", "is_correct": true, "explanation": "正确：枪、炮和刀都属于用于攻击或防卫的器械，符合句意。"}, {"text": "乐器", "is_correct": false, "explanation": "语义：枪、炮和刀不是乐器。"}, {"text": "饮料", "is_correct": false, "explanation": "语义：枪、炮和刀不能喝，不是饮料。"}, {"text": "水果", "is_correct": false, "explanation": "配价：「是」后的类属名词要与主语同类，水果与枪、炮、刀不属于同类。"}], "explanations": {"武器": "正确：枪、炮和刀都属于用于攻击或防卫的器械，符合句意。", "乐器": "语义：枪、炮和刀不是乐器。", "饮料": "语义：枪、炮和刀不能喝，不是饮料。", "水果": "配价：「是」后的类属名词要与主语同类，水果与枪、炮、刀不属于同类。"}, "sentence_index": 0, "correct_answer": "武器"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "孩子们用这件武器搭积木。", "explanation": "这里应该用〈玩具〉。搭积木用的是玩具，武器是用于攻击或防卫的器械。"}, {"text": "他用这件武器弹了一首曲子。", "explanation": "这里应该用〈乐器〉。弹曲子用的是乐器，武器不能用来演奏。"}, {"text": "妈妈用这件武器炒了一盘菜。", "explanation": "这里应该用〈厨具〉。炒菜用的是厨具，武器不能用来做饭。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f0882abe-bb72-4758-a4df-173b86a28d89') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87906, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "武器", "is_correct": true, "explanation": "本词：指用于攻击或防卫的器械。"}, {"text": "武戏", "is_correct": false, "explanation": "qì 与 xì 声母不同（q / x），意思是武打戏。"}, {"text": "误期", "is_correct": false, "explanation": "wǔ 与 wù、qì 与 qī 声调不同，意思是耽误期限。"}, {"text": "雨期", "is_correct": false, "explanation": "wǔ 与 yǔ 声母不同（w / y），意思是雨季。"}], "explanations": {"武器": "本词：指用于攻击或防卫的器械。", "武戏": "qì 与 xì 声母不同（q / x），意思是武打戏。", "误期": "wǔ 与 wù、qì 与 qī 声调不同，意思是耽误期限。", "雨期": "wǔ 与 yǔ 声母不同（w / y），意思是雨季。"}, "sentence_index": null, "correct_answer": "武器"}, "level_3": {"options": [{"text": "武器", "is_correct": true, "explanation": "正确：法律限制普通人拥有的是武器，符合句意。"}, {"text": "太阳", "is_correct": false, "explanation": "语义：普通人不可能拥有太阳，句意不通。"}, {"text": "空气", "is_correct": false, "explanation": "搭配：「拥有」不搭配空气，空气不是可以拥有的物件。"}, {"text": "月亮", "is_correct": false, "explanation": "配价：「拥有」的宾语须是可被占有的具体事物，月亮不能被普通人拥有。"}], "explanations": {"武器": "正确：法律限制普通人拥有的是武器，符合句意。", "太阳": "语义：普通人不可能拥有太阳，句意不通。", "空气": "搭配：「拥有」不搭配空气，空气不是可以拥有的物件。", "月亮": "配价：「拥有」的宾语须是可被占有的具体事物，月亮不能被普通人拥有。"}, "sentence_index": 6, "correct_answer": "武器"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这位医生正在给武器看病。", "explanation": "这里应该用〈病人〉。看病的对象是病人，武器不能看病。"}, {"text": "孩子们正在唱武器。", "explanation": "这里应该用〈歌〉。唱的是歌，武器不能唱。"}, {"text": "他每天晚上都给武器讲故事。", "explanation": "这里应该用〈孩子〉。讲故事要讲给孩子听，武器不能听故事。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f0882abe-bb72-4758-a4df-173b86a28d89') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87906, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "那首武器被工人运走了。", "corrected_sentence": "那批武器被工人运走了。", "error_description": "量词错误：「首」用于诗、歌等，不能计量「武器」。应说「那批武器被工人运走了」，不能说「那首武器被工人运走了」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f0882abe-bb72-4758-a4df-173b86a28d89') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87906, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "士兵们卖了掉旧武器。", "corrected_sentence": "士兵们卖掉了旧武器。", "error_description": "补语位置错误：「掉」是「卖掉」的补语，「了」应放在动补结构之后，应说「卖掉了旧武器」，不能说「卖了掉旧武器」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f0882abe-bb72-4758-a4df-173b86a28d89') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
