INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87907, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "算出是动脑筋算一算，得到一个答案。", "primary_collocate": null, "pronunciation": "suàn chū", "ipa": "swan˥˩ ʈʂʰu˥", "syllable_count": 2, "sentences": [{"text": "爸爸算出了我们一家的开支。", "target_word": "算出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们动脑筋算出了正确的数字。", "target_word": "算出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我在心里算出了大概的价钱。", "target_word": "算出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈算出买这些菜要多少钱。", "target_word": "算出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想了一会儿，就算出了结果。", "target_word": "算出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你先算出总数，再除以五。", "target_word": "算出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们算出了从北京到上海要几个小时。", "target_word": "算出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她认真地算出了每天的花费。", "target_word": "算出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这笔账他花了一小时才算出来。", "target_word": "算出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小朋友们算出了谁的苹果最多。", "target_word": "算出", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "算出了", "label": "体标（了）"}, {"form": "算出来", "label": "趋向补语形式"}], "register": "中性", "sense_fingerprint": "动脑筋算一算得到答案", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd5c4b2d-97ab-40df-bb81-bfbbee817b15') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87907, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "算出", "is_correct": true, "explanation": "算出（suàn chū）指动脑筋算一算，得到一个答案。"}, {"text": "窜出", "is_correct": false, "explanation": "窜出（cuàn chū）与算出的声母不同（c 与 s），意思是突然跑出来。"}, {"text": "钻出", "is_correct": false, "explanation": "声母与声调都不同：钻出读 zuān chū（第一声），与 suàn chū 的声母 z 与 s 不同，声调也不同，“钻出”意思是从里面钻到外面。"}, {"text": "酸楚", "is_correct": false, "explanation": "酸楚（suān chǔ）两个音节的声调都与算出不同，意思是痛苦、难受。"}, {"text": "散出", "is_correct": false, "explanation": "介音不同：sàn 没有介音 u，与 suàn 只差这一个音位，声调相同，“散出”意思是向四周放出。"}], "explanations": {"算出": "算出（suàn chū）指动脑筋算一算，得到一个答案。", "窜出": "窜出（cuàn chū）与算出的声母不同（c 与 s），意思是突然跑出来。", "钻出": "声母与声调都不同：钻出读 zuān chū（第一声），与 suàn chū 的声母 z 与 s 不同，声调也不同，“钻出”意思是从里面钻到外面。", "酸楚": "酸楚（suān chǔ）两个音节的声调都与算出不同，意思是痛苦、难受。", "散出": "介音不同：sàn 没有介音 u，与 suàn 只差这一个音位，声调相同，“散出”意思是向四周放出。"}, "sentence_index": null, "correct_answer": "算出"}, "level_3": {"options": [{"text": "算出", "is_correct": true, "explanation": "正确：“算出”指动脑筋算出结果，与“我们一家的开支”相配。"}, {"text": "发明", "is_correct": false, "explanation": "搭配：“发明”用于工具、方法，不能用于“开支”。"}, {"text": "唱出", "is_correct": false, "explanation": "搭配：“唱出”多用于歌词、旋律，不能用于“开支”。"}, {"text": "吞下", "is_correct": false, "explanation": "语义：“吞下”与记账无关，句子不通。"}], "explanations": {"算出": "正确：“算出”指动脑筋算出结果，与“我们一家的开支”相配。", "发明": "搭配：“发明”用于工具、方法，不能用于“开支”。", "唱出": "搭配：“唱出”多用于歌词、旋律，不能用于“开支”。", "吞下": "语义：“吞下”与记账无关，句子不通。"}, "sentence_index": 0, "correct_answer": "算出"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我看了他一眼，就算出了他在生气。", "explanation": "这里应该用〈察觉〉。算出靠计算得出结果，靠观察知道别人的情绪要用察觉。"}, {"text": "他一听就算出了是谁的声音。", "explanation": "这里应该用〈听出〉。算出靠计算得出结果，凭声音辨认要用听出。"}, {"text": "根据他的口音，我算出了他的家乡。", "explanation": "这里应该用〈推出〉。算出用于数字计算，由线索推断地点要用推出。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '26503c15-eeab-4ed0-8337-4c518cf997e1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87907, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "算出", "is_correct": true, "explanation": "算出（suàn chū）指动脑筋算一算，得到一个答案。"}, {"text": "赚出", "is_correct": false, "explanation": "声母不同：zhuàn 与 suàn 只差声母 zh 与 s，韵母与声调相同，“赚出”意思是挣到（钱）。"}, {"text": "换出", "is_correct": false, "explanation": "声母不同：huàn 与 suàn 只差声母 h 与 s，韵母与声调相同，“换出”意思是用一物交换后拿出去。"}, {"text": "选出", "is_correct": false, "explanation": "选出（xuǎn chū）第一音节的声母与声调与算出不同（x 与 s），意思是挑选出来。"}], "explanations": {"算出": "算出（suàn chū）指动脑筋算一算，得到一个答案。", "赚出": "声母不同：zhuàn 与 suàn 只差声母 zh 与 s，韵母与声调相同，“赚出”意思是挣到（钱）。", "换出": "声母不同：huàn 与 suàn 只差声母 h 与 s，韵母与声调相同，“换出”意思是用一物交换后拿出去。", "选出": "选出（xuǎn chū）第一音节的声母与声调与算出不同（x 与 s），意思是挑选出来。"}, "sentence_index": null, "correct_answer": "算出"}, "level_3": {"options": [{"text": "算出", "is_correct": true, "explanation": "正确：“算出”指经过计算得到结果，与“从北京到上海要几个小时”相配。"}, {"text": "烧掉", "is_correct": false, "explanation": "语义：“烧掉”与计算无关，句子不通。"}, {"text": "哭出", "is_correct": false, "explanation": "语义：“哭出”与计算无关，句子不通。"}, {"text": "雕出", "is_correct": false, "explanation": "搭配：“雕出”用于雕刻物体，不能用于时间。"}], "explanations": {"算出": "正确：“算出”指经过计算得到结果，与“从北京到上海要几个小时”相配。", "烧掉": "语义：“烧掉”与计算无关，句子不通。", "哭出": "语义：“哭出”与计算无关，句子不通。", "雕出": "搭配：“雕出”用于雕刻物体，不能用于时间。"}, "sentence_index": 6, "correct_answer": "算出"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他算出了一首诗，念给大家听。", "explanation": "这里应该用〈写出〉。算出的对象是数字或结果，诗要用写出来。"}, {"text": "妈妈算出了一个故事，讲给我们听。", "explanation": "这里应该用〈编〉。算出的对象是数字或结果，故事要靠编，不能用算出。"}, {"text": "我们算出了一个饼。", "explanation": "这里应该用〈做〉。算出的对象是数字或结果，饼要用做出来。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '26503c15-eeab-4ed0-8337-4c518cf997e1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87907, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我很快就算出去了两条路的距离。", "corrected_sentence": "我很快就算出了两条路的距离。", "error_description": "错误在多出的“去”。“算出”表示经过计算得出结果，不能接趋向补语“去”；应删去“去”，写成“算出了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '26503c15-eeab-4ed0-8337-4c518cf997e1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87907, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "昨天的题目我不算出来。", "corrected_sentence": "昨天的题目我没算出来。", "error_description": "错误在“不”。过去没有得出结果要用“没”，写成“没算出来”；“不算出来”不成立。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '26503c15-eeab-4ed0-8337-4c518cf997e1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
