INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87908, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "经过计算得出结果。", "primary_collocate": null, "pronunciation": "suàn chū", "ipa": "swan˥˩ ʈʂʰu˥", "syllable_count": 2, "sentences": [{"text": "老师很快就算出了这道题的答案。", "target_word": "算出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我算出这个月一共花了三千块。", "target_word": "算出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他用电脑算出了回家的路程。", "target_word": "算出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你能算出这个房间有多大吗？", "target_word": "算出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工程师算出了盖房子需要多少钱。", "target_word": "算出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她把每个人要付的钱都算出来了。", "target_word": "算出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你算出这两个数的和。", "target_word": "算出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生算出了这种药要吃几天。", "target_word": "算出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他算出今年的收入比去年多。", "target_word": "算出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小明算出了答案，高兴地笑了。", "target_word": "算出", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "算出了", "label": "体标（了）"}, {"form": "算出来", "label": "趋向补语形式"}], "register": "中性", "sense_fingerprint": "经过计算得出结果", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd5c4b2d-97ab-40df-bb81-bfbbee817b15') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87908, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "算出", "is_correct": true, "explanation": "算出（suàn chū）指经过计算得出结果。"}, {"text": "窜出", "is_correct": false, "explanation": "窜出（cuàn chū）与算出的声母不同（c 与 s），意思是突然跑出来。"}, {"text": "钻出", "is_correct": false, "explanation": "声母与声调都不同：钻出读 zuān chū（第一声），与 suàn chū 的声母 z 与 s 不同，声调也不同，“钻出”意思是从里面钻到外面。"}, {"text": "酸楚", "is_correct": false, "explanation": "酸楚（suān chǔ）两个音节的声调都与算出不同，意思是痛苦、难受。"}, {"text": "散出", "is_correct": false, "explanation": "介音不同：sàn 没有介音 u，与 suàn 只差这一个音位，声调相同，“散出”意思是向四周放出。"}], "explanations": {"算出": "算出（suàn chū）指经过计算得出结果。", "窜出": "窜出（cuàn chū）与算出的声母不同（c 与 s），意思是突然跑出来。", "钻出": "声母与声调都不同：钻出读 zuān chū（第一声），与 suàn chū 的声母 z 与 s 不同，声调也不同，“钻出”意思是从里面钻到外面。", "酸楚": "酸楚（suān chǔ）两个音节的声调都与算出不同，意思是痛苦、难受。", "散出": "介音不同：sàn 没有介音 u，与 suàn 只差这一个音位，声调相同，“散出”意思是向四周放出。"}, "sentence_index": null, "correct_answer": "算出"}, "level_3": {"options": [{"text": "算出", "is_correct": true, "explanation": "正确：“算出”指经过计算得出结果，与“这道题的答案”相配。"}, {"text": "发明", "is_correct": false, "explanation": "搭配：“发明”用于工具、方法，不能用于“答案”。"}, {"text": "哭出", "is_correct": false, "explanation": "语义：“哭出”与解题无关，句子不通。"}, {"text": "咬出", "is_correct": false, "explanation": "语义：“咬出”与解题无关，句子不通。"}], "explanations": {"算出": "正确：“算出”指经过计算得出结果，与“这道题的答案”相配。", "发明": "搭配：“发明”用于工具、方法，不能用于“答案”。", "哭出": "语义：“哭出”与解题无关，句子不通。", "咬出": "语义：“咬出”与解题无关，句子不通。"}, "sentence_index": 0, "correct_answer": "算出"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他看了一眼我的脸色，就算出了我的心思。", "explanation": "这里应该用〈猜出〉。算出指经过计算得到结果，猜测别人的心思要用猜出。"}, {"text": "他一眼就算出我在撒谎。", "explanation": "这里应该用〈看出〉。算出靠计算得出结果，凭观察识破真相要用看出。"}, {"text": "根据这些线索，我算出了他的身份。", "explanation": "这里应该用〈推出〉。算出用于数字计算，由线索推断身份要用推出。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '26503c15-eeab-4ed0-8337-4c518cf997e1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87908, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "算出", "is_correct": true, "explanation": "算出（suàn chū）指经过计算得出结果。"}, {"text": "赚出", "is_correct": false, "explanation": "声母不同：zhuàn 与 suàn 只差声母 zh 与 s，韵母与声调相同，“赚出”意思是挣到（钱）。"}, {"text": "换出", "is_correct": false, "explanation": "声母不同：huàn 与 suàn 只差声母 h 与 s，韵母与声调相同，“换出”意思是用一物交换后拿出去。"}, {"text": "选出", "is_correct": false, "explanation": "选出（xuǎn chū）第一音节的声母与声调与算出不同（x 与 s），意思是挑选出来。"}], "explanations": {"算出": "算出（suàn chū）指经过计算得出结果。", "赚出": "声母不同：zhuàn 与 suàn 只差声母 zh 与 s，韵母与声调相同，“赚出”意思是挣到（钱）。", "换出": "声母不同：huàn 与 suàn 只差声母 h 与 s，韵母与声调相同，“换出”意思是用一物交换后拿出去。", "选出": "选出（xuǎn chū）第一音节的声母与声调与算出不同（x 与 s），意思是挑选出来。"}, "sentence_index": null, "correct_answer": "算出"}, "level_3": {"options": [{"text": "算出", "is_correct": true, "explanation": "正确：“算出”指经过计算得出结果，与“这两个数的和”相配。"}, {"text": "吞下", "is_correct": false, "explanation": "语义：“吞下”与求和无关，句子不通。"}, {"text": "唱出", "is_correct": false, "explanation": "搭配：“唱出”多用于歌词、旋律，不能用于数字的和。"}, {"text": "扔掉", "is_correct": false, "explanation": "语义：“扔掉”与计算无关，句子不通。"}], "explanations": {"算出": "正确：“算出”指经过计算得出结果，与“这两个数的和”相配。", "吞下": "语义：“吞下”与求和无关，句子不通。", "唱出": "搭配：“唱出”多用于歌词、旋律，不能用于数字的和。", "扔掉": "语义：“扔掉”与计算无关，句子不通。"}, "sentence_index": 6, "correct_answer": "算出"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他算出了一首好听的歌。", "explanation": "这里应该用〈唱〉。算出的对象是数字或结果，歌曲要用唱。"}, {"text": "我算出了一个笑话，大家都笑了。", "explanation": "这里应该用〈讲〉。算出的对象是数字或结果，笑话要用讲。"}, {"text": "她算出了一幅美丽的画。", "explanation": "这里应该用〈绘制〉。算出指经过计算得到结果，画一幅图要用绘制，不能用算出。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '26503c15-eeab-4ed0-8337-4c518cf997e1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87908, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "妹妹很快就算出去了作业的答案。", "corrected_sentence": "妹妹很快就算出了作业的答案。", "error_description": "错误在多出的“去”。“算出”表示经过计算得出结果，不能接趋向补语“去”；应删去“去”，写成“算出了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '26503c15-eeab-4ed0-8337-4c518cf997e1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87908, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "你把这个数算出了来。", "corrected_sentence": "你把这个数算出来了。", "error_description": "错误在“了”和“来”的位置。“算出来”是固定的结果补语，“了”应放在句末，写成“算出来了”；“了”不能插在“出”和“来”之间。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '26503c15-eeab-4ed0-8337-4c518cf997e1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
