INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87909, 1, 'prompt1_core', '{"pos": "量词", "semantic_class": "function", "definition": "首是用来数歌和诗的量词，“一首”就是一支歌或一首诗。", "primary_collocate": null, "pronunciation": "shǒu", "ipa": "ʂoʊ˨˩˦", "syllable_count": 1, "sentences": [{"text": "我会唱一首中文歌。", "target_word": "首", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师教我们读一首诗。", "target_word": "首", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她写了一首短诗。", "target_word": "首", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这首歌很好听。", "target_word": "首", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "你再给我们唱一首吧。", "target_word": "首", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他给妈妈弹了一首钢琴曲。", "target_word": "首", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这首诗是李白写的。", "target_word": "首", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我最喜欢这首歌。", "target_word": "首", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他念了两首古诗。", "target_word": "首", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子们在学一首新歌。", "target_word": "首", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "数歌和诗的量词", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '14147f2a-e52b-4b73-85e3-382a3d8c63ac') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_