INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87909, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "首", "is_correct": true, "explanation": "正确。首（shǒu，第三声）是量词，用于诗和歌曲。"}, {"text": "收", "is_correct": false, "explanation": "收（shōu，第一声）与首（shǒu，第三声）声调不同，意思是收取、收拾，不是量词。"}, {"text": "寿", "is_correct": false, "explanation": "寿（shòu，第四声）与首（shǒu，第三声）声调不同，意思是寿命。"}, {"text": "受", "is_correct": false, "explanation": "受（shòu，第四声）与首（shǒu，第三声）声调不同，意思是接受、遭受。"}, {"text": "瘦", "is_correct": false, "explanation": "瘦（shòu，第四声）与首（shǒu，第三声）声调不同，意思是身体少肉。"}], "explanations": {"首": "正确。首（shǒu，第三声）是量词，用于诗和歌曲。", "收": "收（shōu，第一声）与首（shǒu，第三声）声调不同，意思是收取、收拾，不是量词。", "寿": "寿（shòu，第四声）与首（shǒu，第三声）声调不同，意思是寿命。", "受": "受（shòu，第四声）与首（shǒu，第三声）声调不同，意思是接受、遭受。", "瘦": "瘦（shòu，第四声）与首（shǒu，第三声）声调不同，意思是身体少肉。"}, "sentence_index": null, "correct_answer": "首"}, "level_3": {"options": [{"text": "首", "is_correct": true, "explanation": "正确。“首”是量词，用于诗和歌，“一首中文歌”搭配自然。"}, {"text": "本", "is_correct": false, "explanation": "搭配：“本”用于书册，不能用来数“歌”。"}, {"text": "篇", "is_correct": false, "explanation": "语义：“篇”指文章、小说等文字作品，歌曲不属于这类。"}, {"text": "座", "is_correct": false, "explanation": "体貌：“座”用于山、桥等大型固定的东西，歌曲不是这种事物。"}], "explanations": {"首": "正确。“首”是量词，用于诗和歌，“一首中文歌”搭配自然。", "本": "搭配：“本”用于书册，不能用来数“歌”。", "篇": "语义：“篇”指文章、小说等文字作品，歌曲不属于这类。", "座": "体貌：“座”用于山、桥等大型固定的东西，歌曲不是这种事物。"}, "sentence_index": 0, "correct_answer": "首"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他写了一首文章。", "explanation": "这里应该用〈篇〉。首用于诗词、歌曲，文章要用“篇”。"}, {"text": "我昨天看了一首电影。", "explanation": "这里应该用〈部〉。首用于诗词、歌曲，电影要用“部”。"}, {"text": "我买了一首书。", "explanation": "这里应该用〈本〉。首只用于诗词、歌曲，书要用“本”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6fcd30b9-9649-49b6-a32a-d303d4af5e0e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_ve