INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87914, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "形容词，一连串的；许多相互关联的。", "primary_collocate": null, "pronunciation": "yí xì liè", "ipa": "i˧˥ ɕi˥˩ liɛ˥˩", "syllable_count": 3, "sentences": [{"text": "政府提出了一系列新措施。", "target_word": "一系列", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "学校办了一系列有意思的活动。", "target_word": "一系列", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "医生给他做了一系列检查。", "target_word": "一系列", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这家出版社出了一系列儿童书。", "target_word": "一系列", "complexity_tier": "T3", "furigana": "zhè jiā chū bǎn shè chū le yí xì liè ér tóng shū", "sentence_source": "generated"}, {"text": "老师教我们一系列学习方法。", "target_word": "一系列", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "公司为新产品做了一系列广告。", "target_word": "一系列", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她参加了一系列关于环保的会议。", "target_word": "一系列", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "为了提高成绩，他定了一系列计划。", "target_word": "一系列", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这一系列问题都和水有关系。", "target_word": "一系列", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "博物馆里有一系列关于古代生活的照片。", "target_word": "一系列", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "一连串、相互关联的许多同类事物", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '14147f2a-e52b-4b73-85e3-382a3d8c63ac') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87914, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "一系列", "is_correct": true, "explanation": "正确。“一系列”表示许多相互关联的措施，与“提出”的语境相符。"}, {"text": "固执", "is_correct": false, "explanation": "语义：“固执”形容人的性格，不能修饰“措施”。"}, {"text": "瘦小", "is_correct": false, "explanation": "搭配：“瘦小”形容人或动物的身材，不能修饰“措施”。"}, {"text": "冰冷", "is_correct": false, "explanation": "语义：“冰冷”指温度低或态度冷淡，不能用来修饰“措施”。"}], "explanations": {"一系列": "正确。“一系列”表示许多相互关联的措施，与“提出”的语境相符。", "固执": "语义：“固执”形容人的性格，不能修饰“措施”。", "瘦小": "搭配：“瘦小”形容人或动物的身材，不能修饰“措施”。", "冰冷": "语义：“冰冷”指温度低或态度冷淡，不能用来修饰“措施”。"}, "sentence_index": 0, "correct_answer": "一系列"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "桌上放着一系列纸。", "explanation": "这里应该用〈一叠〉。“一系列”指一件接着一件、相互关联的很多事，不能用来数一叠纸，应该用“一叠”。"}, {"text": "操场上有一系列孩子。", "explanation": "这里应该用〈一群〉。“一系列”不用来形容人群，应该用“一群”。"}, {"text": "冰箱里有一系列牛奶。", "explanation": "这里应该用〈一些〉。“一系列”指相互关联的事，冰箱里的牛奶之间没有这种关系，应该用“一些”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6fcd30b9-9649-49b6-a32a-d303d4af5e0e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87914, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "一系列", "is_correct": true, "explanation": "正确。“一系列”表示一组相互关联的会议，符合句意。"}, {"text": "慵懒", "is_correct": false, "explanation": "语义：“慵懒”形容人的状态，不能修饰“会议”。"}, {"text": "潮湿", "is_correct": false, "explanation": "搭配：“潮湿”形容天气或物体，不能修饰“会议”。"}, {"text": "柔软", "is_correct": false, "explanation": "搭配：“柔软”形容质地，不能修饰“会议”。"}], "explanations": {"一系列": "正确。“一系列”表示一组相互关联的会议，符合句意。", "慵懒": "语义：“慵懒”形容人的状态，不能修饰“会议”。", "潮湿": "搭配：“潮湿”形容天气或物体，不能修饰“会议”。", "柔软": "搭配：“柔软”形容质地，不能修饰“会议”。"}, "sentence_index": 6, "correct_answer": "一系列"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他是我的一系列朋友。", "explanation": "这里应该用〈位〉。“一系列”不能用来数一个朋友，应该用“位”或“个”。"}, {"text": "一系列学生在操场上跑步。", "explanation": "这里应该用〈名〉。“一系列”不用来数一名学生，应该用“名”。"}, {"text": "他家养着一系列猫。", "explanation": "这里应该用〈只〉。“一系列”不用来数一只猫，应该用“只”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6fcd30b9-9649-49b6-a32a-d303d4af5e0e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87914, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "学校为新学期安排了的一系列活动。", "corrected_sentence": "学校为新学期安排了一系列活动。", "error_description": "错误：“的”放在“安排了”和“一系列”之间，多余。正确：“安排了一系列活动”，“的”不能插在动词与“一系列”之间。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6fcd30b9-9649-49b6-a32a-d303d4af5e0e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87914, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他参加了一个一系列培训，收获很大。", "corrected_sentence": "他参加了一系列培训，收获很大。", "error_description": "“一系列”已含数量，前面不能再加“一个”。应说“一系列培训”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6fcd30b9-9649-49b6-a32a-d303d4af5e0e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
