INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87915, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "神是故事里很厉害的人物，大家都很尊敬他。", "primary_collocate": null, "pronunciation": "shén", "ipa": "ʂən˧˥", "syllable_count": 1, "sentences": [{"text": "故事里的神能让天下雨。", "target_word": "神", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "故事里这个神住在山上，大家都很尊敬他。", "target_word": "神", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们爱听神的故事。", "target_word": "神", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "书里有一个很会飞的神。", "target_word": "神", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "故事里，神帮助了那个穷人。", "target_word": "神", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个神有三个头，样子很怪。", "target_word": "神", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷给我讲了一个神的故事。", "target_word": "神", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电影里的神有很多本领。", "target_word": "神", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "村里人说山里住着一个神。", "target_word": "神", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在故事里，神常常救好人。", "target_word": "神", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一位神", "label": "量词"}, {"form": "神仙", "label": "复合"}, {"form": "神话", "label": "复合"}], "register": "通用", "sense_fingerprint": "神：故事里本领很大、受人尊敬的人物", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '84eaa279-90ef-4dbd-b39e-63b4c5dbbc90') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87915, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "神", "is_correct": true, "explanation": "正确：神，故事里本领很大、受人尊敬的人物。"}, {"text": "身", "is_correct": false, "explanation": "shēn（第一声）与 shén（第二声）声调不同，意思是身体。"}, {"text": "绳", "is_correct": false, "explanation": "shéng（第二声）与 shén 韵母不同（ng 与 n），意思是绳子。"}, {"text": "审", "is_correct": false, "explanation": "shěn（第三声）与 shén 声调不同，意思是审查。"}, {"text": "肾", "is_correct": false, "explanation": "shèn（第四声）与 shén 声调不同，意思是肾脏。"}, {"text": "深", "is_correct": false, "explanation": "shēn（第一声）与 shén 声调不同，意思是深浅。"}], "explanations": {"神": "正确：神，故事里本领很大、受人尊敬的人物。", "身": "shēn（第一声）与 shén（第二声）声调不同，意思是身体。", "绳": "shéng（第二声）与 shén 韵母不同（ng 与 n），意思是绳子。", "审": "shěn（第三声）与 shén 声调不同，意思是审查。", "肾": "shèn（第四声）与 shén 声调不同，意思是肾脏。", "深": "shēn（第一声）与 shén 声调不同，意思是深浅。"}, "sentence_index": null, "correct_answer": "神"}, "level_3": {"options": [{"text": "神", "is_correct": true, "explanation": "正确：神，故事里能让天下下雨的人物。"}, {"text": "课本", "is_correct": false, "explanation": "语义：课本是学习用的书，不能让天下下雨。"}, {"text": "书包", "is_correct": false, "explanation": "语义：书包是装书的袋子，与故事里的雨无关。"}, {"text": "作业", "is_correct": false, "explanation": "配价：“让天下雨”需要有能力的施事，“作业”不能充当这样的主语。"}], "explanations": {"神": "正确：神，故事里能让天下下雨的人物。", "课本": "语义：课本是学习用的书，不能让天下下雨。", "书包": "语义：书包是装书的袋子，与故事里的雨无关。", "作业": "配价：“让天下雨”需要有能力的施事，“作业”不能充当这样的主语。"}, "sentence_index": 0, "correct_answer": "神"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "隔壁的神每天买菜做饭，很辛苦。", "explanation": "这里应该用〈阿姨〉。“神”指故事里很厉害的人物，不指现实中的邻居，不能用来说日常生活中做家务的人。"}, {"text": "书里有一只很会飞的神。", "explanation": "这里应该用〈位〉。“只”多用于动物或单个物件，神要用量词“位”。"}, {"text": "我家的神很聪明，会听懂主人的话。", "explanation": "这里应该用〈小狗〉。“神”指故事里很厉害的人物，不指家里养的宠物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '833ea5fc-85bc-447f-ba8f-2c270206bdec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87915, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "神", "is_correct": true, "explanation": "正确：神，故事里本领很大、受人尊敬的人物。"}, {"text": "甚", "is_correct": false, "explanation": "shèn（第四声）与 shén 声调不同，意思是很、非常。"}, {"text": "慎", "is_correct": false, "explanation": "shèn（第四声）与 shén 声调不同，意思是谨慎。"}, {"text": "申", "is_correct": false, "explanation": "shēn（第一声）与 shén 声调不同，意思是申请、陈述。"}, {"text": "婶", "is_correct": false, "explanation": "shěn（第三声）与 shén 声调不同，意思是婶婶。"}], "explanations": {"神": "正确：神，故事里本领很大、受人尊敬的人物。", "甚": "shèn（第四声）与 shén 声调不同，意思是很、非常。", "慎": "shèn（第四声）与 shén 声调不同，意思是谨慎。", "申": "shēn（第一声）与 shén 声调不同，意思是申请、陈述。", "婶": "shěn（第三声）与 shén 声调不同，意思是婶婶。"}, "sentence_index": null, "correct_answer": "神"}, "level_3": {"options": [{"text": "神", "is_correct": true, "explanation": "正确：神，故事里本领很大的人物。"}, {"text": "体积", "is_correct": false, "explanation": "语义：体积指物体占的空间，没有“故事”可讲。"}, {"text": "音量", "is_correct": false, "explanation": "语义：音量指声音的大小，不能讲成故事。"}, {"text": "温度", "is_correct": false, "explanation": "搭配：“温度”常与“高、低、升、降”搭配，不说“讲温度的故事”。"}], "explanations": {"神": "正确：神，故事里本领很大的人物。", "体积": "语义：体积指物体占的空间，没有“故事”可讲。", "音量": "语义：音量指声音的大小，不能讲成故事。", "温度": "搭配：“温度”常与“高、低、升、降”搭配，不说“讲温度的故事”。"}, "sentence_index": 6, "correct_answer": "神"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这位老人手里有一本神，每天都看。", "explanation": "这里应该用〈位〉。“本”用于书、本子，神要用量词“位”。"}, {"text": "我的神很重，每天都背着。", "explanation": "这里应该用〈书包〉。“神”指故事里很厉害的人物，不能指可以背在身上的物品。"}, {"text": "神每天都开车送我去上学。", "explanation": "这里应该用〈爸爸〉。“神”指故事里很厉害的人物，不指现实中每天开车送孩子的家人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '833ea5fc-85bc-447f-ba8f-2c270206bdec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87915, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "书里写着一只神，他会飞。", "corrected_sentence": "书里写着一位神，他会飞。", "error_description": "“神”的量词应用“位”，不用“只”。“只”多用于动物，应改为“一位神”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '833ea5fc-85bc-447f-ba8f-2c270206bdec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87915, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "一个厉害神住在山上。", "corrected_sentence": "一个厉害的神住在山上。", "error_description": "“厉害”修饰“神”时要加“的”，应为“厉害的神”，不能说“厉害神”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '833ea5fc-85bc-447f-ba8f-2c270206bdec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
