INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87921, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "身上是人或动物的身体上面。", "primary_collocate": null, "pronunciation": "shēn shang", "ipa": "ʂən˥ ʂaŋ", "syllable_count": 2, "sentences": [{"text": "他身上穿着一件红色的外套。", "target_word": "身上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小狗身上有很多白毛。", "target_word": "身上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件衣服穿在他身上很合适。", "target_word": "身上", "complexity_tier": "T3", "furigana": "zhè jiàn yīfu chuān zài tā shēnshang hěn héshì.", "sentence_source": "generated"}, {"text": "小猫跳到我身上睡觉。", "target_word": "身上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他身上背着一个很大的书包。", "target_word": "身上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那只老虎身上有黑色的条纹。", "target_word": "身上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子身上盖着一条小被子。", "target_word": "身上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她身上戴着一条漂亮的项链。", "target_word": "身上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这只鸟身上的羽毛是蓝色的。", "target_word": "身上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天太冷了，他身上多穿了两件衣服。", "target_word": "身上", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "通用", "sense_fingerprint": "人或动物的身体上面，穿戴、携带、附着东西的位置", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '410cbcc6-88e5-4dbf-9766-d970c97f3598') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87921, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "身上", "is_correct": true, "explanation": "正确：身上指人或动物身体的上面，衣服穿在身上。"}, {"text": "手上", "is_correct": false, "explanation": "语义：手上指手的表面，手不能穿衣服。"}, {"text": "头上", "is_correct": false, "explanation": "搭配：衣服穿在身体躯干上，头上只能戴帽子，不能说“穿”。"}, {"text": "脸上", "is_correct": false, "explanation": "语义：脸上指面部，衣服不会穿在脸上。"}], "explanations": {"身上": "正确：身上指人或动物身体的上面，衣服穿在身上。", "手上": "语义：手上指手的表面，手不能穿衣服。", "头上": "搭配：衣服穿在身体躯干上，头上只能戴帽子，不能说“穿”。", "脸上": "语义：脸上指面部，衣服不会穿在脸上。"}, "sentence_index": 0, "correct_answer": "身上"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的身上很健康，每天都坚持锻炼。", "explanation": "这里应该用〈身体〉。身上指身体的表面位置，说人健康要用〈身体〉。"}, {"text": "老师一直在身上陪着我写作业。", "explanation": "这里应该用〈身边〉。身上指身体的表面，陪伴在旁边要用〈身边〉。"}, {"text": "这张桌子身上放着一本书。", "explanation": "这里应该用〈上面〉。身上指人或动物身体的表面，桌子不是身体，表示物体表面的位置要用〈上面〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3d1a9c34-0345-46ff-8cb2-0810e91fa327') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87921, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "身上", "is_correct": true, "explanation": "正确：被子盖在人身上，身上指身体表面。"}, {"text": "脚下", "is_correct": false, "explanation": "语义：脚下指脚的下方，被子不会盖在脚下。"}, {"text": "桌上", "is_correct": false, "explanation": "搭配：孩子盖被子的处所应是身体，“桌上”不能与此搭配。"}, {"text": "眼前", "is_correct": false, "explanation": "语义：眼前指眼睛的前方，被子不会盖在眼前。"}], "explanations": {"身上": "正确：被子盖在人身上，身上指身体表面。", "脚下": "语义：脚下指脚的下方，被子不会盖在脚下。", "桌上": "搭配：孩子盖被子的处所应是身体，“桌上”不能与此搭配。", "眼前": "语义：眼前指眼睛的前方，被子不会盖在眼前。"}, "sentence_index": 6, "correct_answer": "身上"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "心脏在他身上剧烈地跳动。", "explanation": "身上指身体的表面，心脏在身体内部，这里不能用“身上”。"}, {"text": "他身上有一扇门，很奇怪。", "explanation": "这里应该用〈身后〉。身上指身体的表面，门在人的后面要用〈身后〉。"}, {"text": "会议在他身上举行了两个小时。", "explanation": "身上只指身体的表面，不能用来表示会议等活动的场所。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3d1a9c34-0345-46ff-8cb2-0810e91fa327') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87921, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "妈妈披着一件毛衣身上。", "corrected_sentence": "妈妈披着一件毛衣在身上。", "error_description": "介词错误：处所“身上”位于“披着一件毛衣”之后，前面要加“在”，漏掉“在”。正确形式是“披着一件毛衣在身上”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3d1a9c34-0345-46ff-8cb2-0810e91fa327') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87921, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我身上带着了身份证。", "corrected_sentence": "我身上带着身份证。", "error_description": "体标错误：“着”与“了”不能同时用在动词后，句中多加了“了”。错误形式是“带着了身份证”，正确形式是“带着身份证”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3d1a9c34-0345-46ff-8cb2-0810e91fa327') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
