INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87923, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "内能是一个东西里面所有很小很小的粒子运动时带的能量，加上粒子之间相互作用的能量。", "primary_collocate": null, "pronunciation": "nèi néng", "ipa": "/nei˥˩ nəŋ˧˥/", "syllable_count": 2, "sentences": [{"text": "内能是物体里面的能量。", "target_word": "内能", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "水热了，它的内能就变大了。", "target_word": "内能", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "冰变成水时，内能会增加。", "target_word": "内能", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这杯热水的内能比冷水大。", "target_word": "内能", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "铁块很热，说明它的内能高。", "target_word": "内能", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们学过什么是内能。", "target_word": "内能", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说，同一杯水，温度高，内能就大。", "target_word": "内能", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "搓手的时候，手的内能变大了。", "target_word": "内能", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一杯水和一桶水，哪个内能大？", "target_word": "内能", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "内能和温度有关系。", "target_word": "内能", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "物体内部微小粒子运动及相互作用的能量总和", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a298fe30-4cb1-44d1-ba83-8e5984f2584b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87923, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "温度", "is_correct": false, "explanation": "语义：温度表示冷热程度，不是能量，不能作定义的主语。"}, {"text": "体积", "is_correct": false, "explanation": "语义：体积指物体所占空间的大小，不是能量。"}, {"text": "内能", "is_correct": true, "explanation": "内能：指物体里面所有粒子运动时带的能量，与“能量”的定义相符。"}, {"text": "内部", "is_correct": false, "explanation": "搭配：内部是方位词，不能与“能量”构成定义句的主语。"}], "explanations": {"温度": "语义：温度表示冷热程度，不是能量，不能作定义的主语。", "体积": "语义：体积指物体所占空间的大小，不是能量。", "内能": "内能：指物体里面所有粒子运动时带的能量，与“能量”的定义相符。", "内部": "搭配：内部是方位词，不能与“能量”构成定义句的主语。"}, "sentence_index": 0, "correct_answer": "内能"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这辆跑得很快的汽车有很大的内能。", "explanation": "应该用〈动能〉。动能指物体整体运动的能量；内能指物体内部粒子的能量，汽车整体跑得快并不等于内能大。"}, {"text": "他练了十年，内能很深。", "explanation": "应该用〈内力〉。内力指人体内练出的功力；内能是物理学术语，指物体内部粒子的能量，不用于人。"}, {"text": "这个吊在空中的重物有很大的内能。", "explanation": "应该用〈势能〉。势能指物体因位置而具有的能量；内能只指物体内部粒子的动能和势能之和，与重物的位置无关。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '73ed49ee-02fe-4815-a4f8-121fa8aa9f1c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87923, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "颜色", "is_correct": false, "explanation": "搭配：颜色不说“大”，应说“深”“浅”，与“就大”不搭配。"}, {"text": "年级", "is_correct": false, "explanation": "语义：年级指学习阶段，没有大小之说，句意不通。"}, {"text": "方向", "is_correct": false, "explanation": "语义：方向没有大小，不能说“温度高，方向就大”。"}, {"text": "内能", "is_correct": true, "explanation": "内能：温度高时内能就大，与“温度高，……就大”的语义相符。"}], "explanations": {"颜色": "搭配：颜色不说“大”，应说“深”“浅”，与“就大”不搭配。", "年级": "语义：年级指学习阶段，没有大小之说，句意不通。", "方向": "语义：方向没有大小，不能说“温度高，方向就大”。", "内能": "内能：温度高时内能就大，与“温度高，……就大”的语义相符。"}, "sentence_index": 6, "correct_answer": "内能"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "用温度计测量水的内能。", "explanation": "应该用〈温度〉。温度计测量的是温度，内能是能量的总和，不能用温度计直接测量。"}, {"text": "用天平称出了这块铁的内能。", "explanation": "应该用〈质量〉。天平称的是质量，内能不是能用天平称出的量。"}, {"text": "这个苹果受到的内能很大。", "explanation": "应该用〈重力〉。重力是地球对物体的引力，物体可以受到重力；内能不是外力，不能说受到。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '73ed49ee-02fe-4815-a4f8-121fa8aa9f1c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87923, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "加热后，水多了一个内能。", "corrected_sentence": "加热后，水多了一点内能。", "error_description": "错误：“内能”前的量词用“个”。“内能”是抽象名词，数量要用“点”“些”等，正确为“一点内能”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '73ed49ee-02fe-4815-a4f8-121fa8aa9f1c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87923, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "冰变成水以后，它的内能增加了了。", "corrected_sentence": "冰变成水以后，它的内能增加了。", "error_description": "错误：“增加”后面多了一个“了”。“了”只用一次，正确为“增加了”，“增加了了”不符合汉语习惯。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '73ed49ee-02fe-4815-a4f8-121fa8aa9f1c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
