INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87924, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '73ed49ee-02fe-4815-a4f8-121fa8aa9f1c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87924, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "物体内部分子无规则运动的动能和分子势能的总和。", "primary_collocate": null, "pronunciation": "nèi néng", "ipa": "/nei˥˩ nəŋ˧˥/", "syllable_count": 2, "sentences": [{"text": "物体的内能包括分子动能和势能。", "target_word": "内能", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "内能是分子动能和势能的总和。", "target_word": "内能", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "对物体做功，可以改变它的内能。", "target_word": "内能", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "气体受热后，内能会变大。", "target_word": "内能", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "热传递能改变物体的内能。", "target_word": "内能", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "同一物体，温度越高，内能越大。", "target_word": "内能", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "内能的单位是焦耳。", "target_word": "内能", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一块冰也有内能。", "target_word": "内能", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "分子运动越快，物体的内能越大。", "target_word": "内能", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这道题让我们计算气体的内能。", "target_word": "内能", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "物理学术语：分子动能与分子势能的总和", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a298fe30-4cb1-44d1-ba83-8e5984f2584b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87924, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "温度", "is_correct": false, "explanation": "语义：温度表示冷热程度，不包括分子动能和势能。"}, {"text": "体积", "is_correct": false, "explanation": "语义：体积指物体所占空间的大小，不包括能量。"}, {"text": "能力", "is_correct": false, "explanation": "搭配：能力多与“强”“弱”搭配，不作物理量的主语。"}, {"text": "内能", "is_correct": true, "explanation": "内能：物体内部分子动能与势能的总和，与“包括分子动能和势能”相符。"}], "explanations": {"温度": "语义：温度表示冷热程度，不包括分子动能和势能。", "体积": "语义：体积指物体所占空间的大小，不包括能量。", "能力": "搭配：能力多与“强”“弱”搭配，不作物理量的主语。", "内能": "内能：物体内部分子动能与势能的总和，与“包括分子动能和势能”相符。"}, "sentence_index": 0, "correct_answer": "内能"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个吊在空中的重物有很大的内能。", "explanation": "应该用〈势能〉。势能指物体因位置而具有的能量；内能只指物体内部分子的动能和势能之和，不包括物体整体的位置能。"}, {"text": "用温度计测量房间的内能。", "explanation": "应该用〈温度〉。温度计测量的是温度，内能是能量，不用温度计测量。"}, {"text": "用天平称出了这袋米的内能。", "explanation": "应该用〈质量〉。天平称的是质量，内能不是能用天平称出的量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '73ed49ee-02fe-4815-a4f8-121fa8aa9f1c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87924, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "温度", "is_correct": false, "explanation": "语义：温度的单位是摄氏度或开尔文，不是焦耳。"}, {"text": "功率", "is_correct": false, "explanation": "语义：功率的单位是瓦特，不是焦耳。"}, {"text": "内部", "is_correct": false, "explanation": "搭配：内部是方位词，不是可以度量的物理量，没有单位。"}, {"text": "内能", "is_correct": true, "explanation": "内能：是物理量，它的单位是焦耳，与句意相符。"}], "explanations": {"温度": "语义：温度的单位是摄氏度或开尔文，不是焦耳。", "功率": "语义：功率的单位是瓦特，不是焦耳。", "内部": "搭配：内部是方位词，不是可以度量的物理量，没有单位。", "内能": "内能：是物理量，它的单位是焦耳，与句意相符。"}, "sentence_index": 6, "correct_answer": "内能"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这颗高速飞行的子弹有很大的内能。", "explanation": "应该用〈动能〉。动能指物体整体运动的能量；内能指物体内部粒子的能量，不由整体速度决定。"}, {"text": "这块石头受到很大的内能。", "explanation": "应该用〈重力〉。重力是地球对物体的引力，物体可以受到重力；内能不是外力，不能说受到。"}, {"text": "他练功十年，内能很深厚。", "explanation": "应该用〈内力〉。内力指人体内练出的功力；内能是物理学术语，指物体内部粒子的能量，不用于人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '73ed49ee-02fe-4815-a4f8-121fa8aa9f1c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87924, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "气体受热后，内能变了大。", "corrected_sentence": "气体受热后，内能变大了。", "error_description": "错误：结果补语“大”应紧跟动词“变”，“了”放在补语之后，正确为“变大了”，“变了大”不符合语序。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '73ed49ee-02fe-4815-a4f8-121fa8aa9f1c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87924, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个系统有一定个的内能。", "corrected_sentence": "这个系统有一定量的内能。", "error_description": "错误：“内能”前的量词用“个”。“内能”是抽象的量，应用“量”，正确为“一定量的内能”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '73ed49ee-02fe-4815-a4f8-121fa8aa9f1c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
