INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87932, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "君主的女儿。", "primary_collocate": null, "pronunciation": "gōng zhǔ", "ipa": "kʊŋ˥ ʈʂu˨˩˦", "syllable_count": 2, "sentences": [{"text": "书里写了一位聪明的公主。", "target_word": "公主", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公主戴着一顶金色的皇冠。", "target_word": "公主", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个国家的公主要结婚了。", "target_word": "公主", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公主从小就在宫里长大。", "target_word": "公主", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "女孩们都喜欢看公主的故事。", "target_word": "公主", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公主笑着对国王说：“谢谢爸爸。”", "target_word": "公主", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在电影里演过一位公主。", "target_word": "公主", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老国王最爱他的小公主。", "target_word": "公主", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公主骑着白马来到了河边。", "target_word": "公主", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们打扮成公主和王子。", "target_word": "公主", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "位", "label": "量词"}, {"form": "个", "label": "量词"}, {"form": "小公主", "label": "复合"}], "register": "中性", "sense_fingerprint": "君主的女儿", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '78bd22d5-58b2-46ac-bd58-f8a4351aa496') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87932, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "公主", "is_correct": true, "explanation": "正确。“聪明的”和“一位”都要求人物名词，公主符合书里写的人物。"}, {"text": "猪", "is_correct": false, "explanation": "搭配：量词“位”只用于人，不能和“猪”搭配。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：桌子不是能写进书里、具有聪明品质的人物。"}, {"text": "雨", "is_correct": false, "explanation": "语义：雨是天气现象，不能用“聪明的”来形容，也不能成为书中人物。"}], "explanations": {"公主": "正确。“聪明的”和“一位”都要求人物名词，公主符合书里写的人物。", "猪": "搭配：量词“位”只用于人，不能和“猪”搭配。", "桌子": "语义：桌子不是能写进书里、具有聪明品质的人物。", "雨": "语义：雨是天气现象，不能用“聪明的”来形容，也不能成为书中人物。"}, "sentence_index": 0, "correct_answer": "公主"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "老国王去世后，公主立即登基。", "explanation": "这里应该用〈女王〉。登基指君主即位，公主不是君主，不能说“公主登基”。"}, {"text": "这位公主的父亲是一个普通的农民。", "explanation": "这里应该用〈姑娘〉。公主指君主的女儿，父亲是普通农民就不能称公主。"}, {"text": "那位公主颁布了新的法律。", "explanation": "这里应该用〈国王〉。颁布法律是君主的权力，公主不能这样用。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4bdfd8fd-3c6f-42b0-8fce-715d5e9632d9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87932, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "公主", "is_correct": true, "explanation": "正确。“演过一位”后面需要人物角色，公主符合。"}, {"text": "电影", "is_correct": false, "explanation": "搭配：“演过”要求角色名词，且量词“位”不能修饰“电影”。"}, {"text": "马", "is_correct": false, "explanation": "搭配：量词“位”只用于人，不能说“一位马”。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头不是能被扮演的角色，“演过”说的是扮演人物。"}], "explanations": {"公主": "正确。“演过一位”后面需要人物角色，公主符合。", "电影": "搭配：“演过”要求角色名词，且量词“位”不能修饰“电影”。", "马": "搭配：量词“位”只用于人，不能说“一位马”。", "石头": "语义：石头不是能被扮演的角色，“演过”说的是扮演人物。"}, "sentence_index": 6, "correct_answer": "公主"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他一点家务都不做，真像个公主。", "explanation": "这里用的是“娇气、爱被伺候的人”的引申义，不是“君主的女儿”的本义。"}, {"text": "街上走过一头公主。", "explanation": "这里应该用〈位〉。公主指人，不能用量词“头”。"}, {"text": "宴会上坐着一条公主。", "explanation": "这里应该用〈位〉。公主指人，不能用量词“条”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4bdfd8fd-3c6f-42b0-8fce-715d5e9632d9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87932, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "宫里住着三只公主。", "corrected_sentence": "宫里住着三位公主。", "error_description": "错误：量词用“只”，说成“三只公主”。正确：应说“三位公主”。“公主”指人，量词应用“位”或“个”，不能用“只”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4bdfd8fd-3c6f-42b0-8fce-715d5e9632d9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87932, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那只可爱的小公主在花园里玩。", "corrected_sentence": "那位可爱的小公主在花园里玩。", "error_description": "错误：量词用“只”，说成“那只可爱的小公主”。正确：应说“那位可爱的小公主”。“公主”指人，量词应用“位”或“个”，不能用“只”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4bdfd8fd-3c6f-42b0-8fce-715d5e9632d9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
