INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87945, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "圈是弯成一个圆形的线或东西。", "primary_collocate": null, "pronunciation": "quān", "ipa": "tɕʰɥɛn˥", "syllable_count": 1, "sentences": [{"text": "她在纸上画了一个圈。", "target_word": "圈", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师在错字上画了一个红圈。", "target_word": "圈", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他用铁丝弯成一个圈。", "target_word": "圈", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "绳子绕成了一个小圈。", "target_word": "圈", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她把一根橡皮筋拉成一个圈，套在笔上。", "target_word": "圈", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子用彩色纸条粘成了一个圈。", "target_word": "圈", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "请把这根线绕成一个圈。", "target_word": "圈", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把电线卷成圈，放进了箱子。", "target_word": "圈", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把一根细绳打成一个圈，系在桌腿上。", "target_word": "圈", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "铁丝弯成圈以后，可以套在木棒上。", "target_word": "圈", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "圈圈", "label": "重叠"}], "register": "中性", "sense_fingerprint": "线或细长的东西弯成的圆形", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '14147f2a-e52b-4b73-85e3-382a3d8c63ac') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87945, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "圈", "is_correct": true, "explanation": "正确答案：圈（quān，第一声），指弯成圆形的线或东西。"}, {"text": "权", "is_correct": false, "explanation": "quán（第二声）与 quān（第一声）声调不同，意思是权利。"}, {"text": "劝", "is_correct": false, "explanation": "quàn（第四声）与 quān（第一声）声调不同，意思是劝告。"}, {"text": "冠", "is_correct": false, "explanation": "guān 与 quān 声母不同（g 与 q）；读 guān 的“冠”指帽子，与“圈”不同。"}], "explanations": {"圈": "正确答案：圈（quān，第一声），指弯成圆形的线或东西。", "权": "quán（第二声）与 quān（第一声）声调不同，意思是权利。", "劝": "quàn（第四声）与 quān（第一声）声调不同，意思是劝告。", "冠": "guān 与 quān 声母不同（g 与 q）；读 guān 的“冠”指帽子，与“圈”不同。"}, "sentence_index": null, "correct_answer": "圈"}, "level_3": {"options": [{"text": "圈", "is_correct": true, "explanation": "正确答案：“画了一个圈”，“圈”是在纸上画出的圆形线条。"}, {"text": "声音", "is_correct": false, "explanation": "语义：声音不能用笔画在纸上，与“在纸上画”不符。"}, {"text": "问题", "is_correct": false, "explanation": "搭配：“画”后面一般接图形、图画，不说“画问题”。"}, {"text": "计划", "is_correct": false, "explanation": "搭配：“画”不接“计划”，应说“制订计划”。"}], "explanations": {"圈": "正确答案：“画了一个圈”，“圈”是在纸上画出的圆形线条。", "声音": "语义：声音不能用笔画在纸上，与“在纸上画”不符。", "问题": "搭配：“画”后面一般接图形、图画，不说“画问题”。", "计划": "搭配：“画”不接“计划”，应说“制订计划”。"}, "sentence_index": 0, "correct_answer": "圈"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的手上戴着一根圈。", "explanation": "这里应该用〈个〉。“根”用于细长的条状物，圆环形的东西不用“根”计量。"}, {"text": "他用一根直圈把木板固定住了。", "explanation": "这里应该用〈铁丝〉。圈指弯成圆形的东西，不能是直的；直的线要说“铁丝”。"}, {"text": "他用一个圈装了三斤苹果。", "explanation": "这里应该用〈篮子〉。圈指弯成的环形东西，不能用来装东西；装苹果要用〈篮子〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6fcd30b9-9649-49b6-a32a-d303d4af5e0e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87945, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "圈", "is_correct": true, "explanation": "正确答案：圈（quān，第一声），指弯成圆形的线或东西。"}, {"text": "全", "is_correct": false, "explanation": "quán（第二声）与 quān（第一声）声调不同，意思是全部。"}, {"text": "拳", "is_correct": false, "explanation": "quán（第二声）与 quān（第一声）声调不同，意思是拳头。"}, {"text": "关", "is_correct": false, "explanation": "guān 与 quān 声母不同（g 与 q），意思是关系。"}, {"text": "捐", "is_correct": false, "explanation": "juān 与 quān 声母不同（j 与 q，q 送气），意思是捐献。"}], "explanations": {"圈": "正确答案：圈（quān，第一声），指弯成圆形的线或东西。", "全": "quán（第二声）与 quān（第一声）声调不同，意思是全部。", "拳": "quán（第二声）与 quān（第一声）声调不同，意思是拳头。", "关": "guān 与 quān 声母不同（g 与 q），意思是关系。", "捐": "juān 与 quān 声母不同（j 与 q，q 送气），意思是捐献。"}, "sentence_index": null, "correct_answer": "圈"}, "level_3": {"options": [{"text": "圈", "is_correct": true, "explanation": "正确答案：“绕成一个圈”，“圈”指线绕成的圆形，符合语境。"}, {"text": "城市", "is_correct": false, "explanation": "语义：线只能绕成圆、团之类的形状，不能绕成城市。"}, {"text": "故事", "is_correct": false, "explanation": "搭配：“绕”后面不接“故事”，线不能绕成故事。"}, {"text": "梦想", "is_correct": false, "explanation": "语义：“梦想”是抽象的想法，线无法绕成梦想。"}], "explanations": {"圈": "正确答案：“绕成一个圈”，“圈”指线绕成的圆形，符合语境。", "城市": "语义：线只能绕成圆、团之类的形状，不能绕成城市。", "故事": "搭配：“绕”后面不接“故事”，线不能绕成故事。", "梦想": "语义：“梦想”是抽象的想法，线无法绕成梦想。"}, "sentence_index": 6, "correct_answer": "圈"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他把铁丝弯成了一把圈，挂在墙上。", "explanation": "这里应该用〈个〉。“把”多用于有柄的器具，铁丝圈不用“把”计量。"}, {"text": "他的手上戴着一只圈。", "explanation": "这里应该用〈个〉。“只”多用于动物或成对物品中的一个，圆环形的东西不用“只”计量。"}, {"text": "孩子们把积木装进一个圈里，放在桌上。", "explanation": "这里应该用〈盒子〉。圈指弯成的环形东西，不能用来装东西；装积木要用〈盒子〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6fcd30b9-9649-49b6-a32a-d303d4af5e0e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87945, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他把铁丝绕成一根圈，挂在墙上。", "corrected_sentence": "他把铁丝绕成一个圈，挂在墙上。", "error_description": "错误：“一根圈”的量词“根”用错，应为“一个圈”。“根”用于细长条状的东西，圆环不用“根”计量。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6fcd30b9-9649-49b6-a32a-d303d4af5e0e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87945, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他把铁丝弯成了一条圈，挂在墙上。", "corrected_sentence": "他把铁丝弯成了一个圈，挂在墙上。", "error_description": "错误：量词“条”用错，应为“个”。“条”用于长条形的东西，圆圈不用“条”计量，“圈”应与量词“个”搭配。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6fcd30b9-9649-49b6-a32a-d303d4af5e0e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
