INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87946, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "环形的东西；周围一圈。", "primary_collocate": null, "pronunciation": "quān", "ipa": "tɕʰɥɛn˥", "syllable_count": 1, "sentences": [{"text": "孩子们围成一圈，中间坐着老师。", "target_word": "圈", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他绕着操场跑了三圈。", "target_word": "圈", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "湖边有一圈高高的树。", "target_word": "圈", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "月亮周围有一圈淡淡的光。", "target_word": "圈", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她在池塘边走了一圈。", "target_word": "圈", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这只狗的脖子上有一圈白毛。", "target_word": "圈", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "桌子旁边坐了一圈人。", "target_word": "圈", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子手上套着一个塑料圈。", "target_word": "圈", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在城外骑了一圈，才回家。", "target_word": "圈", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "杯子下面留下了一圈水印。", "target_word": "圈", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "圈圈", "label": "重叠"}], "register": "中性", "sense_fingerprint": "环形的东西，或环绕在周围的一圈", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '14147f2a-e52b-4b73-85e3-382a3d8c63ac') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87946, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "圈", "is_correct": true, "explanation": "正确答案：圈（quān，第一声），指环形的东西。"}, {"text": "全", "is_correct": false, "explanation": "quán（第二声）与 quān（第一声）声调不同，意思是全部。"}, {"text": "劝", "is_correct": false, "explanation": "quàn（第四声）与 quān（第一声）声调不同，意思是劝告。"}, {"text": "冠", "is_correct": false, "explanation": "guān 与 quān 声母不同（g 与 q）；读 guān 的“冠”指帽子，与“圈”不同。"}, {"text": "捐", "is_correct": false, "explanation": "juān 与 quān 声母不同（j 与 q，q 送气），意思是捐献。"}], "explanations": {"圈": "正确答案：圈（quān，第一声），指环形的东西。", "全": "quán（第二声）与 quān（第一声）声调不同，意思是全部。", "劝": "quàn（第四声）与 quān（第一声）声调不同，意思是劝告。", "冠": "guān 与 quān 声母不同（g 与 q）；读 guān 的“冠”指帽子，与“圈”不同。", "捐": "juān 与 quān 声母不同（j 与 q，q 送气），意思是捐献。"}, "sentence_index": null, "correct_answer": "圈"}, "level_3": {"options": [{"text": "圈", "is_correct": true, "explanation": "正确答案：“围成一圈”，“圈”指环形，正好形容孩子们围成的圆形。"}, {"text": "行", "is_correct": false, "explanation": "语义：“一行”是直线，与“围成”以及“中间坐着老师”的圆形情境不符。"}, {"text": "排", "is_correct": false, "explanation": "搭配：“围成”后不说“一排”，应说“排成一排”。"}, {"text": "列", "is_correct": false, "explanation": "搭配：“围成”后不说“一列”，“列”多用于队伍。"}], "explanations": {"圈": "正确答案：“围成一圈”，“圈”指环形，正好形容孩子们围成的圆形。", "行": "语义：“一行”是直线，与“围成”以及“中间坐着老师”的圆形情境不符。", "排": "搭配：“围成”后不说“一排”，应说“排成一排”。", "列": "搭配：“围成”后不说“一列”，“列”多用于队伍。"}, "sentence_index": 0, "correct_answer": "圈"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他在纸上画了一条圈。", "explanation": "这里应该用〈个〉。“条”用于细长的东西，圆圈不能用“条”计量。"}, {"text": "这块玻璃的圈有十厘米，很结实。", "explanation": "这里应该用〈厚度〉。圈只指环形的东西，不表示物体的厚薄；说玻璃的厚薄要用厚度。"}, {"text": "他在墙上挂了一根圈。", "explanation": "这里应该用〈个〉。“根”用于细长的条状物，圆圈不能用“根”计量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6fcd30b9-9649-49b6-a32a-d303d4af5e0e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87946, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "圈", "is_correct": true, "explanation": "正确答案：圈（quān，第一声），指环形的东西。"}, {"text": "权", "is_correct": false, "explanation": "quán（第二声）与 quān（第一声）声调不同，意思是权利。"}, {"text": "拳", "is_correct": false, "explanation": "quán（第二声）与 quān（第一声）声调不同，意思是拳头。"}, {"text": "关", "is_correct": false, "explanation": "guān 与 quān 声母不同（g 与 q），意思是关系。"}], "explanations": {"圈": "正确答案：圈（quān，第一声），指环形的东西。", "权": "quán（第二声）与 quān（第一声）声调不同，意思是权利。", "拳": "quán（第二声）与 quān（第一声）声调不同，意思是拳头。", "关": "guān 与 quān 声母不同（g 与 q），意思是关系。"}, "sentence_index": null, "correct_answer": "圈"}, "level_3": {"options": [{"text": "圈", "is_correct": true, "explanation": "正确答案：“坐了一圈人”，“圈”指围成环形，与“桌子旁边”的情境一致。"}, {"text": "座", "is_correct": false, "explanation": "搭配：“座”多用于山、房屋等大型固定物，不用来计量坐着的人。"}, {"text": "把", "is_correct": false, "explanation": "搭配：“把”多用于有柄的器具，不用来计量坐着的人。"}, {"text": "对", "is_correct": false, "explanation": "语义：“一对”指两个成双的人，与桌旁一群人的情境不符。"}], "explanations": {"圈": "正确答案：“坐了一圈人”，“圈”指围成环形，与“桌子旁边”的情境一致。", "座": "搭配：“座”多用于山、房屋等大型固定物，不用来计量坐着的人。", "把": "搭配：“把”多用于有柄的器具，不用来计量坐着的人。", "对": "语义：“一对”指两个成双的人，与桌旁一群人的情境不符。"}, "sentence_index": 6, "correct_answer": "圈"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他在桌上放了一座圈。", "explanation": "这里应该用〈个〉。“座”多用于山、房屋等大型固定物，圆圈不用“座”计量。"}, {"text": "农民把碗圈在桌上。", "explanation": "这里的“圈”是“用围栏关住”的意思，指围养牲畜，不能用来说把碗放在桌上；这里应该用〈放〉。"}, {"text": "他的脖子上围着一朵圈。", "explanation": "这里应该用〈个〉。“朵”用于花朵等，圆环形的东西不用“朵”计量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6fcd30b9-9649-49b6-a32a-d303d4af5e0e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87946, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "湖面上有一只淡淡的圈。", "corrected_sentence": "湖面上有一个淡淡的圈。", "error_description": "错误：量词“只”用错，应为“个”。“只”多用于动物或成对物品中的一个，圆形的东西要用“个”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6fcd30b9-9649-49b6-a32a-d303d4af5e0e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87946, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他用绳子做了一只圈，挂在门上。", "corrected_sentence": "他用绳子做了一个圈，挂在门上。", "error_description": "错误：“一只圈”的量词“只”用错，应为“一个圈”。“只”多用于动物或成对物品中的一个，圆圈要用“个”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6fcd30b9-9649-49b6-a32a-d303d4af5e0e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
