INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87953, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "学术是大学里的人研究出来的很深的学问。", "primary_collocate": null, "pronunciation": "xué shù", "ipa": "ɕɥe˧˥ ʂu˥˩", "syllable_count": 2, "sentences": [{"text": "他在大学里一直做学术研究。", "target_word": "学术", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位教授在学术上很有名。", "target_word": "学术", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校下周要开一个学术会议。", "target_word": "学术", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他一心想做学术，不想去公司工作。", "target_word": "学术", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她写的这篇文章很有学术价值。", "target_word": "学术", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大学里的学术气氛很浓。", "target_word": "学术", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书很专业，适合学术方面的读者。", "target_word": "学术", "complexity_tier": "T3", "furigana": "zhè běn shū hěn zhuān yè，shì hé xué shù fāng miàn de dú zhě。", "sentence_source": "generated"}, {"text": "爸爸是大学教授，每天都在写学术论文。", "target_word": "学术", "complexity_tier": "T3", "furigana": "bà ba shì dà xué jiào shòu，měi tiān dōu zài xiě xué shù lùn wén。", "sentence_source": "generated"}, {"text": "他的学术水平得到了大家的认可。", "target_word": "学术", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们请了一位专家来做学术报告。", "target_word": "学术", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "学术界", "label": "复合词"}, {"form": "学术研究", "label": "复合词"}, {"form": "學術", "label": "繁体"}], "register": "书面", "sense_fingerprint": "大学里研究出来的很深的学问", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd5c4b2d-97ab-40df-bb81-bfbbee817b15') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87953, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "学术", "is_correct": true, "explanation": "学术（xué shù）指大学里研究出来的很深的学问。"}, {"text": "学士", "is_correct": false, "explanation": "学士（xué shì）与学术的第二音节韵母不同（shì 与 shù），意思是学位等级。"}, {"text": "学史", "is_correct": false, "explanation": "学史（xué shǐ）第二音节声调不同，意思是学习历史。"}, {"text": "血书", "is_correct": false, "explanation": "血书（xuè shū）两个音节的声调都与学术不同，意思是用血写成的字。"}, {"text": "学时", "is_correct": false, "explanation": "学时（xué shí）第二音节声调不同，意思是学习的时间。"}], "explanations": {"学术": "学术（xué shù）指大学里研究出来的很深的学问。", "学士": "学士（xué shì）与学术的第二音节韵母不同（shì 与 shù），意思是学位等级。", "学史": "学史（xué shǐ）第二音节声调不同，意思是学习历史。", "血书": "血书（xuè shū）两个音节的声调都与学术不同，意思是用血写成的字。", "学时": "学时（xué shí）第二音节声调不同，意思是学习的时间。"}, "sentence_index": null, "correct_answer": "学术"}, "level_3": {"options": [{"text": "学术", "is_correct": true, "explanation": "正确：“学术”指大学里研究出来的学问，与“研究”搭配。"}, {"text": "寒假", "is_correct": false, "explanation": "语义：“寒假”与学术研究无关，句子不通。"}, {"text": "门票", "is_correct": false, "explanation": "语义：“门票”与研究无关，句子不通。"}, {"text": "玩意儿", "is_correct": false, "explanation": "语域：“玩意儿”是口语，与书面的学术语域不合。"}], "explanations": {"学术": "正确：“学术”指大学里研究出来的学问，与“研究”搭配。", "寒假": "语义：“寒假”与学术研究无关，句子不通。", "门票": "语义：“门票”与研究无关，句子不通。", "玩意儿": "语域：“玩意儿”是口语，与书面的学术语域不合。"}, "sentence_index": 0, "correct_answer": "学术"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他很有学术，大家都尊敬他。", "explanation": "这里应该用〈学问〉。学术指大学里研究出来的专门学问，不说“有学术”。"}, {"text": "他一心想完成学术，不想去公司工作。", "explanation": "这里应该用〈学业〉。“完成学业”是固定说法；学术指学问本身，“完成学术”不成立，此处应说“做学术”。"}, {"text": "他每天都去学术。", "explanation": "这里应该用〈学校〉。学术指学问，不指地点，他去的是学校。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '26503c15-eeab-4ed0-8337-4c518cf997e1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87953, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "学术", "is_correct": true, "explanation": "正确：“学术方面的读者”指对学术感兴趣的读者，与“适合”相配。"}, {"text": "夜间", "is_correct": false, "explanation": "语义：“夜间”与读者的专业方向无关，句子不通。"}, {"text": "厨房", "is_correct": false, "explanation": "语义：“厨房”与读者的专业方向无关，句子不通。"}, {"text": "鸡蛋", "is_correct": false, "explanation": "搭配：“鸡蛋”不能指读者的专业方向，搭配不当。"}], "explanations": {"学术": "正确：“学术方面的读者”指对学术感兴趣的读者，与“适合”相配。", "夜间": "语义：“夜间”与读者的专业方向无关，句子不通。", "厨房": "语义：“厨房”与读者的专业方向无关，句子不通。", "鸡蛋": "搭配：“鸡蛋”不能指读者的专业方向，搭配不当。"}, "sentence_index": 6, "correct_answer": "学术"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们请了一位学术来讲课。", "explanation": "这里应该用〈专家〉。学术指学问，不指人。"}, {"text": "他家里摆着一座学术。", "explanation": "这里应该用〈门〉。学术指学问，学问要用“门”；“座”用于山、楼等大型建筑，与学术不搭。"}, {"text": "这顿饭的学术很好吃。", "explanation": "这里应该用〈饭菜〉。学术指学问，不能用来形容饭菜的味道。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '26503c15-eeab-4ed0-8337-4c518cf997e1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87953, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这本学术很深奥。", "corrected_sentence": "这门学术很深奥。", "error_description": "错误在量词“本”。学问、学科用“门”，不用“本”；“本”用于书籍。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '26503c15-eeab-4ed0-8337-4c518cf997e1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87953, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他是搞学术人。", "corrected_sentence": "他是搞学术的人。", "error_description": "错误在“的”。“搞学术”修饰“人”，中间要加“的”，不能说“搞学术人”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '26503c15-eeab-4ed0-8337-4c518cf997e1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
