INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87954, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "有系统的、较专门的学问。", "primary_collocate": null, "pronunciation": "xué shù", "ipa": "ɕɥe˧˥ ʂu˥˩", "syllable_count": 2, "sentences": [{"text": "这篇论文在学术上很有分量。", "target_word": "学术", "complexity_tier": "T3", "furigana": "zhè piān lùn wén zài xué shù shàng hěn yǒu fèn liàng。", "sentence_source": "generated"}, {"text": "这本杂志专门发表学术文章。", "target_word": "学术", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们在学术问题上有不同看法。", "target_word": "学术", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学术研究要有证据，不能乱说。", "target_word": "学术", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位老人一生都在学术方面努力。", "target_word": "学术", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学术交流让两国的学者成了朋友。", "target_word": "学术", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "做学术要诚实，不能抄别人的。", "target_word": "学术", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家出版社出版了很多学术书。", "target_word": "学术", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他辞了职，回学校继续搞学术。", "target_word": "学术", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个学术团体有五百多个会员。", "target_word": "学术", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "学术性", "label": "复合词"}, {"form": "学术交流", "label": "复合词"}, {"form": "學術", "label": "繁体"}], "register": "书面", "sense_fingerprint": "有系统的较专门的学问", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd5c4b2d-97ab-40df-bb81-bfbbee817b15') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87954, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "学术", "is_correct": true, "explanation": "学术（xué shù）指有系统的、较专门的学问。"}, {"text": "学士", "is_correct": false, "explanation": "学士（xué shì）与学术的第二音节韵母不同（shì 与 shù），意思是学位等级。"}, {"text": "学史", "is_correct": false, "explanation": "学史（xué shǐ）第二音节声调不同，意思是学习历史。"}, {"text": "血书", "is_correct": false, "explanation": "血书（xuè shū）两个音节的声调都与学术不同，意思是用血写成的字。"}, {"text": "学时", "is_correct": false, "explanation": "学时（xué shí）第二音节声调不同，意思是学习的时间。"}], "explanations": {"学术": "学术（xué shù）指有系统的、较专门的学问。", "学士": "学士（xué shì）与学术的第二音节韵母不同（shì 与 shù），意思是学位等级。", "学史": "学史（xué shǐ）第二音节声调不同，意思是学习历史。", "血书": "血书（xuè shū）两个音节的声调都与学术不同，意思是用血写成的字。", "学时": "学时（xué shí）第二音节声调不同，意思是学习的时间。"}, "sentence_index": null, "correct_answer": "学术"}, "level_3": {"options": [{"text": "学术", "is_correct": true, "explanation": "正确：“在学术上”表示在学问方面，与“很有分量”相配。"}, {"text": "厨房", "is_correct": false, "explanation": "语义：“厨房”与论文的分量无关，句子不通。"}, {"text": "玩意儿", "is_correct": false, "explanation": "语域：“玩意儿”是口语，与书面的论文语域不合。"}, {"text": "窗户", "is_correct": false, "explanation": "语义：“窗户”不能衡量分量，句子不通。"}], "explanations": {"学术": "正确：“在学术上”表示在学问方面，与“很有分量”相配。", "厨房": "语义：“厨房”与论文的分量无关，句子不通。", "玩意儿": "语域：“玩意儿”是口语，与书面的论文语域不合。", "窗户": "语义：“窗户”不能衡量分量，句子不通。"}, "sentence_index": 0, "correct_answer": "学术"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "她很有学术，大家都尊敬她。", "explanation": "这里应该用〈学问〉。学术指有系统的专门学问，不说“有学术”。"}, {"text": "他一心想完成学术，不想去公司。", "explanation": "这里应该用〈学业〉。“完成学业”是固定说法；学术指学问本身，“完成学术”不成立，此处应说“做学术”。"}, {"text": "这顿饭的学术很好吃。", "explanation": "这里应该用〈饭菜〉。学术指学问，不能用来形容饭菜的味道。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '26503c15-eeab-4ed0-8337-4c518cf997e1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87954, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "学术", "is_correct": true, "explanation": "正确：“做学术”指从事学问研究，与“要诚实”相配。"}, {"text": "夜间", "is_correct": false, "explanation": "语义：“夜间”与“诚实”和“抄别人的”的语境无关，句子不通。"}, {"text": "扫帚", "is_correct": false, "explanation": "语义：“扫帚”不是可以做的事情，句子不通。"}, {"text": "八卦", "is_correct": false, "explanation": "语域：“八卦”是口语，与“做学术要诚实”的书面语域不合。"}], "explanations": {"学术": "正确：“做学术”指从事学问研究，与“要诚实”相配。", "夜间": "语义：“夜间”与“诚实”和“抄别人的”的语境无关，句子不通。", "扫帚": "语义：“扫帚”不是可以做的事情，句子不通。", "八卦": "语域：“八卦”是口语，与“做学术要诚实”的书面语域不合。"}, "sentence_index": 6, "correct_answer": "学术"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们请了一位学术来上课。", "explanation": "这里应该用〈老师〉。学术指学问，不指人。"}, {"text": "他每天都去学术。", "explanation": "这里应该用〈学校〉。学术指学问，不指地点，他去的是学校。"}, {"text": "他从书架上拿下来一张学术。", "explanation": "这里应该用〈门〉。学术指学问，学问用“门”；“张”用于纸张、桌子等平面物，不能用于学术。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '26503c15-eeab-4ed0-8337-4c518cf997e1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87954, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她在学术上的很有成绩。", "corrected_sentence": "她在学术上很有成绩。", "error_description": "错误：“的”后面不能直接接“很有成绩”。“在学术上”后应直接接“很有成绩”，应删去“的”，正确是“她在学术上很有成绩。”", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '26503c15-eeab-4ed0-8337-4c518cf997e1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87954, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这位学术团体很有名。", "corrected_sentence": "这个学术团体很有名。", "error_description": "错误在量词“位”。“位”用于人；学术团体是组织，应该用“个”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '26503c15-eeab-4ed0-8337-4c518cf997e1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
