INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87959, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "对外是对着外面，对着别的国家或别的人。", "primary_collocate": null, "pronunciation": "duì wài", "ipa": "twei˥˩ wai˥˩", "syllable_count": 2, "sentences": [{"text": "这家商店今天不对外营业。", "target_word": "对外", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司的电话不对外公开。", "target_word": "对外", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件事先不要对外说。", "target_word": "对外", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校的游泳池周末对外开放。", "target_word": "对外", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们对外宣布了好消息。", "target_word": "对外", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个房间不对外出租。", "target_word": "对外", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说，家里的事不要对外讲。", "target_word": "对外", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们的新产品明天对外发布。", "target_word": "对外", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个会议不对外，只有公司的人能来。", "target_word": "对外", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这份调查报告还没有对外公布。", "target_word": "对外", "complexity_tier": "T3", "furigana": "zhè fèn diàochá bàogào hái méiyǒu duìwài gōngbù", "sentence_source": "generated"}], "morphological_forms": [], "register": "正式", "sense_fingerprint": "对着外面或别人，不是对内", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '78bd22d5-58b2-46ac-bd58-f8a4351aa496') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87959, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "对外", "is_correct": true, "explanation": "正确。对外作状语修饰“营业”，表示面向外面的顾客。"}, {"text": "一起", "is_correct": false, "explanation": "语义：“一起”表示共同，与“营业”面向顾客开门的意思不符。"}, {"text": "大声", "is_correct": false, "explanation": "语义：“大声”说的是声音，不能修饰“营业”这种经营行为。"}, {"text": "慢慢", "is_correct": false, "explanation": "体貌：“慢慢”表示速度或渐进，与“今天不……营业”的时间范围不相合。"}], "explanations": {"对外": "正确。对外作状语修饰“营业”，表示面向外面的顾客。", "一起": "语义：“一起”表示共同，与“营业”面向顾客开门的意思不符。", "大声": "语义：“大声”说的是声音，不能修饰“营业”这种经营行为。", "慢慢": "体貌：“慢慢”表示速度或渐进，与“今天不……营业”的时间范围不相合。"}, "sentence_index": 0, "correct_answer": "对外"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个班级对外有二十个学生。", "explanation": "这里应该用〈一共〉。对外指面向外部的人或单位，只修饰面向外部的动作，不表示数量；说班级人数要用“一共”。"}, {"text": "对外下雨了，我们别出去。", "explanation": "这里应该用〈外面〉。对外指面向外部的人或单位，不能表示“外面”这个地点，也不能描述天气。"}, {"text": "他对外跟我当面道歉了。", "explanation": "这里应该删去〈对外〉。句中已有“当面”，对外表示面向外部，与面对面道歉的语境不符。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4bdfd8fd-3c6f-42b0-8fce-715d5e9632d9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87959, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "对外", "is_correct": true, "explanation": "正确。对外修饰“讲”，表示向外人讲，即传到外面去。"}, {"text": "已经", "is_correct": false, "explanation": "语法：“已经”表示动作已完成，不能放在“不要”之后的劝阻句中。"}, {"text": "偶尔", "is_correct": false, "explanation": "语义：“偶尔”表示次数少，与“家里的事”这种需要保密的内容不相合。"}, {"text": "独自", "is_correct": false, "explanation": "搭配：“独自”强调一个人，不能修饰“讲家里的事”这种说话动作。"}], "explanations": {"对外": "正确。对外修饰“讲”，表示向外人讲，即传到外面去。", "已经": "语法：“已经”表示动作已完成，不能放在“不要”之后的劝阻句中。", "偶尔": "语义：“偶尔”表示次数少，与“家里的事”这种需要保密的内容不相合。", "独自": "搭配：“独自”强调一个人，不能修饰“讲家里的事”这种说话动作。"}, "sentence_index": 6, "correct_answer": "对外"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这件事他对外跟我说过。", "explanation": "这里应该用〈私下〉。对外指面向外部人员，与“跟我说”的私下语境相矛盾，不能这样表达。"}, {"text": "他对外想了想，决定把文件收起来。", "explanation": "这里应该用〈独自〉。对外指面向外部，不表示人在心里思考；这里说的是一个人独自想。"}, {"text": "他对外把情况告诉了老板。", "explanation": "这里应该用〈直接〉。对外指面向外部人员，不表示不经中间环节。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4bdfd8fd-3c6f-42b0-8fce-715d5e9632d9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87959, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个系统暂时不对外面开放。", "corrected_sentence": "这个系统暂时不对外开放。", "error_description": "错误：在“对外”后面多加了“面”，写成“对外面开放”。正确：“对外”是固定的副词，不能加“面”，应说“对外开放”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4bdfd8fd-3c6f-42b0-8fce-715d5e9632d9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87959, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个计划下个月对外面宣布。", "corrected_sentence": "这个计划下个月对外宣布。", "error_description": "错误：在“对外”后面多加了“面”，写成“对外面宣布”。正确：“对外”是固定的副词，不能加“面”，应说“对外宣布”，表示向外界公布。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4bdfd8fd-3c6f-42b0-8fce-715d5e9632d9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
