INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87960, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "对外部，对别的国家、地区或单位。", "primary_collocate": null, "pronunciation": "duì wài", "ipa": "twei˥˩ wai˥˩", "syllable_count": 2, "sentences": [{"text": "中国对外开放了很多城市。", "target_word": "对外", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个国家的对外贸易很发达。", "target_word": "对外", "complexity_tier": "T3", "furigana": "zhè ge guójiā de duìwài màoyì hěn fādá", "sentence_source": "generated"}, {"text": "这家医院对外提供国际医疗服务。", "target_word": "对外", "complexity_tier": "T3", "furigana": "zhè jiā yīyuàn duìwài tígōng guójì yīliáo fúwù", "sentence_source": "generated"}, {"text": "公司有一个专门对外联系的部门。", "target_word": "对外", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在学校负责对外交流工作。", "target_word": "对外", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个港口下个月对外国船只开放。", "target_word": "对外", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "政府对外发布了新的规定。", "target_word": "对外", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这所大学的部分课程不对外国学生开放。", "target_word": "对外", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家工厂的产品都对外销售。", "target_word": "对外", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经理说，这份文件不能对外发。", "target_word": "对外", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "正式", "sense_fingerprint": "对外部的国家、地区或单位", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '78bd22d5-58b2-46ac-bd58-f8a4351aa496') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87960, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "对外", "is_correct": true, "explanation": "正确。对外修饰“开放”，表示向外国开放。"}, {"text": "偶尔", "is_correct": false, "explanation": "语义：“偶尔”表示次数少，与“开放了很多城市”的规模不相合。"}, {"text": "大声", "is_correct": false, "explanation": "语义：“大声”说的是声音，不能修饰“开放”这种政策行为。"}, {"text": "暗中", "is_correct": false, "explanation": "语义：“暗中”表示不公开地进行，与“开放”的公开含义相反。"}], "explanations": {"对外": "正确。对外修饰“开放”，表示向外国开放。", "偶尔": "语义：“偶尔”表示次数少，与“开放了很多城市”的规模不相合。", "大声": "语义：“大声”说的是声音，不能修饰“开放”这种政策行为。", "暗中": "语义：“暗中”表示不公开地进行，与“开放”的公开含义相反。"}, "sentence_index": 0, "correct_answer": "对外"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他对外等我，一直没有离开。", "explanation": "这里应该用〈在外面〉。对外不表示位置，只修饰“开放”“联系”这类面向外部的动作。"}, {"text": "他对外吃了三碗饭。", "explanation": "这里应该用〈在家〉。对外指面向外部的人或单位，不能说吃饭的地点或数量；这里说的是在家吃饭。"}, {"text": "他对外找了老板。", "explanation": "这里应该用〈直接〉。对外指面向外部，不表示不经中间环节地去做。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4bdfd8fd-3c6f-42b0-8fce-715d5e9632d9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87960, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "对外", "is_correct": true, "explanation": "正确。对外修饰“发布”，表示向外界公开发布。"}, {"text": "很", "is_correct": false, "explanation": "语法：“很”是程度副词，不能直接修饰“发布”这类动作动词。"}, {"text": "非常", "is_correct": false, "explanation": "语法：“非常”同样是程度副词，不能用来修饰“发布”。"}, {"text": "独自", "is_correct": false, "explanation": "搭配：“独自”强调一个人，不能用来修饰政府机构发布规定这种行为。"}], "explanations": {"对外": "正确。对外修饰“发布”，表示向外界公开发布。", "很": "语法：“很”是程度副词，不能直接修饰“发布”这类动作动词。", "非常": "语法：“非常”同样是程度副词，不能用来修饰“发布”。", "独自": "搭配：“独自”强调一个人，不能用来修饰政府机构发布规定这种行为。"}, "sentence_index": 6, "correct_answer": "对外"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "经理对外跟我说过这件事。", "explanation": "这里应该用〈私下〉。对外指面向外部人员，与“跟我说”的私下语境相矛盾。"}, {"text": "经理对外想了想，决定把文件留下。", "explanation": "这里应该用〈独自〉。对外指面向外部人员，不表示个人在心里思考；这里说的是经理自己想。"}, {"text": "他对外当面把消息告诉了我。", "explanation": "这里应该删去〈对外〉。句中已有“当面”，对外表示面向外部，与面对面告知的语境不符。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4bdfd8fd-3c6f-42b0-8fce-715d5e9632d9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87960, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个机构对外面提供帮助。", "corrected_sentence": "这个机构对外提供帮助。", "error_description": "错误：在“对外”后面多加了“面”，写成“对外面提供帮助”。正确：“对外”是固定的副词，不能加“面”，应说“对外提供帮助”，表示面向外部。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4bdfd8fd-3c6f-42b0-8fce-715d5e9632d9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87960, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这家公司的新产品将对外面发布。", "corrected_sentence": "这家公司的新产品将对外发布。", "error_description": "错误：在“对外”后面多加了“面”，写成“对外面发布”。正确：“对外”是固定的副词，不能加“面”，应说“对外发布”，表示向外界公布。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4bdfd8fd-3c6f-42b0-8fce-715d5e9632d9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
