INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87961, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "反间是想办法让坏人那边自己人吵起来。", "primary_collocate": null, "pronunciation": "fǎn jiàn", "ipa": "fan˨˩ tɕjɛn˥˩", "syllable_count": 2, "sentences": [{"text": "警察想办法反间坏人。", "target_word": "反间", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "警察决定反间这个坏人团伙。", "target_word": "反间", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们想反间那伙坏人，让坏人互相怀疑。", "target_word": "反间", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "警察用假消息反间了两个坏人。", "target_word": "反间", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们要反间他们，让他们自己吵起来。", "target_word": "反间", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "好人想办法反间坏人，让他们吵架。", "target_word": "反间", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老警察说：“先反间，再抓人。”", "target_word": "反间", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "为了抓住大坏人，警察反间了他的几个手下。", "target_word": "反间", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电影里的警察常常反间坏人。", "target_word": "反间", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他用一张照片反间了那伙坏人。", "target_word": "反间", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "反间了", "label": "体标"}, {"form": "反间过", "label": "体标"}, {"form": "反間", "label": "繁体"}], "register": "中性", "sense_fingerprint": "想办法让坏人一方内部不和、自己人吵起来", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ac8ff967-745b-40e1-9201-f6f0972c5a6d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87961, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "反间", "is_correct": true, "explanation": "正确答案：反间（fǎn jiàn），即想办法让坏人一方内部不和。"}, {"text": "翻建", "is_correct": false, "explanation": "fān（第一声）与 fǎn（第三声）声调不同，意思是翻修、重建。"}, {"text": "反剪", "is_correct": false, "explanation": "jiǎn（第三声）与 jiàn（第四声）声调不同，意思是反剪双手。"}, {"text": "眼见", "is_correct": false, "explanation": "yǎn（第三声）与 fǎn（第三声）声母不同（y 与 f），意思是亲眼看见。"}], "explanations": {"反间": "正确答案：反间（fǎn jiàn），即想办法让坏人一方内部不和。", "翻建": "fān（第一声）与 fǎn（第三声）声调不同，意思是翻修、重建。", "反剪": "jiǎn（第三声）与 jiàn（第四声）声调不同，意思是反剪双手。", "眼见": "yǎn（第三声）与 fǎn（第三声）声母不同（y 与 f），意思是亲眼看见。"}, "sentence_index": null, "correct_answer": "反间"}, "level_3": {"options": [{"text": "反间", "is_correct": true, "explanation": "正确：反间即想办法离间坏人一方，与“警察”和“坏人”的语境相合。"}, {"text": "保护", "is_correct": false, "explanation": "语义：警察去保护坏人，与“想办法”的办案意图相反。"}, {"text": "表彰", "is_correct": false, "explanation": "语义：表彰坏人与警察打击坏人的目的不符。"}, {"text": "招待", "is_correct": false, "explanation": "搭配：“招待”针对宾客，不用于“想办法……坏人”这样的办案语境。"}], "explanations": {"反间": "正确：反间即想办法离间坏人一方，与“警察”和“坏人”的语境相合。", "保护": "语义：警察去保护坏人，与“想办法”的办案意图相反。", "表彰": "语义：表彰坏人与警察打击坏人的目的不符。", "招待": "搭配：“招待”针对宾客，不用于“想办法……坏人”这样的办案语境。"}, "sentence_index": 0, "correct_answer": "反间"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "警察冲进屋里，一把反间了两个坏人。", "explanation": "这里应该用〈抓住〉。反间是离间敌方内部，不是把人当场抓住。"}, {"text": "警察反间了那辆汽车，让它停下来。", "explanation": "这里应该用〈拦住〉。反间的对象是人或人群，“汽车”是物，不能被离间；让车停下应用“拦住”。"}, {"text": "警察反间小偷，让他趴在地上。", "explanation": "这里应该用〈命令〉。反间是离间敌方内部，不表示对人下达指令。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f7b918d-c73d-4c78-b735-3ef7235ac0cb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87961, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "反间", "is_correct": true, "explanation": "正确：先反间，即先离间坏人内部，再抓人，语境相合。"}, {"text": "表扬", "is_correct": false, "explanation": "语义：表扬坏人与“再抓人”的办案逻辑相悖。"}, {"text": "慰问", "is_correct": false, "explanation": "语义：慰问坏人与警察办案的目的相反。"}, {"text": "歌颂", "is_correct": false, "explanation": "搭配：“歌颂”多用于英雄、祖国，不用于坏人。"}], "explanations": {"反间": "正确：先反间，即先离间坏人内部，再抓人，语境相合。", "表扬": "语义：表扬坏人与“再抓人”的办案逻辑相悖。", "慰问": "语义：慰问坏人与警察办案的目的相反。", "歌颂": "搭配：“歌颂”多用于英雄、祖国，不用于坏人。"}, "sentence_index": 6, "correct_answer": "反间"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他一眼反间了那伙坏人。", "explanation": "这里应该用〈认出〉。反间是离间敌方内部，不表示用眼睛辨认。"}, {"text": "他向警察反间了那伙坏人的老大。", "explanation": "这里应该用〈举报〉。反间是离间敌方内部，不表示向警方告发；告发同伙要用“举报”。"}, {"text": "他用一张照片反间了那伙坏人的罪行。", "explanation": "这里应该用〈证明〉。反间是离间敌方内部，不能用于证明罪行。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f7b918d-c73d-4c78-b735-3ef7235ac0cb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87961, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "警察决定先反间过那伙坏人。", "corrected_sentence": "警察决定先反间那伙坏人。", "error_description": "“过”表示曾经有过的经历，不能用于“决定先……”这种尚未发生的计划。应去掉“过”，写作：警察决定先反间那伙坏人。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f7b918d-c73d-4c78-b735-3ef7235ac0cb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87961, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "警察正在反间了那伙坏人。", "corrected_sentence": "警察正在反间那伙坏人。", "error_description": "“正在”表示动作正在进行，不能与动态助词“了”同用。应去掉“反间”后面的“了”，写作：警察正在反间那伙坏人。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f7b918d-c73d-4c78-b735-3ef7235ac0cb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
