INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87969, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "妇女是长大了的女人。", "primary_collocate": null, "pronunciation": "fù nǚ", "ipa": "fu˥˩ ny˨˩˦", "syllable_count": 2, "sentences": [{"text": "那位妇女抱着一个小孩。", "target_word": "妇女", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公园里有很多老年妇女在跳舞。", "target_word": "妇女", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妇女和男人一样可以工作。", "target_word": "妇女", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位妇女每天都很早起床。", "target_word": "妇女", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我看见一位妇女在门口等人。", "target_word": "妇女", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "有些妇女喜欢在家里做饭。", "target_word": "妇女", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书是写给妇女看的。", "target_word": "妇女", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她是一位很能干的妇女。", "target_word": "妇女", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "车上的妇女把座位让给了老人。", "target_word": "妇女", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "村里的妇女们一起去山上种树。", "target_word": "妇女", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "婦女", "label": "繁体"}], "register": "中性偏书面", "sense_fingerprint": "长大成人的女人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7b9c7047-c41d-4dd6-a29e-9eca3dfeee0a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87969, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "妇女", "is_correct": true, "explanation": "正确：“妇女”指长大成人的女人，能够抱着小孩，符合句意。"}, {"text": "宝宝", "is_correct": false, "explanation": "语义：宝宝是被抱的婴幼儿，不能抱着一个小孩。"}, {"text": "婴儿", "is_correct": false, "explanation": "语义：婴儿还不会抱人，与“抱着一个小孩”的动作相矛盾。"}, {"text": "幼儿", "is_correct": false, "explanation": "搭配：幼儿自己还需要别人照顾，不能说他抱着一个小孩。"}], "explanations": {"妇女": "正确：“妇女”指长大成人的女人，能够抱着小孩，符合句意。", "宝宝": "语义：宝宝是被抱的婴幼儿，不能抱着一个小孩。", "婴儿": "语义：婴儿还不会抱人，与“抱着一个小孩”的动作相矛盾。", "幼儿": "搭配：幼儿自己还需要别人照顾，不能说他抱着一个小孩。"}, "sentence_index": 0, "correct_answer": "妇女"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个妇女还在上幼儿园。", "explanation": "这里应该用〈小女孩〉。“妇女”指长大了的女人，不能用来指还在上幼儿园的孩子。"}, {"text": "我爸爸是个妇女。", "explanation": "这里应该用〈男人〉。“妇女”指女性，不能用来指男性。"}, {"text": "这个妇女刚满十六岁，正在读高中。", "explanation": "这里应该用〈少女〉。“妇女”指长大了的成年女子，十六岁的女孩应说少女。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '91e180dd-508b-4434-8fa4-cf412f9f8831') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87969, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "妇女", "is_correct": true, "explanation": "正确：“妇女”指长大了的女人，适合作为“写给……看的”书的读者。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头不会阅读，书不能写给石头看。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：桌子不能看书，与“写给……看的”不相符。"}, {"text": "窗户", "is_correct": false, "explanation": "搭配：“写给……看的”要求读者是有阅读能力的人，窗户不能与之搭配。"}], "explanations": {"妇女": "正确：“妇女”指长大了的女人，适合作为“写给……看的”书的读者。", "石头": "语义：石头不会阅读，书不能写给石头看。", "桌子": "语义：桌子不能看书，与“写给……看的”不相符。", "窗户": "搭配：“写给……看的”要求读者是有阅读能力的人，窗户不能与之搭配。"}, "sentence_index": 6, "correct_answer": "妇女"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我家的小狗是妇女。", "explanation": "“妇女”专指长大了的女性，不能用来指狗这样的动物。"}, {"text": "我弟弟的名字叫妇女。", "explanation": "“妇女”是泛称，不是人名，不能用来给人取名。"}, {"text": "我的妇女今天很忙。", "explanation": "这里应该用〈妻子〉。“妇女”是泛指女性的名词，不能用来指自己的妻子。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '91e180dd-508b-4434-8fa4-cf412f9f8831') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87969, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "那位妇女们在超市门口卖水果。", "corrected_sentence": "那位妇女在超市门口卖水果。", "error_description": "“们”误用：“们”不能附在带指示词和量词的名词后，“那位妇女”后不能加“们”。正确说法：那位妇女在超市门口卖水果。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '91e180dd-508b-4434-8fa4-cf412f9f8831') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87969, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "几妇女在村口聊天。", "corrected_sentence": "几位妇女在村口聊天。", "error_description": "量词缺失：数词“几”后面要加量词，“妇女”前应为“几位”。正确说法：几位妇女在村口聊天。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '91e180dd-508b-4434-8fa4-cf412f9f8831') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
