INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87973, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "怪是不一般，让人觉得有点怕或者奇怪。", "primary_collocate": null, "pronunciation": "guài", "ipa": "kwaɪ˥˩", "syllable_count": 1, "sentences": [{"text": "半夜里，窗外有一个怪影子。", "target_word": "怪", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他今天很怪，一句话也不说。", "target_word": "怪", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个房子晚上有点怪，我不敢进去。", "target_word": "怪", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我做了一个很怪的梦，吓醒了。", "target_word": "怪", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "那条黑路上的灯光很怪。", "target_word": "怪", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "山洞里很黑，里面有点怪，大家都停住了。", "target_word": "怪", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他的笑声听起来很怪，让人害怕。", "target_word": "怪", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她看着我，眼神怪怪的。", "target_word": "怪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "夜里的森林安静得有点怪。", "target_word": "怪", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "那个老人说话很怪，孩子们都躲开他。", "target_word": "怪", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "怪怪的", "label": "重叠"}], "register": "口语", "sense_fingerprint": "不一般，让人有点害怕或不安", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '14147f2a-e52b-4b73-85e3-382a3d8c63ac') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87973, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "怪", "is_correct": true, "explanation": "正确答案：怪（guài，第四声），意思是不一般、让人有点害怕。"}, {"text": "快", "is_correct": false, "explanation": "kuài 与 guài 声母不同（k 与 g，送气与否），意思是快。"}, {"text": "拐", "is_correct": false, "explanation": "guǎi（第三声）与 guài（第四声）声调不同，意思是拐弯。"}, {"text": "挂", "is_correct": false, "explanation": "guà 与 guài 韵母不同（a 与 ai），意思是挂起来。"}, {"text": "贵", "is_correct": false, "explanation": "guì 与 guài 韵母不同（i 与 ai），意思是价格高。"}], "explanations": {"怪": "正确答案：怪（guài，第四声），意思是不一般、让人有点害怕。", "快": "kuài 与 guài 声母不同（k 与 g，送气与否），意思是快。", "拐": "guǎi（第三声）与 guài（第四声）声调不同，意思是拐弯。", "挂": "guà 与 guài 韵母不同（a 与 ai），意思是挂起来。", "贵": "guì 与 guài 韵母不同（i 与 ai），意思是价格高。"}, "sentence_index": null, "correct_answer": "怪"}, "level_3": {"options": [{"text": "怪", "is_correct": true, "explanation": "正确答案：“怪”指不一般、让人害怕，可以修饰“影子”。"}, {"text": "亮", "is_correct": false, "explanation": "语义：半夜里窗外光线暗，“亮”与“半夜”的情境相矛盾。"}, {"text": "红", "is_correct": false, "explanation": "体貌：影子是暗色的轮廓，不用“红”来描写。"}, {"text": "饿", "is_correct": false, "explanation": "语义：“饿”描述人的感受，不能用来修饰影子。"}], "explanations": {"怪": "正确答案：“怪”指不一般、让人害怕，可以修饰“影子”。", "亮": "语义：半夜里窗外光线暗，“亮”与“半夜”的情境相矛盾。", "红": "体貌：影子是暗色的轮廓，不用“红”来描写。", "饿": "语义：“饿”描述人的感受，不能用来修饰影子。"}, "sentence_index": 0, "correct_answer": "怪"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这学期他的进步很怪，老师都为他高兴。", "explanation": "这里应该用〈惊人〉。怪指不一般、让人觉得奇怪，不用来形容进步的程度；赞叹进步要用惊人。"}, {"text": "这座大桥很怪，大家都赞叹它的气势。", "explanation": "这里应该用〈雄伟〉。怪只表示不寻常、让人觉得奇怪，不表示壮观、令人敬佩；赞叹建筑的气势要用雄伟。"}, {"text": "这个女孩长得很怪，大家都夸她有气质。", "explanation": "这里应该用〈漂亮〉。怪指不寻常、让人觉得奇怪，形容外貌好看要用漂亮。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6fcd30b9-9649-49b6-a32a-d303d4af5e0e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87973, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "怪", "is_correct": true, "explanation": "正确答案：怪（guài，第四声），意思是不一般、让人有点害怕。"}, {"text": "块", "is_correct": false, "explanation": "kuài 与 guài 声母不同（k 与 g，送气与否），意思是块状物。"}, {"text": "筷", "is_correct": false, "explanation": "kuài 与 guài 声母不同（k 与 g），意思是筷子。"}, {"text": "乖", "is_correct": false, "explanation": "guāi（第一声）与 guài（第四声）声调不同，意思是听话。"}, {"text": "柜", "is_correct": false, "explanation": "guì 与 guài 韵母不同（i 与 ai），意思是柜子。"}], "explanations": {"怪": "正确答案：怪（guài，第四声），意思是不一般、让人有点害怕。", "块": "kuài 与 guài 声母不同（k 与 g，送气与否），意思是块状物。", "筷": "kuài 与 guài 声母不同（k 与 g），意思是筷子。", "乖": "guāi（第一声）与 guài（第四声）声调不同，意思是听话。", "柜": "guì 与 guài 韵母不同（i 与 ai），意思是柜子。"}, "sentence_index": null, "correct_answer": "怪"}, "level_3": {"options": [{"text": "怪", "is_correct": true, "explanation": "正确答案：“怪”指不一般、让人害怕，与“让人害怕”的后半句一致。"}, {"text": "好听", "is_correct": false, "explanation": "语义：“好听”是赞美声音，与“让人害怕”的后半句相矛盾。"}, {"text": "开心", "is_correct": false, "explanation": "语义：“开心”表示高兴，与“让人害怕”的后半句相矛盾。"}, {"text": "温和", "is_correct": false, "explanation": "语义：“温和”指声音柔和，与“让人害怕”的感受相矛盾。"}], "explanations": {"怪": "正确答案：“怪”指不一般、让人害怕，与“让人害怕”的后半句一致。", "好听": "语义：“好听”是赞美声音，与“让人害怕”的后半句相矛盾。", "开心": "语义：“开心”表示高兴，与“让人害怕”的后半句相矛盾。", "温和": "语义：“温和”指声音柔和，与“让人害怕”的感受相矛盾。"}, "sentence_index": 6, "correct_answer": "怪"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这种药的疗效很怪，明显优于对照组。", "explanation": "这里应该用〈显著〉。怪只表示不寻常、让人觉得奇怪，不表示效果突出；描述疗效的明显差别要用显著。"}, {"text": "这台电脑的内存很怪，一共有三十二G。", "explanation": "这里应该用〈大〉。怪只指不寻常，不用来描述容量多少；说内存容量大要用大。"}, {"text": "这座楼的层数很怪，一共有三十层。", "explanation": "这里应该用〈多〉。怪只指不寻常，不用来描述数量多少；说楼层数量多要用多。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6fcd30b9-9649-49b6-a32a-d303d4af5e0e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content 