INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87974, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "奇异；不寻常。", "primary_collocate": null, "pronunciation": "guài", "ipa": "kwaɪ˥˩", "syllable_count": 1, "sentences": [{"text": "这件事真怪，我想不明白。", "target_word": "怪", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "今年的天气很怪，十月还那么热。", "target_word": "怪", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他买了一件样子很怪的衣服。", "target_word": "怪", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这种水果的味道有点怪。", "target_word": "怪", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "电脑今天怪得很，总是自己关机。", "target_word": "怪", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他的名字很怪，我从没听过。", "target_word": "怪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这只猫的叫声很怪，不像别的猫。", "target_word": "怪", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "说也怪，我刚想起他，他就来电话了。", "target_word": "怪", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个字写得很怪，我认不出来。", "target_word": "怪", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他穿得很怪，走在街上大家都回头看。", "target_word": "怪", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "怪怪的", "label": "重叠"}], "register": "口语", "sense_fingerprint": "奇异、不寻常、和平常不一样", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '14147f2a-e52b-4b73-85e3-382a3d8c63ac') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87974, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "怪", "is_correct": true, "explanation": "正确答案：怪（guài，第四声），意思是奇异、不寻常。"}, {"text": "块", "is_correct": false, "explanation": "kuài 与 guài 声母不同（k 与 g，送气与否），意思是块状物。"}, {"text": "乖", "is_correct": false, "explanation": "guāi（第一声）与 guài（第四声）声调不同，意思是听话。"}, {"text": "挂", "is_correct": false, "explanation": "guà 与 guài 韵母不同（a 与 ai），意思是挂起来。"}, {"text": "柜", "is_correct": false, "explanation": "guì 与 guài 韵母不同（i 与 ai），意思是柜子。"}], "explanations": {"怪": "正确答案：怪（guài，第四声），意思是奇异、不寻常。", "块": "kuài 与 guài 声母不同（k 与 g，送气与否），意思是块状物。", "乖": "guāi（第一声）与 guài（第四声）声调不同，意思是听话。", "挂": "guà 与 guài 韵母不同（a 与 ai），意思是挂起来。", "柜": "guì 与 guài 韵母不同（i 与 ai），意思是柜子。"}, "sentence_index": null, "correct_answer": "怪"}, "level_3": {"options": [{"text": "怪", "is_correct": true, "explanation": "正确答案：“怪”指奇异、不寻常，与“我想不明白”相呼应。"}, {"text": "容易", "is_correct": false, "explanation": "语义：“容易”表示不难，与“我想不明白”相矛盾。"}, {"text": "热", "is_correct": false, "explanation": "搭配：“热”说温度，不能用来形容事情。"}, {"text": "简单", "is_correct": false, "explanation": "语义：“简单”表示不难，与“我想不明白”相矛盾。"}], "explanations": {"怪": "正确答案：“怪”指奇异、不寻常，与“我想不明白”相呼应。", "容易": "语义：“容易”表示不难，与“我想不明白”相矛盾。", "热": "搭配：“热”说温度，不能用来形容事情。", "简单": "语义：“简单”表示不难，与“我想不明白”相矛盾。"}, "sentence_index": 0, "correct_answer": "怪"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这锅鱼汤的味道很怪，大家都夸它好喝。", "explanation": "这里应该用〈鲜美〉。怪只表示不寻常，不表示味道好；称赞食物的美味要用鲜美。"}, {"text": "这个班的人数很怪，一共有四十个学生。", "explanation": "这里应该用〈多〉。怪只表示不寻常，不用来描述人数的多少；说人数多要用多。"}, {"text": "这块石头的重量很怪，正好是一公斤。", "explanation": "这里应该用〈沉〉。怪只表示不寻常，不用来描述轻重；说东西分量大要用沉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6fcd30b9-9649-49b6-a32a-d303d4af5e0e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87974, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "怪", "is_correct": true, "explanation": "正确答案：怪（guài，第四声），意思是奇异、不寻常。"}, {"text": "快", "is_correct": false, "explanation": "kuài 与 guài 声母不同（k 与 g，送气与否），意思是快。"}, {"text": "拐", "is_correct": false, "explanation": "guǎi（第三声）与 guài（第四声）声调不同，意思是拐弯。"}, {"text": "贵", "is_correct": false, "explanation": "guì 与 guài 韵母不同（i 与 ai），意思是价格高。"}, {"text": "筷", "is_correct": false, "explanation": "kuài 与 guài 声母不同（k 与 g），意思是筷子。"}], "explanations": {"怪": "正确答案：怪（guài，第四声），意思是奇异、不寻常。", "快": "kuài 与 guài 声母不同（k 与 g，送气与否），意思是快。", "拐": "guǎi（第三声）与 guài（第四声）声调不同，意思是拐弯。", "贵": "guì 与 guài 韵母不同（i 与 ai），意思是价格高。", "筷": "kuài 与 guài 声母不同（k 与 g），意思是筷子。"}, "sentence_index": null, "correct_answer": "怪"}, "level_3": {"options": [{"text": "怪", "is_correct": true, "explanation": "正确答案：“怪”指奇异、不寻常，与“不像别的猫”相呼应。"}, {"text": "普通", "is_correct": false, "explanation": "语义：“普通”与“不像别的猫”的对比相矛盾。"}, {"text": "整齐", "is_correct": false, "explanation": "搭配：“整齐”说排列有序，不能用来形容叫声。"}, {"text": "方正", "is_correct": false, "explanation": "搭配：“方正”说形状，叫声没有方形可言。"}], "explanations": {"怪": "正确答案：“怪”指奇异、不寻常，与“不像别的猫”相呼应。", "普通": "语义：“普通”与“不像别的猫”的对比相矛盾。", "整齐": "搭配：“整齐”说排列有序，不能用来形容叫声。", "方正": "搭配：“方正”说形状，叫声没有方形可言。"}, "sentence_index": 6, "correct_answer": "怪"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这项手术的成功率很怪，远远超过普通水平。", "explanation": "这里应该用〈高〉。怪只表示不寻常，不用来描述比率高低；说成功率高要用高。"}, {"text": "这台机器的运转速度很怪，比以前提高了一倍。", "explanation": "这里应该用〈快〉。怪只表示不寻常，不用来描述速度快慢；说速度快要用快。"}, {"text": "这道数学题的难度很怪，班上只有一个人会做。", "explanation": "这里应该用〈大〉。怪只表示不寻常，不表示难度高低；说难度高要用“难度很大”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6fcd30b9-9649-49b6-a32a-d303d4af5e0e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87974, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我今天买了一种很怪水果。", "corrected_sentence": "我今天买了一种很怪的水果。", "error_description": "错误：“很怪水果”漏掉了“的”。正确：“很怪的水果”。“很怪”修饰名词时要加“的”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6fcd30b9-9649-49b6-a32a-d303d4af5e0e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87974, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个办法怪得很得，大家都没想到。", "corrected_sentence": "这个办法怪得很，大家都没想到。", "error_description": "错误：“怪得很”后多出了“得”，补语结构重复。正确：“怪得很”，“得”只用一次。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6fcd30b9-9649-49b6-a32a-d303d4af5e0e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
