INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87989, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "旅行是离开家，到很远的地方去玩。", "primary_collocate": null, "pronunciation": "lǚ xíng", "ipa": "/ly˨˩˦ ɕiŋ˧˥/", "syllable_count": 2, "sentences": [{"text": "暑假我想离开家去远方旅行。", "target_word": "旅行", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们全家去海边旅行了。", "target_word": "旅行", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他喜欢到很远的地方旅行。", "target_word": "旅行", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她带着相机去旅行。", "target_word": "旅行", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "旅行让我看到了很多新东西。", "target_word": "旅行", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你去过国外旅行吗？", "target_word": "旅行", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们明天出发去旅行。", "target_word": "旅行", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们都想去山里旅行。", "target_word": "旅行", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "旅行的路上，我们唱了很多歌。", "target_word": "旅行", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们开着车去很远的地方旅行。", "target_word": "旅行", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "旅行了", "label": "体标（完成）"}, {"form": "旅行过", "label": "体标（经历）"}, {"form": "旅行社", "label": "复合词"}, {"form": "旅行箱", "label": "复合词"}], "register": "通用", "sense_fingerprint": "离开家到远方去玩", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a298fe30-4cb1-44d1-ba83-8e5984f2584b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87989, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "旅行", "is_correct": true, "explanation": "正确。“离开家去远方旅行”指离开家到很远的地方去玩，与句中的意思相符。"}, {"text": "生病", "is_correct": false, "explanation": "语义：生病不是去远方要做的事，句子说的是离开家去远方玩。"}, {"text": "出生", "is_correct": false, "explanation": "语义：出生只发生一次，不能用来表示离开家去远方的计划。"}, {"text": "视察", "is_correct": false, "explanation": "语域：“视察”是上级对下级的正式检查，与“暑假我想……”的口语计划不协调。"}], "explanations": {"旅行": "正确。“离开家去远方旅行”指离开家到很远的地方去玩，与句中的意思相符。", "生病": "语义：生病不是去远方要做的事，句子说的是离开家去远方玩。", "出生": "语义：出生只发生一次，不能用来表示离开家去远方的计划。", "视察": "语域：“视察”是上级对下级的正式检查，与“暑假我想……”的口语计划不协调。"}, "sentence_index": 0, "correct_answer": "旅行"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我晚饭后去公园旅行。", "explanation": "这里应该用〈散步〉。旅行指离开家到很远的地方去玩，家附近公园里的散步不能说“旅行”。"}, {"text": "我每天在办公室旅行。", "explanation": "这里应该用〈上班〉。旅行要离开家到远方去，每天在办公室工作不能说“旅行”。"}, {"text": "她晚上在家旅行。", "explanation": "这里应该用〈睡觉〉。旅行要离开家到远方去，晚上在家休息不能说“旅行”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '73ed49ee-02fe-4815-a4f8-121fa8aa9f1c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87989, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "旅行", "is_correct": true, "explanation": "正确。“明天出发去旅行”表示明天出门去玩，与“出发”相符。"}, {"text": "发烧", "is_correct": false, "explanation": "语义：发烧是身体状况，不能说明明天出发要去做的事。"}, {"text": "睡觉", "is_correct": false, "explanation": "语义：“出发去睡觉”不能说明出发的目的，与句中的出行语境冲突。"}, {"text": "离开", "is_correct": false, "explanation": "配价：“离开”要带离开的处所，“出发去离开”宾语缺失，表达不完整。"}], "explanations": {"旅行": "正确。“明天出发去旅行”表示明天出门去玩，与“出发”相符。", "发烧": "语义：发烧是身体状况，不能说明明天出发要去做的事。", "睡觉": "语义：“出发去睡觉”不能说明出发的目的，与句中的出行语境冲突。", "离开": "配价：“离开”要带离开的处所，“出发去离开”宾语缺失，表达不完整。"}, "sentence_index": 6, "correct_answer": "旅行"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她住院的时候，每天在病房里旅行。", "explanation": "这里应该用〈休息〉。旅行是离开家到很远的地方去玩，病房里的日常休息不能说“旅行”。"}, {"text": "他在厨房里旅行，做了一桌好菜。", "explanation": "这里应该用〈做饭〉。旅行是离开家到很远的地方去玩，在厨房做菜应说“做饭”。"}, {"text": "我每天在图书馆里旅行，找资料。", "explanation": "这里应该用〈看书〉。旅行是离开家到很远的地方去玩，在图书馆看书、查资料不能说“旅行”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '73ed49ee-02fe-4815-a4f8-121fa8aa9f1c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87989, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们明天去海边旅行了。", "corrected_sentence": "我们明天去海边旅行。", "error_description": "错误：“明天”指将来，“旅行”后不能加“了”。应去掉“了”，说“明天去海边旅行”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '73ed49ee-02fe-4815-a4f8-121fa8aa9f1c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87989, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们周末山里旅行。", "corrected_sentence": "他们周末去山里旅行。", "error_description": "错误：漏了“去”。“旅行”是不及物动词，去“山里”要先用“去”引出地点，应说“去山里旅行”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '73ed49ee-02fe-4815-a4f8-121fa8aa9f1c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
