INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87994, 1, 'prompt1_core', '{"pos": "连词", "semantic_class": "function", "definition": "连词，与“又”“也”配合，表示两种情况同时存在。", "primary_collocate": null, "pronunciation": "jì", "ipa": "tɕi˥˩", "syllable_count": 1, "sentences": [{"text": "这家饭馆的菜既好吃又便宜。", "target_word": "既", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她既聪明又努力。", "target_word": "既", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这个房子既大又亮。", "target_word": "既", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他既会唱歌，又会跳舞。", "target_word": "既", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这本书既有意思，又有用。", "target_word": "既", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "坐地铁既快又方便。", "target_word": "既", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他既是我的老师，也是我的朋友。", "target_word": "既", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这件衣服既好看又不贵。", "target_word": "既", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这里的夏天既热又湿。", "target_word": "既", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "新手机既轻又薄，我很喜欢。", "target_word": "既", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "既：与「又」「也」配合，并列两种性质或情况同时存在（既……又……）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3a694cc8-f902-4891-9c84-c2b01ecc1500') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87994, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "既", "is_correct": true, "explanation": "既读 jì，表示两种情况同时存在，与听到的音一致。"}, {"text": "机", "is_correct": false, "explanation": "jī（第一声）与 jì（第四声）声调不同，意思是机器。"}, {"text": "己", "is_correct": false, "explanation": "jǐ（第三声）与 jì（第四声）声调不同，意思是自己。"}, {"text": "气", "is_correct": false, "explanation": "qì 与 jì 声母不同（q 与 j），声调相同，意思是空气。"}, {"text": "戏", "is_correct": false, "explanation": "xì 与 jì 声母不同（x 与 j），声调相同，意思是戏剧。"}], "explanations": {"既": "既读 jì，表示两种情况同时存在，与听到的音一致。", "机": "jī（第一声）与 jì（第四声）声调不同，意思是机器。", "己": "jǐ（第三声）与 jì（第四声）声调不同，意思是自己。", "气": "qì 与 jì 声母不同（q 与 j），声调相同，意思是空气。", "戏": "xì 与 jì 声母不同（x 与 j），声调相同，意思是戏剧。"}, "sentence_index": null, "correct_answer": "既"}, "level_3": {"options": [{"text": "既", "is_correct": true, "explanation": "“既”与“又”配合，表示两种性质同时存在，“好吃又便宜”符合句意。"}, {"text": "所以", "is_correct": false, "explanation": "语义：“所以”表示因果，后句应是结果，“好吃又便宜”不能作为原因。"}, {"text": "或者", "is_correct": false, "explanation": "语义：“或者”表示二者选一，与“好吃又便宜”同时具备的意思相矛盾。"}, {"text": "而", "is_correct": false, "explanation": "句法：“而”连接前后并列成分，此处前面是主语“这家饭馆的菜”，“而”不能直接接“好吃又便宜”。"}], "explanations": {"既": "“既”与“又”配合，表示两种性质同时存在，“好吃又便宜”符合句意。", "所以": "语义：“所以”表示因果，后句应是结果，“好吃又便宜”不能作为原因。", "或者": "语义：“或者”表示二者选一，与“好吃又便宜”同时具备的意思相矛盾。", "而": "句法：“而”连接前后并列成分，此处前面是主语“这家饭馆的菜”，“而”不能直接接“好吃又便宜”。"}, "sentence_index": 0, "correct_answer": "既"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这家饭馆的菜既好吃，但便宜。", "explanation": "这里应该用〈又〉。“既”要与“又”或“也”配合表示两种情况并存，与转折词“但”搭配会变成转折，此处表示并列应用“又”。"}, {"text": "他既会唱歌。", "explanation": "这里应该用〈只〉。“既”要与“又”或“也”配合，连接两种情况；此处只说一种情况，表示“仅仅”应用“只”。"}, {"text": "这个城市既很安静。", "explanation": "这里应该用〈也〉。“既”需要与“又”配合连接两种情况，不能单独修饰形容词；此处表示“同样”应用“也”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9884cfa0-9a08-47ab-a104-92125ae6cbdf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87994, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "既", "is_correct": true, "explanation": "既读 jì，表示两种情况同时存在，与听到的音一致。"}, {"text": "几", "is_correct": false, "explanation": "jǐ（第三声）与 jì（第四声）声调不同，意思是几个。"}, {"text": "集", "is_correct": false, "explanation": "jí（第二声）与 jì（第四声）声调不同，意思是聚集。"}, {"text": "去", "is_correct": false, "explanation": "qù 与 jì 声母不同（q 与 j），声调相同，意思是去。"}, {"text": "鸡", "is_correct": false, "explanation": "jī（第一声）与 jì（第四声）声调不同，意思是鸡。"}], "explanations": {"既": "既读 jì，表示两种情况同时存在，与听到的音一致。", "几": "jǐ（第三声）与 jì（第四声）声调不同，意思是几个。", "集": "jí（第二声）与 jì（第四声）声调不同，意思是聚集。", "去": "qù 与 jì 声母不同（q 与 j），声调相同，意思是去。", "鸡": "jī（第一声）与 jì（第四声）声调不同，意思是鸡。"}, "sentence_index": null, "correct_answer": "既"}, "level_3": {"options": [{"text": "既", "is_correct": true, "explanation": "“既”与“也”配合，表示两种身份同时存在，符合句意。"}, {"text": "因此", "is_correct": false, "explanation": "语义：“因此”引出结果，后句应是结论，“也是我的朋友”不能作为结果。"}, {"text": "与其", "is_correct": false, "explanation": "搭配：“与其”要与“不如”配合表示取舍比较，不能与“也”搭配。"}, {"text": "或", "is_correct": false, "explanation": "语域：“或”是书面语，且表示选择，与口语句中的“也是”并列不通顺。"}], "explanations": {"既": "“既”与“也”配合，表示两种身份同时存在，符合句意。", "因此": "语义：“因此”引出结果，后句应是结论，“也是我的朋友”不能作为结果。", "与其": "搭配：“与其”要与“不如”配合表示取舍比较，不能与“也”搭配。", "或": "语域：“或”是书面语，且表示选择，与口语句中的“也是”并列不通顺。"}, "sentence_index": 6, "correct_answer": "既"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他既很累，还是坚持跑完了。", "explanation": "这里应该用〈虽然〉。“既”要与“又”或“也”配合表示两种情况并存，不表示让步；表示让步应用“虽然”。"}, {"text": "我想要轻的既薄的手机。", "explanation": "这里应该用〈或者〉。“既”表示两种情况并存，要与“又”或“也”配合；表示二者选一应用“或者”。"}, {"text": "这家店的菜既便宜，好吃。", "explanation": "这里应该用〈并且〉。“既”要与“又”或“也”成对使用，缺少“又”时不能连接两种情况；表示并列应用“并且”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9884cfa0-9a08-47ab-a104-92125ae6cbdf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87994, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个城市既安静但干净。", "corrected_sentence": "这个城市既安静又干净。", "error_description": "连词错误：“既”要与“又”配合表示两种情况并存，与“但”搭配会变成转折，应为“既安静又干净”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9884cfa0-9a08-47ab-a104-92125ae6cbdf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87994, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们既要学习，但要工作。", "corrected_sentence": "我们既要学习，又要工作。", "error_description": "“又”被换成“但”：“既”要与“又”或“也”配合，表示两种情况并存；与“但”配合会变成转折，应改为“又要工作”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9884cfa0-9a08-47ab-a104-92125ae6cbdf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88005, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '040634d2-eecc-4f2b-ac40-4e35c0af5098') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88005, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '040634d2-eecc-4f2b-ac40-4e35c0af5098') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88005, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "有所是有一点，不是很多。", "primary_collocate": null, "pronunciation": "yǒu suǒ", "ipa": "jou˨˩˦ swo˨˩˦", "syllable_count": 2, "sentences": [{"text": "今天的天气有所好转。", "target_word": "有所", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个月的价格有所下降。", "target_word": "有所", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "吃了药以后，他的病情有所好转。", "target_word": "有所", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "最近学习压力有所减轻。", "target_word": "有所", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "经过努力，他的成绩有所提高。", "target_word": "有所", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这几天，路上的车有所减少。", "target_word": "有所", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "听了老师的话，他的态度有所改变。", "target_word": "有所", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比起去年，今年的收入有所增加。", "target_word": "有所", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "雨停了以后，空气有所改善。", "target_word": "有所", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他的汉语比以前有所进步。", "target_word": "有所", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "有所：程度很轻，后接动词，表示有一点变化，不是很多", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd8d3828f-e88f-4827-ada6-b99a5aa80d30') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88005, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "有所", "is_correct": true, "explanation": "正确：「有所」表示程度轻微的变化，可以与“好转”搭配。"}, {"text": "严重", "is_correct": false, "explanation": "搭配：“严重”只修饰负面状况，不能用来修饰“好转”。"}, {"text": "从来", "is_correct": false, "explanation": "搭配：“从来”多用于否定句，肯定句里不能说“从来好转”。"}, {"text": "一共", "is_correct": false, "explanation": "语义：“一共”表示总计，不能用来描述天气的变化。"}], "explanations": {"有所": "正确：「有所」表示程度轻微的变化，可以与“好转”搭配。", "严重": "搭配：“严重”只修饰负面状况，不能用来修饰“好转”。", "从来": "搭配：“从来”多用于否定句，肯定句里不能说“从来好转”。", "一共": "语义：“一共”表示总计，不能用来描述天气的变化。"}, "sentence_index": 0, "correct_answer": "有所"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "今年公司的利润有所翻了十倍。", "explanation": "语义：“有所”表示程度轻微的变化，“翻了十倍”是大幅变化，这里应该用〈大幅〉。"}, {"text": "他的病一夜之间有所痊愈了。", "explanation": "语义：“有所”只表示有一点变化，“痊愈”是彻底恢复，这里应该用〈彻底〉。"}, {"text": "他的口语有所进步，一年内从零基础到能主持节目。", "explanation": "语义：“有所”只表示有一点变化，“从零基础到能主持节目”是巨大变化，两者矛盾，这里应该用〈飞速〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '040634d2-eecc-4f2b-ac40-4e35c0af5098') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88005, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "有所", "is_correct": true, "explanation": "正确：「有所」表示变化的程度轻微，与“改变”搭配自然。"}, {"text": "始终", "is_correct": false, "explanation": "语义：“始终”表示一直不变，与“改变”的变化义矛盾。"}, {"text": "仍然", "is_correct": false, "explanation": "语义：“仍然”表示维持原来的状态，与“改变”矛盾。"}, {"text": "十分", "is_correct": false, "explanation": "搭配：“十分”修饰形容词或心理动词，不能修饰“改变”这样的动词。"}], "explanations": {"有所": "正确：「有所」表示变化的程度轻微，与“改变”搭配自然。", "始终": "语义：“始终”表示一直不变，与“改变”的变化义矛盾。", "仍然": "语义：“仍然”表示维持原来的状态，与“改变”矛盾。", "十分": "搭配：“十分”修饰形容词或心理动词，不能修饰“改变”这样的动词。"}, "sentence_index": 6, "correct_answer": "有所"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这次会议以后，大家的工作热情有所高涨，人人都加班到深夜。", "explanation": "语义：“有所”只表示有一点变化，“人人都加班到深夜”是热情大幅高涨，两者矛盾，这里应该用〈大幅〉。"}, {"text": "这次改革让公司的销量有所翻倍。", "explanation": "语义：“有所”只表示有一点变化，“翻倍”是数量成倍增加，两者矛盾，这里应该用〈成倍〉，不能用〈有所〉。"}, {"text": "他的体重有所增加，一个月里胖了二十公斤。", "explanation": "语义：“有所”只表示有一点变化，“一个月胖了二十公斤”是大幅变化，这里应该用〈大幅〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '040634d2-eecc-4f2b-ac40-4e35c0af5098') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88005, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他的成绩有所了下降。", "corrected_sentence": "他的成绩有所下降。", "error_description": "插入错误：“有所”是副词，直接修饰动词，中间不能插入“了”。应说“有所下降”，不能说“有所了下降”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '040634d2-eecc-4f2b-ac40-4e35c0af5098') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88005, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他的脾气有所的改变。", "corrected_sentence": "他的脾气有所改变。", "error_description": "插入错误：“有所”是副词，直接修饰动词，中间不能加“的”。应说“有所改变”，不能说“有所的改变”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '040634d2-eecc-4f2b-ac40-4e35c0af5098') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
