INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88006, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '040634d2-eecc-4f2b-ac40-4e35c0af5098') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88006, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "副词，表示在某种程度上有（变化、了解等）。", "primary_collocate": null, "pronunciation": "yǒu suǒ", "ipa": "jou˨˩˦ swo˨˩˦", "syllable_count": 2, "sentences": [{"text": "对这个城市，我已经有所了解。", "target_word": "有所", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "两个地方的习惯有所不同。", "target_word": "有所", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "出发以前，我们都有所准备。", "target_word": "有所", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这几年，人们的生活有所改变。", "target_word": "有所", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "关于这件事，我以前有所耳闻。", "target_word": "有所", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "读了这本书，我有所收获。", "target_word": "有所", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "听了我的建议，他有所考虑。", "target_word": "有所", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "虽然他不说，但我对他的想法有所了解。", "target_word": "有所", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "做这个工作，你要对市场有所认识。", "target_word": "有所", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "和去年比，今年大家的看法有所不同。", "target_word": "有所", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "有所：在某种程度上有，后接了解、不同、准备、收获等双音节动词", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd8d3828f-e88f-4827-ada6-b99a5aa80d30') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88006, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "有所", "is_correct": true, "explanation": "正确：「有所」表示在某种程度上有了解，与“了解”搭配自然。"}, {"text": "曾经", "is_correct": false, "explanation": "语义：“曾经”指过去的经历，与“已经”的时间表达重复、矛盾。"}, {"text": "总是", "is_correct": false, "explanation": "搭配：“总是”表示经常性的行为，不能修饰“了解”这类状态。"}, {"text": "一共", "is_correct": false, "explanation": "语义：“一共”表示总计，不能用来描述对城市的了解程度。"}], "explanations": {"有所": "正确：「有所」表示在某种程度上有了解，与“了解”搭配自然。", "曾经": "语义：“曾经”指过去的经历，与“已经”的时间表达重复、矛盾。", "总是": "搭配：“总是”表示经常性的行为，不能修饰“了解”这类状态。", "一共": "语义：“一共”表示总计，不能用来描述对城市的了解程度。"}, "sentence_index": 0, "correct_answer": "有所"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我对这个城市完全有所了解，连每条小路都走过。", "explanation": "语义：“有所”表示程度不深，“完全”表示彻底，两者矛盾，这里应该用〈非常〉。"}, {"text": "这几年，人们的生活有所彻底改变。", "explanation": "语义：“有所”只表示轻微的变化，“彻底”表示完全改变，两者矛盾，这里应该用〈大幅〉。"}, {"text": "我们两个的想法有所一致，每件事都完全相同。", "explanation": "语义：“有所”只表示程度不深，“每件事都完全相同”是完全一致，两者矛盾，这里应该用〈完全〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '040634d2-eecc-4f2b-ac40-4e35c0af5098') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88006, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "有所", "is_correct": true, "explanation": "正确：「有所」表示在某种程度上有考虑，与“考虑”搭配自然。"}, {"text": "不必", "is_correct": false, "explanation": "语义：“不必”表示不需要，与“有所考虑”的肯定语义相反。"}, {"text": "十分", "is_correct": false, "explanation": "搭配：“十分”不修饰“考虑”这类动词。"}, {"text": "一共", "is_correct": false, "explanation": "搭配：“一共”表示总计，不能直接修饰“考虑”这类动作。"}], "explanations": {"有所": "正确：「有所」表示在某种程度上有考虑，与“考虑”搭配自然。", "不必": "语义：“不必”表示不需要，与“有所考虑”的肯定语义相反。", "十分": "搭配：“十分”不修饰“考虑”这类动词。", "一共": "搭配：“一共”表示总计，不能直接修饰“考虑”这类动作。"}, "sentence_index": 6, "correct_answer": "有所"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她听了这个消息，有所哭了起来。", "explanation": "语义：这里误用了“有所”，它表示在某种程度上有变化或了解，不能表示〈开始〉的意思；直接说“哭了起来”即可。"}, {"text": "我们在电影院里有所看了一场电影。", "explanation": "语义：这里误用了“有所”，它表示在某种程度上有变化或了解，不是〈有些〉的数量义，不能用来说看了多少场电影。"}, {"text": "这本书我有所读过了三遍。", "explanation": "语义：这里误用了“有所”，它表示在某种程度上有了解，不是〈反复〉的次数义，与“读过了三遍”的次数表达矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '040634d2-eecc-4f2b-ac40-4e35c0af5098') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88006, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我对这件事已经有所了准备。", "corrected_sentence": "我对这件事已经有所准备。", "error_description": "插入错误：“有所”是副词，直接修饰动词，中间不能插入“了”。应说“已经有所准备”，不能说“已经有所了准备”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '040634d2-eecc-4f2b-ac40-4e35c0af5098') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88006, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他对这个问题有所的考虑。", "corrected_sentence": "他对这个问题有所考虑。", "error_description": "插入错误：“有所”是副词，直接修饰动词，中间不能加“的”。应说“有所考虑”，不能说“有所的考虑”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '040634d2-eecc-4f2b-ac40-4e35c0af5098') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88021, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '48c93dd2-8733-4a1a-82c1-dc57833b3687') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
