INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88021, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "自己人是和我们很亲，不是外人。", "primary_collocate": null, "pronunciation": "zì jǐ rén", "ipa": "tsɿ˥˩ tɕi˨˩˦ ʐən˧˥", "syllable_count": 3, "sentences": [{"text": "别客气，我们都是自己人。", "target_word": "自己人", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "你放心说，这里都是自己人。", "target_word": "自己人", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他对我们像对自己人一样好。", "target_word": "自己人", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "大家都把他当成自己人。", "target_word": "自己人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件事只能告诉自己人。", "target_word": "自己人", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "在这家店吃饭，老板把我们当自己人。", "target_word": "自己人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "对自己人，他从来不说假话。", "target_word": "自己人", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "来，坐吧，这儿没有外人，都是自己人。", "target_word": "自己人", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "跟自己人谈事情，不用那么客气。", "target_word": "自己人", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们是自己人，有话就直说吧。", "target_word": "自己人", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "口语", "sense_fingerprint": "和自己关系亲近、不必见外的人，与外人相对", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f8530ce5-0286-4987-b867-f019ea50f76c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88021, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "自己人", "is_correct": true, "explanation": "正确：“我们都是自己人”指彼此亲近、不见外，与“别客气”的语境相合。"}, {"text": "外人", "is_correct": false, "explanation": "语义：外人与自己人相对。“别客气，我们都是外人”与亲近的语境矛盾。"}, {"text": "敌人", "is_correct": false, "explanation": "语义：敌人是对立关系，不能和“别客气”一起描述“我们”的关系。"}, {"text": "官员", "is_correct": false, "explanation": "语域：官员是偏正式的身份称呼，与“别客气”这种随意口语的语气不合。"}], "explanations": {"自己人": "正确：“我们都是自己人”指彼此亲近、不见外，与“别客气”的语境相合。", "外人": "语义：外人与自己人相对。“别客气，我们都是外人”与亲近的语境矛盾。", "敌人": "语义：敌人是对立关系，不能和“别客气”一起描述“我们”的关系。", "官员": "语域：官员是偏正式的身份称呼，与“别客气”这种随意口语的语气不合。"}, "sentence_index": 0, "correct_answer": "自己人"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我家来了一件自己人。", "explanation": "这里应该用〈个〉。自己人指人，要用“个”或“位”来数，“件”用于物品，不能用来数人。"}, {"text": "这个邻居是我们的自己人，天天半夜来偷我家的东西。", "explanation": "这里应该用〈小偷〉。自己人意味着可以信任，与“半夜来偷东西”的行为矛盾，应说小偷。"}, {"text": "开会时，大家都把他请出去了，因为他是我们的自己人。", "explanation": "这里应该用〈外人〉。自己人是可以信任、可以留下的人，因“是自己人”而被请出去的说法与语境矛盾，应说外人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '48c93dd2-8733-4a1a-82c1-dc57833b3687') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88021, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "自己人", "is_correct": true, "explanation": "正确：“对自己人，他从来不说假话”表示对亲近的人守信，符合语境。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头不会听话，“对石头从来不说假话”没有意义。"}, {"text": "空气", "is_correct": false, "explanation": "配价：“说假话”需要能听的对象，空气不能作为听话的人。"}, {"text": "桌子", "is_correct": false, "explanation": "搭配：“对……说假话”的对象应是人，“桌子”与这一搭配不合。"}], "explanations": {"自己人": "正确：“对自己人，他从来不说假话”表示对亲近的人守信，符合语境。", "石头": "语义：石头不会听话，“对石头从来不说假话”没有意义。", "空气": "配价：“说假话”需要能听的对象，空气不能作为听话的人。", "桌子": "搭配：“对……说假话”的对象应是人，“桌子”与这一搭配不合。"}, "sentence_index": 6, "correct_answer": "自己人"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他是我们的自己人，却专门骗路人的钱。", "explanation": "这里应该用〈骗子〉。自己人意味着可以信任，与“专门骗路人的钱”的行为矛盾，应说骗子。"}, {"text": "路上的自己人走得很快。", "explanation": "这里应该用〈行人〉。自己人指亲近、可信任的人，路上不相识的人只能说行人。"}, {"text": "在地铁上，一个自己人一直盯着我看，我很不舒服。", "explanation": "这里应该用〈陌生人〉。自己人指亲近、可信任的人，在地铁上盯着我看的素不相识的人应说陌生人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '48c93dd2-8733-4a1a-82c1-dc57833b3687') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88021, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他是我们的一只自己人，大家都信任他。", "corrected_sentence": "他是我们的一个自己人，大家都信任他。", "error_description": "错误：量词“只”用错。自己人指人，应该用“个”，“只”多用于动物。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '48c93dd2-8733-4a1a-82c1-dc57833b3687') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88021, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他在我们眼里是头自己人。", "corrected_sentence": "他在我们眼里是个自己人。", "error_description": "错误：量词“头”用错。自己人指人，应该用“个”，“头”用于牲畜。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '48c93dd2-8733-4a1a-82c1-dc57833b3687') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88022, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '48c93dd2-8733-4a1a-82c1-dc57833b3687') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88022, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '48c93dd2-8733-4a1a-82c1-dc57833b3687') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88022, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "指自家的人；关系密切、可以信任的人。", "primary_collocate": null, "pronunciation": "zì jǐ rén", "ipa": "tsɿ˥˩ tɕi˨˩˦ ʐən˧˥", "syllable_count": 3, "sentences": [{"text": "他们都是自己人，不用担心。", "target_word": "自己人", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "过年的时候，只有自己人在家吃饭。", "target_word": "自己人", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这笔钱交给自己人，我才放心。", "target_word": "自己人", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "公司里的重要工作，他只让自己人做。", "target_word": "自己人", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "在外面工作，遇到自己人特别高兴。", "target_word": "自己人", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我哥哥帮我，当然是自己人帮自己人。", "target_word": "自己人", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "谁是自己人，谁是外人，他看得很清楚。", "target_word": "自己人", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个秘密，我只告诉过自己人。", "target_word": "自己人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "朋友们帮了我很多，我把他们当自己人。", "target_word": "自己人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司小，所以大家像自己人一样。", "target_word": "自己人", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "口语", "sense_fingerprint": "自家人或同一方、可以信任的人，与外人相对", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f8530ce5-0286-4987-b867-f019ea50f76c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88022, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "自己人", "is_correct": true, "explanation": "正确：“他们都是自己人，不用担心”表示彼此信任，符合语境。"}, {"text": "敌人", "is_correct": false, "explanation": "语义：敌人会让人担心，与“不用担心”的安心语境相反。"}, {"text": "小偷", "is_correct": false, "explanation": "语义：小偷让人警惕，“他们都是小偷，不用担心”与语境冲突。"}, {"text": "外人", "is_correct": false, "explanation": "搭配：“都是外人”强调身份界限，与“不用担心”所表达的信任不搭。"}], "explanations": {"自己人": "正确：“他们都是自己人，不用担心”表示彼此信任，符合语境。", "敌人": "语义：敌人会让人担心，与“不用担心”的安心语境相反。", "小偷": "语义：小偷让人警惕，“他们都是小偷，不用担心”与语境冲突。", "外人": "搭配：“都是外人”强调身份界限，与“不用担心”所表达的信任不搭。"}, "sentence_index": 0, "correct_answer": "自己人"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "街上走来一个自己人，我们都提高了警惕。", "explanation": "这里应该用〈陌生人〉。自己人指可以信任的人，对走来的陌生人应说陌生人，并且要提高警惕。"}, {"text": "公司派了一只自己人去谈判。", "explanation": "这里应该用〈个〉。自己人指人，要用“个”或“位”来数，“只”用于动物。"}, {"text": "这个会议只对自己人开放，他是我们的自己人，所以不能进去。", "explanation": "这里应该用〈外人〉。自己人指可以信任、可以让其进入的人，“只对自己人开放”的语境中，他是自己人却不能进去，应说外人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '48c93dd2-8733-4a1a-82c1-dc57833b3687') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88022, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "自己人", "is_correct": true, "explanation": "正确：“谁是自己人，谁是外人”形成对照，符合语境。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头不分内外，“谁是石头”与语境不符。"}, {"text": "空气", "is_correct": false, "explanation": "语义：空气没有内外之分，不能与“外人”对照。"}, {"text": "桌子", "is_correct": false, "explanation": "搭配：“谁是……”要求指人，“桌子”与这一搭配不合。"}], "explanations": {"自己人": "正确：“谁是自己人，谁是外人”形成对照，符合语境。", "石头": "语义：石头不分内外，“谁是石头”与语境不符。", "空气": "语义：空气没有内外之分，不能与“外人”对照。", "桌子": "搭配：“谁是……”要求指人，“桌子”与这一搭配不合。"}, "sentence_index": 6, "correct_answer": "自己人"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个人是我的自己人，我从不信任他，每次见面都要提防他。", "explanation": "这里应该用〈仇人〉。自己人意味着可以信任，与“从不信任、每次见面都要提防”的语境矛盾，对需要提防的人应说仇人。"}, {"text": "街上的自己人走得很快，我们都追不上。", "explanation": "这里应该用〈行人〉。自己人指亲近、可信任的人，街上不相识的人只能说行人。"}, {"text": "这个自己人专门骗老人的钱。", "explanation": "这里应该用〈骗子〉。自己人意味着可以信任，与“专门骗钱”的行为矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '48c93dd2-8733-4a1a-82c1-dc57833b3687') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88022, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他是我的一条自己人。", "corrected_sentence": "他是我的一个自己人。", "error_description": "错误：量词“条”用错。自己人指人，应该用“个”，“条”用于细长的东西。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '48c93dd2-8733-4a1a-82c1-dc57833b3687') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88022, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他是我们的一台自己人。", "corrected_sentence": "他是我们的一位自己人。", "error_description": "错误：量词“台”用错。自己人指人，应该用“位”或“个”，“台”用于机器。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '48c93dd2-8733-4a1a-82c1-dc57833b3687') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
