INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88028, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "设想中居住在地球以外其他星球上的生物。", "primary_collocate": null, "pronunciation": "wài xīng rén", "ipa": "wai̯˥˩ ɕiŋ˥ ɻən˧˥", "syllable_count": 3, "sentences": [{"text": "科学家想知道外星人是不是真的存在。", "target_word": "外星人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个电台一直在找外星人发来的信号。", "target_word": "外星人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "很多人觉得外星人可能比人类更聪明。", "target_word": "外星人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他写了一本关于外星人的书。", "target_word": "外星人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "外星人真的来了，人们会怎么办？", "target_word": "外星人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "据说那个小镇上有人见过外星人。", "target_word": "外星人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个游戏里，你要打败外星人。", "target_word": "外星人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "科学家还没有发现外星人的证据。", "target_word": "外星人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那位作家想象中的外星人住在海底。", "target_word": "外星人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "外星人在这部小说里是主角。", "target_word": "外星人", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "位", "label": "量词"}], "register": "中性", "sense_fingerprint": "设想中地球以外星球上的生物（科学、科幻语境）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5476bafa-4a1b-4403-b163-44a07b2b0ef2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88028, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "外星人", "is_correct": true, "explanation": "正确。外星人是设想中的生物，正是科学家想要验证其是否存在的对象。"}, {"text": "老师", "is_correct": false, "explanation": "语义：老师是现实中的人，科学家不会怀疑他“是不是真的存在”。"}, {"text": "空气", "is_correct": false, "explanation": "语义：空气显然存在，不需要“想知道是不是真的存在”。"}, {"text": "日期", "is_correct": false, "explanation": "搭配：“是不是真的存在”多用于事物或现象，“日期”不这样搭配。"}], "explanations": {"外星人": "正确。外星人是设想中的生物，正是科学家想要验证其是否存在的对象。", "老师": "语义：老师是现实中的人，科学家不会怀疑他“是不是真的存在”。", "空气": "语义：空气显然存在，不需要“想知道是不是真的存在”。", "日期": "搭配：“是不是真的存在”多用于事物或现象，“日期”不这样搭配。"}, "sentence_index": 0, "correct_answer": "外星人"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他每天早上开外星人去公司上班。", "explanation": "这里应该用〈汽车〉。“开”的宾语应是车辆，外星人是生物，不能用来驾驶。"}, {"text": "他明天要去外星人考察生物。", "explanation": "这里应该用〈外星球〉。“外星人”指生物，不能当作考察的地点；表示地点要用“外星球”。"}, {"text": "他用外星人钉钉子。", "explanation": "这里应该用〈锤子〉。外星人是生物，不能当作工具使用。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '81b2f6d0-4009-4c46-a64f-4bf1effb2f7d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88028, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "外星人", "is_correct": true, "explanation": "正确。游戏里的敌人正是外星人，句子意思完整。"}, {"text": "空气", "is_correct": false, "explanation": "搭配：“打败”的对象应是对手或敌人，不说打败空气。"}, {"text": "雨水", "is_correct": false, "explanation": "语义：雨水不是能被打败的对手，这句话说不通。"}, {"text": "钟表", "is_correct": false, "explanation": "配价：“打败”要求能与之对抗的对象，钟表不能充当。"}], "explanations": {"外星人": "正确。游戏里的敌人正是外星人，句子意思完整。", "空气": "搭配：“打败”的对象应是对手或敌人，不说打败空气。", "雨水": "语义：雨水不是能被打败的对手，这句话说不通。", "钟表": "配价：“打败”要求能与之对抗的对象，钟表不能充当。"}, "sentence_index": 6, "correct_answer": "外星人"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这位工程师发明了外星人，还给它申请了专利。", "explanation": "这里应该用〈想象〉。外星人是想象中的生物，不能当作发明物去申请专利。"}, {"text": "这台新手机就是一个外星人，功能很多。", "explanation": "这里应该用〈设备〉。“外星人”指想象中住在别的星球上的生物，不能用来称呼手机。"}, {"text": "这家公司每天都在制造很多外星人。", "explanation": "这里应该用〈设计〉。外星人是想象中的生物，不能像产品一样大量制造。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '81b2f6d0-4009-4c46-a64f-4bf1effb2f7d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88028, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "街上突然走出来一棵外星人。", "corrected_sentence": "街上突然走出来一个外星人。", "error_description": "错误：量词“棵”用于树木，不能计量外星人。正确：“一个外星人”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '81b2f6d0-4009-4c46-a64f-4bf1effb2f7d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88028, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他画了一把外星人，很可爱。", "corrected_sentence": "他画了一个外星人，很可爱。", "error_description": "错误：量词“把”用于有柄的器具，不能计量外星人。正确：“一个外星人”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '81b2f6d0-4009-4c46-a64f-4bf1effb2f7d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
