INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88044, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "用强力使对方服从；强迫。", "primary_collocate": null, "pronunciation": "bī", "ipa": "pi˥", "syllable_count": 1, "sentences": [{"text": "敌人逼他交出了地图。", "target_word": "逼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "坏人逼老人把钱交出来。", "target_word": "逼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "官兵逼百姓交粮食。", "target_word": "逼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们用刀逼司机停车。", "target_word": "逼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "警察逼小偷放下了刀。", "target_word": "逼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "强盗逼着村民搬走了。", "target_word": "逼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "敌军逼将军投降。", "target_word": "逼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们用暴力逼我签了字。", "target_word": "逼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国王逼大臣说出了秘密。", "target_word": "逼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "坏人用枪逼他开了门。", "target_word": "逼", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "逼着", "label": "体标"}, {"form": "逼了", "label": "体标"}], "register": "中性", "sense_fingerprint": "用强力、武力或暴力迫使对方服从", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ac8ff967-745b-40e1-9201-f6f0972c5a6d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88044, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "逼", "is_correct": true, "explanation": "正确答案：逼（bī），意思是用强力使对方服从。"}, {"text": "比", "is_correct": false, "explanation": "bǐ（第三声）与 bī（第一声）声调不同，意思是比较。"}, {"text": "鼻", "is_correct": false, "explanation": "bí（第二声）与 bī（第一声）声调不同，意思是鼻子。"}, {"text": "闭", "is_correct": false, "explanation": "bì（第四声）与 bī（第一声）声调不同，意思是关闭。"}, {"text": "批", "is_correct": false, "explanation": "pī（第一声）与 bī（第一声）声母不同（p 与 b），意思是批准、批评。"}, {"text": "低", "is_correct": false, "explanation": "dī（第一声）与 bī（第一声）声母不同（d 与 b），意思是低。"}], "explanations": {"逼": "正确答案：逼（bī），意思是用强力使对方服从。", "比": "bǐ（第三声）与 bī（第一声）声调不同，意思是比较。", "鼻": "bí（第二声）与 bī（第一声）声调不同，意思是鼻子。", "闭": "bì（第四声）与 bī（第一声）声调不同，意思是关闭。", "批": "pī（第一声）与 bī（第一声）声母不同（p 与 b），意思是批准、批评。", "低": "dī（第一声）与 bī（第一声）声母不同（d 与 b），意思是低。"}, "sentence_index": null, "correct_answer": "逼"}, "level_3": {"options": [{"text": "逼", "is_correct": true, "explanation": "正确：“敌人逼他交出地图”表示敌人用强力迫使他服从，语境相合。"}, {"text": "保护", "is_correct": false, "explanation": "语义：“保护”与敌人用强力迫使对方交出地图的意图相反。"}, {"text": "欢迎", "is_correct": false, "explanation": "搭配：“欢迎”不用于强迫对方交出东西，搭配不当。"}, {"text": "慰问", "is_correct": false, "explanation": "配价：“慰问”后不能接“交出了地图”这样的兼语小句。"}], "explanations": {"逼": "正确：“敌人逼他交出地图”表示敌人用强力迫使他服从，语境相合。", "保护": "语义：“保护”与敌人用强力迫使对方交出地图的意图相反。", "欢迎": "搭配：“欢迎”不用于强迫对方交出东西，搭配不当。", "慰问": "配价：“慰问”后不能接“交出了地图”这样的兼语小句。"}, "sentence_index": 0, "correct_answer": "逼"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "特警冲进大楼，逼了人质。", "explanation": "这里应该用〈解救〉。逼是强迫，此处是把人质救出，不是逼迫他们。"}, {"text": "他用糖果逼小孩上车。", "explanation": "这里应该用〈诱骗〉。逼是强迫，与“糖果”这种诱饵的手段矛盾。"}, {"text": "他心甘情愿地被逼交出了钱。", "explanation": "这里应该用〈劝〉。逼是用强力使对方服从，与“心甘情愿”矛盾；劝是说服对方自愿去做。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f7b918d-c73d-4c78-b735-3ef7235ac0cb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88044, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "逼", "is_correct": true, "explanation": "正确答案：逼（bī），意思是用强力使对方服从。"}, {"text": "笔", "is_correct": false, "explanation": "bǐ（第三声）与 bī（第一声）声调不同，意思是笔。"}, {"text": "必", "is_correct": false, "explanation": "bì（第四声）与 bī（第一声）声调不同，意思是必须。"}, {"text": "披", "is_correct": false, "explanation": "pī（第一声）与 bī（第一声）声母不同（p 与 b），意思是披上。"}, {"text": "滴", "is_correct": false, "explanation": "dī（第一声）与 bī（第一声）声母不同（d 与 b），意思是滴下。"}], "explanations": {"逼": "正确答案：逼（bī），意思是用强力使对方服从。", "笔": "bǐ（第三声）与 bī（第一声）声调不同，意思是笔。", "必": "bì（第四声）与 bī（第一声）声调不同，意思是必须。", "披": "pī（第一声）与 bī（第一声）声母不同（p 与 b），意思是披上。", "滴": "dī（第一声）与 bī（第一声）声母不同（d 与 b），意思是滴下。"}, "sentence_index": null, "correct_answer": "逼"}, "level_3": {"options": [{"text": "逼", "is_correct": true, "explanation": "正确：“敌军逼将军投降”表示敌军用强力迫使将军服从，语境相合。"}, {"text": "恭喜", "is_correct": false, "explanation": "语义：敌军恭喜将军投降，与敌军迫使对方的语境相反。"}, {"text": "感谢", "is_correct": false, "explanation": "语义：敌军感谢将军投降不合逻辑，与敌军迫使将军服从的语境相反。"}, {"text": "赞美", "is_correct": false, "explanation": "语义：赞美将军投降不符合敌军强迫对方的语境。"}], "explanations": {"逼": "正确：“敌军逼将军投降”表示敌军用强力迫使将军服从，语境相合。", "恭喜": "语义：敌军恭喜将军投降，与敌军迫使对方的语境相反。", "感谢": "语义：敌军感谢将军投降不合逻辑，与敌军迫使将军服从的语境相反。", "赞美": "语义：赞美将军投降不符合敌军强迫对方的语境。"}, "sentence_index": 6, "correct_answer": "逼"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "老师用爱心逼了那个调皮的学生。", "explanation": "这里应该用〈感化〉。逼是强迫，与“用爱心”的方式矛盾。"}, {"text": "他是自愿的，却被大家逼着签了字。", "explanation": "这里应该用〈说服〉。逼是用强力使对方服从，与“自愿”矛盾；说服是让对方自己同意去做。"}, {"text": "他高高兴兴地被逼去唱了一首歌。", "explanation": "这里应该用〈邀请〉。逼是用强力使对方服从，与“高高兴兴”的心情矛盾；邀请是客气地请对方去做。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f7b918d-c73d-4c78-b735-3ef7235ac0cb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88044, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "土匪逼让商人交出了钱。", "corrected_sentence": "土匪逼着商人交出了钱。", "error_description": "“逼”已表示使令，不能再与“让”连用，构成重复使令。应将“让”改为表示持续的“着”，写作：土匪逼着商人交出了钱。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f7b918d-c73d-4c78-b735-3ef7235ac0cb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88044, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们用刀逼让农民交出了钱。", "corrected_sentence": "他们用刀逼农民交出了钱。", "error_description": "“逼”已表示使令，其后不能再加“让”，构成重复使令。应去掉“让”，写作：他们用刀逼农民交出了钱。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f7b918d-c73d-4c78-b735-3ef7235ac0cb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88049, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "出", "is_correct": true, "explanation": "“出”与“入”构成反义：“入”是从外面到里面，“出”是从里面到外面，与“走入”相对的是“走出”。"}, {"text": "跑", "is_correct": false, "explanation": "“跑”与“入”没有反义关系，二者不是相对的动作。"}, {"text": "坐", "is_correct": false, "explanation": "“坐”与“入”没有反义关系，二者不是相对的动作。"}, {"text": "唱", "is_correct": false, "explanation": "“唱”与“入”没有反义关系，二者不是相对的动作。"}], "correct_answer": "出", "explanations": {"出": "“出”与“入”构成反义：“入”是从外面到里面，“出”是从里面到外面，与“走入”相对的是“走出”。", "跑": "“跑”与“入”没有反义关系，二者不是相对的动作。", "坐": "“坐”与“入”没有反义关系，二者不是相对的动作。", "唱": "“唱”与“入”没有反义关系，二者不是相对的动作。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9884cfa0-9a08-47ab-a104-92125ae6cbdf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88049, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "出", "is_correct": true, "explanation": "“出”与“入”构成反义：“入”是从外面到里面，“出”是从里面到外面，与“进入”相对。"}, {"text": "玩", "is_correct": false, "explanation": "“玩”与“入”没有反义关系，二者不是相对的动作。"}, {"text": "睡", "is_correct": false, "explanation": "“睡”与“入”没有反义关系，二者不是相对的动作。"}, {"text": "说", "is_correct": false, "explanation": "“说”与“入”没有反义关系，二者不是相对的动作。"}], "correct_answer": "出", "explanations": {"出": "“出”与“入”构成反义：“入”是从外面到里面，“出”是从里面到外面，与“进入”相对。", "玩": "“玩”与“入”没有反义关系，二者不是相对的动作。", "睡": "“睡”与“入”没有反义关系，二者不是相对的动作。", "说": "“说”与“入”没有反义关系，二者不是相对的动作。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9884cfa0-9a08-47ab-a104-92125ae6cbdf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88049, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "入指人、动物或交通工具自己从外面移动到里面。", "primary_collocate": null, "pronunciation": "rù", "ipa": "ʐu˥˩", "syllable_count": 1, "sentences": [{"text": "他推开门，走入教室。", "target_word": "入", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "小鸟飞入树林，不见了。", "target_word": "入", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子笑着跑入妈妈的怀里。", "target_word": "入", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们沿着小路走入山谷。", "target_word": "入", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "火车慢慢驶入车站。", "target_word": "入", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他从后门悄悄溜入了会场。", "target_word": "入", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "雨停了，我们走入花园散步。", "target_word": "入", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "飞机穿过云层，飞入蓝天。", "target_word": "入", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "门口没人，他大步走入大厅。", "target_word": "入", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这里是办公室，非请勿入。", "target_word": "入", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "入口", "label": "复合"}, {"form": "入内", "label": "复合"}], "register": "书面语", "sense_fingerprint": "入：人、动物或交通工具自己从外面移动到里面（走入、飞入、驶入、请勿入）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 5 above tier T1: 3 words above tier T1 (max 2): 后门 (Zipf 3.75), 悄悄 (Zipf 3.95), 溜 (Zipf 3.92)']::text[], '3a694cc8-f902-4891-9c84-c2b01ecc1500') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88049, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "入", "is_correct": true, "explanation": "入读 rù，表示从外面走到里面，与听到的音一致。"}, {"text": "如", "is_correct": false, "explanation": "rú（第二声）与 rù（第四声）声调不同，意思是如果、像。"}, {"text": "乳", "is_correct": false, "explanation": "rǔ（第三声）与 rù（第四声）声调不同，意思是乳汁。"}, {"text": "路", "is_correct": false, "explanation": "lù 与 rù 声母不同（l 与 r），声调相同，意思是道路。"}, {"text": "露", "is_correct": false, "explanation": "lù 与 rù 声母不同（l 与 r），声调相同，意思是露水。"}], "explanations": {"入": "入读 rù，表示从外面走到里面，与听到的音一致。", "如": "rú（第二声）与 rù（第四声）声调不同，意思是如果、像。", "乳": "rǔ（第三声）与 rù（第四声）声调不同，意思是乳汁。", "路": "lù 与 rù 声母不同（l 与 r），声调相同，意思是道路。", "露": "lù 与 rù 声母不同（l 与 r），声调相同，意思是露水。"}, "sentence_index": null, "correct_answer": "入"}, "level_3": {"options": [{"text": "入", "is_correct": true, "explanation": "“入”表示从外面进到里面，与“推开门”的动作相连，符合句意。"}, {"text": "管理", "is_correct": false, "explanation": "语义：“管理”指负责、掌管，与“推开门”之后的移动不相连，句意不通。"}, {"text": "修理", "is_correct": false, "explanation": "搭配：“修理”多用于修复物品，不与人的位移动作“走”搭配。"}, {"text": "爱", "is_correct": false, "explanation": "语义：“爱”表示喜欢的情感，与“推开门”后的移动动作不合。"}], "explanations": {"入": "“入”表示从外面进到里面，与“推开门”的动作相连，符合句意。", "管理": "语义：“管理”指负责、掌管，与“推开门”之后的移动不相连，句意不通。", "修理": "搭配：“修理”多用于修复物品，不与人的位移动作“走”搭配。", "爱": "语义：“爱”表示喜欢的情感，与“推开门”后的移动动作不合。"}, "sentence_index": 0, "correct_answer": "入"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他从屋里走入院子外面。", "explanation": "这里的“入”表示进到里面，院子外面不是里面；表示向外走应该用〈走出〉。"}, {"text": "小猫跑入了山顶。", "explanation": "这里的“入”表示进到里面，山顶不是可以走进去的里面；此处应该用〈爬上〉。"}, {"text": "他笑入了教室。", "explanation": "这里的“入”需要与表示移动的动作搭配；“笑”不是移动动作，不能表示走进去，应该用〈走〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9884cfa0-9a08-47ab-a104-92125ae6cbdf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88049, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "入", "is_correct": true, "explanation": "入读 rù，表示从外面走到里面，与听到的音一致。"}, {"text": "鹿", "is_correct": false, "explanation": "lù 与 rù 声母不同（l 与 r），声调相同，意思是鹿。"}, {"text": "录", "is_correct": false, "explanation": "lù 与 rù 声母不同（l 与 r），声调相同，意思是记录。"}, {"text": "怒", "is_correct": false, "explanation": "nù 与 rù 声母不同（n 与 r），声调相同，意思是愤怒。"}, {"text": "日", "is_correct": false, "explanation": "rì（第四声）与 rù 韵母不同（i 与 u），意思是太阳、日子。"}], "explanations": {"入": "入读 rù，表示从外面走到里面，与听到的音一致。", "鹿": "lù 与 rù 声母不同（l 与 r），声调相同，意思是鹿。", "录": "lù 与 rù 声母不同（l 与 r），声调相同，意思是记录。", "怒": "nù 与 rù 声母不同（n 与 r），声调相同，意思是愤怒。", "日": "rì（第四声）与 rù 韵母不同（i 与 u），意思是太阳、日子。"}, "sentence_index": null, "correct_answer": "入"}, "level_3": {"options": [{"text": "入", "is_correct": true, "explanation": "“入”表示从外面进到里面，与“走”和“花园”搭配，符合句意。"}, {"text": "照顾", "is_correct": false, "explanation": "语义：“照顾”表示照料，“我们照顾花园散步”后半句不通，且“照顾”不表示走入。"}, {"text": "设计", "is_correct": false, "explanation": "语义：“设计”指规划绘图，与“雨停了”之后的散步不相连，句意不通。"}, {"text": "维护", "is_correct": false, "explanation": "语义：“维护”指保养保护，与“雨停了”之后的散步动作不合。"}], "explanations": {"入": "“入”表示从外面进到里面，与“走”和“花园”搭配，符合句意。", "照顾": "语义：“照顾”表示照料，“我们照顾花园散步”后半句不通，且“照顾”不表示走入。", "设计": "语义：“设计”指规划绘图，与“雨停了”之后的散步不相连，句意不通。", "维护": "语义：“维护”指保养保护，与“雨停了”之后的散步动作不合。"}, "sentence_index": 6, "correct_answer": "入"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他睡入了教室。", "explanation": "这里的“入”表示走进去，需要移动动作；“睡”不是移动，不能与“入”搭配，应该用〈走〉。"}, {"text": "他的笑容入了门外。", "explanation": "这里的“入”表示进到里面，门外不是里面；“笑容”不能走，表示向外应该用〈飘出〉。"}, {"text": "孩子把头探入了窗户外面。", "explanation": "这里的“入”表示进到里面，窗外不是里面；表示向外伸出应该用〈探出〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9884cfa0-9a08-47ab-a104-92125ae6cbdf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88049, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "小猫悄悄走了入厨房。", "corrected_sentence": "小猫悄悄走入了厨房。", "error_description": "“了”位置错误：“了”应放在补语“入”之后，即“走入了厨房”，不能插在“走”和“入”之间。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9884cfa0-9a08-47ab-a104-92125ae6cbdf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88049, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "小狗入跑了院子。", "corrected_sentence": "小狗跑入了院子。", "error_description": "“入”位置错误：“入”是补语，应紧跟动词“跑”之后，即“跑入”，不能放在“跑”前面。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9884cfa0-9a08-47ab-a104-92125ae6cbdf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88050, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "出", "is_correct": true, "explanation": "“出”与“入”构成反义：“入”指东西进到里面，“出”指东西到外面，与“放入”相对的是“取出”。"}, {"text": "写", "is_correct": false, "explanation": "“写”与“入”没有反义关系，二者不是相对的动作。"}, {"text": "洗", "is_correct": false, "explanation": "“洗”与“入”没有反义关系，二者不是相对的动作。"}, {"text": "喝", "is_correct": false, "explanation": "“喝”与“入”没有反义关系，二者不是相对的动作。"}], "correct_answer": "出", "explanations": {"出": "“出”与“入”构成反义：“入”指东西进到里面，“出”指东西到外面，与“放入”相对的是“取出”。", "写": "“写”与“入”没有反义关系，二者不是相对的动作。", "洗": "“洗”与“入”没有反义关系，二者不是相对的动作。", "喝": "“喝”与“入”没有反义关系，二者不是相对的动作。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9884cfa0-9a08-47ab-a104-92125ae6cbdf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
