INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88050, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "东西或液体进到容器或空间的里面，与“出”相对。", "primary_collocate": null, "pronunciation": "rù", "ipa": "ʐu˥˩", "syllable_count": 1, "sentences": [{"text": "把牛奶倒入杯子里。", "target_word": "入", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把盐放入汤里，再搅一搅。", "target_word": "入", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "河水流入大海。", "target_word": "入", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他把钥匙放入口袋里。", "target_word": "入", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "雨水从窗缝流入屋里。", "target_word": "入", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "先把鸡蛋打入碗中，再加一点盐。", "target_word": "入", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把文件放入抽屉里。", "target_word": "入", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "把脏衣服放入洗衣机里。", "target_word": "入", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "水不断流入池子，很快就满了。", "target_word": "入", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "请把照片放入信封里。", "target_word": "入", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "入口", "label": "复合"}, {"form": "出入", "label": "复合"}], "register": "书面语", "sense_fingerprint": "入：东西或液体进到里面，与「出」相对（倒入、放入、流入、打入）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 4 above tier T1: 3 words above tier T1 (max 2): 雨水 (Zipf 3.94), 窗 (Zipf 3.98), 缝 (Zipf 3.92)']::text[], '3a694cc8-f902-4891-9c84-c2b01ecc1500') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88050, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "入", "is_correct": true, "explanation": "入读 rù，表示东西或液体进到里面，与听到的音一致。"}, {"text": "如", "is_correct": false, "explanation": "rú（第二声）与 rù（第四声）声调不同，意思是如果、像。"}, {"text": "乳", "is_correct": false, "explanation": "rǔ（第三声）与 rù（第四声）声调不同，意思是乳汁。"}, {"text": "怒", "is_correct": false, "explanation": "nù 与 rù 声母不同（n 与 r），声调相同，意思是愤怒。"}, {"text": "露", "is_correct": false, "explanation": "lù 与 rù 声母不同（l 与 r），声调相同，意思是露水。"}], "explanations": {"入": "入读 rù，表示东西或液体进到里面，与听到的音一致。", "如": "rú（第二声）与 rù（第四声）声调不同，意思是如果、像。", "乳": "rǔ（第三声）与 rù（第四声）声调不同，意思是乳汁。", "怒": "nù 与 rù 声母不同（n 与 r），声调相同，意思是愤怒。", "露": "lù 与 rù 声母不同（l 与 r），声调相同，意思是露水。"}, "sentence_index": null, "correct_answer": "入"}, "level_3": {"options": [{"text": "入", "is_correct": true, "explanation": "“入”表示东西进到容器里，与“倒”搭配，符合句意。"}, {"text": "扔", "is_correct": false, "explanation": "语义：“扔”表示丢弃，与“把牛奶”进到杯子里的注入动作不符。"}, {"text": "泼", "is_correct": false, "explanation": "搭配：“泼”多指液体溅出，与把牛奶注入杯子的动作不搭配。"}, {"text": "搅", "is_correct": false, "explanation": "语义：“搅”表示搅动，与“倒”进杯子的动作不同，句意不通。"}], "explanations": {"入": "“入”表示东西进到容器里，与“倒”搭配，符合句意。", "扔": "语义：“扔”表示丢弃，与“把牛奶”进到杯子里的注入动作不符。", "泼": "搭配：“泼”多指液体溅出，与把牛奶注入杯子的动作不搭配。", "搅": "语义：“搅”表示搅动，与“倒”进杯子的动作不同，句意不通。"}, "sentence_index": 0, "correct_answer": "入"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他把钥匙从口袋里入到外面。", "explanation": "这里应该用〈拿出〉。“入”表示进到里面，与“出”相对，不能表示从里面到外面。"}, {"text": "他把牛奶入到桌子上。", "explanation": "这里应该用〈倒在〉。“入”需要进入容器或空间的里面，桌面不是里面，不能用“入”。"}, {"text": "孩子入了一口气。", "explanation": "这里应该用〈吸入〉。“入”不能单独表示吸气，吸气要用“吸入”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9884cfa0-9a08-47ab-a104-92125ae6cbdf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88050, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "入", "is_correct": true, "explanation": "入读 rù，表示东西或液体进到里面，与听到的音一致。"}, {"text": "路", "is_correct": false, "explanation": "lù 与 rù 声母不同（l 与 r），声调相同，意思是道路。"}, {"text": "鹿", "is_correct": false, "explanation": "lù 与 rù 声母不同（l 与 r），声调相同，意思是鹿。"}, {"text": "录", "is_correct": false, "explanation": "lù 与 rù 声母不同（l 与 r），声调相同，意思是记录。"}, {"text": "日", "is_correct": false, "explanation": "rì（第四声）与 rù 韵母不同（i 与 u），意思是太阳、日子。"}], "explanations": {"入": "入读 rù，表示东西或液体进到里面，与听到的音一致。", "路": "lù 与 rù 声母不同（l 与 r），声调相同，意思是道路。", "鹿": "lù 与 rù 声母不同（l 与 r），声调相同，意思是鹿。", "录": "lù 与 rù 声母不同（l 与 r），声调相同，意思是记录。", "日": "rì（第四声）与 rù 韵母不同（i 与 u），意思是太阳、日子。"}, "sentence_index": null, "correct_answer": "入"}, "level_3": {"options": [{"text": "入", "is_correct": true, "explanation": "“入”表示东西进到里面，“请把文件放入抽屉里”符合句意。"}, {"text": "扔", "is_correct": false, "explanation": "语义：“扔”表示丢弃，“放扔抽屉里”不成句，且不表示进入。"}, {"text": "撕", "is_correct": false, "explanation": "语义：“撕”表示用力分开，与“放”连用不通，句意不成立。"}, {"text": "烧", "is_correct": false, "explanation": "语义：“烧”表示燃烧，与“放”连用不通，也不表示进入抽屉。"}], "explanations": {"入": "“入”表示东西进到里面，“请把文件放入抽屉里”符合句意。", "扔": "语义：“扔”表示丢弃，“放扔抽屉里”不成句，且不表示进入。", "撕": "语义：“撕”表示用力分开，与“放”连用不通，句意不成立。", "烧": "语义：“烧”表示燃烧，与“放”连用不通，也不表示进入抽屉。"}, "sentence_index": 6, "correct_answer": "入"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他入了一杯水。", "explanation": "这里应该用〈倒入〉。“入”不能单独表示把液体倒进去，要说“倒入”。"}, {"text": "孩子把玩具入到床底下。", "explanation": "这里应该用〈塞〉。床底下是下面，不是可以进入的里面，“入”不能表示塞到下面。"}, {"text": "他把信入了信箱。", "explanation": "这里应该用〈投入〉。“入”不能单独表示投递，投信要说“投入”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9884cfa0-9a08-47ab-a104-92125ae6cbdf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88050, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她把糖倒了入牛奶里。", "corrected_sentence": "她把糖倒入了牛奶里。", "error_description": "“了”位置错误：应为“倒入了”，“了”放在“入”之后，不能插在“倒”和“入”之间。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9884cfa0-9a08-47ab-a104-92125ae6cbdf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88050, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她把盐撒进入汤里。", "corrected_sentence": "她把盐撒入汤里。", "error_description": "多加了“进”：“入”本身已表示进到里面，前面不能再加“进”，应直接说“撒入”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9884cfa0-9a08-47ab-a104-92125ae6cbdf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
