INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88055, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "再次是又一次，和上一次一样。", "primary_collocate": null, "pronunciation": "zài cì", "ipa": "tsai˥˩ tsʰɨ˥˩", "syllable_count": 2, "sentences": [{"text": "天气再次变冷了。", "target_word": "再次", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他再次回到了老家。", "target_word": "再次", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我再次给妈妈打电话。", "target_word": "再次", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次我再次拿了第一。", "target_word": "再次", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她再次告诉我要小心。", "target_word": "再次", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "火车再次开动了。", "target_word": "再次", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你能再次帮我看一下吗？", "target_word": "再次", "complexity_tier": "T3", "furigana": "zài cì", "sentence_source": "generated"}, {"text": "小狗再次跑到了门口。", "target_word": "再次", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们再次来到这家饭馆。", "target_word": "再次", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他再次站在老师面前。", "target_word": "再次", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性偏书面", "sense_fingerprint": "又一次，和上一次一样", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7b9c7047-c41d-4dd6-a29e-9eca3dfeee0a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88055, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "必须", "is_correct": false, "explanation": "语义：“必须”表示必要或义务，需要行为的主体，不能用来说天气的变化。"}, {"text": "很", "is_correct": false, "explanation": "搭配：“很”修饰形容词，不修饰“变冷”这类变化动词。"}, {"text": "连忙", "is_correct": false, "explanation": "搭配：“连忙”修饰人的动作，不修饰“变冷了”这类天气变化。"}, {"text": "再次", "is_correct": true, "explanation": "“再次”表示又一次，与“天气再次变冷了”中同上一次一样的变化相符。"}], "explanations": {"必须": "语义：“必须”表示必要或义务，需要行为的主体，不能用来说天气的变化。", "很": "搭配：“很”修饰形容词，不修饰“变冷”这类变化动词。", "连忙": "搭配：“连忙”修饰人的动作，不修饰“变冷了”这类天气变化。", "再次": "“再次”表示又一次，与“天气再次变冷了”中同上一次一样的变化相符。"}, "sentence_index": 0, "correct_answer": "再次"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "妈妈先做饭，再次洗碗。", "explanation": "这里应该用“然后”，不用“再次”。“再次”表示同一动作又发生，不用于表示先后顺序。"}, {"text": "我从来没读过这本书，却再次读完了它。", "explanation": "这里不用“再次”。句中说“从来没读过”，而“再次”要求此前已经做过同样的事，前提不成立；表示初次时应说“第一次”。"}, {"text": "小狗一直再次叫个不停。", "explanation": "这里应该表达持续不断，不用“再次”。“再次”表示某个动作又发生一次，与持续不断的状态不符。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '91e180dd-508b-4434-8fa4-cf412f9f8831') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88055, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "很", "is_correct": false, "explanation": "搭配：“很”修饰形容词，不能修饰“能”后面的动作，这里不成立。"}, {"text": "已经", "is_correct": false, "explanation": "语义：“已经”表示动作已经完成，与“能……帮我看一下”这种请求语境冲突。"}, {"text": "再次", "is_correct": true, "explanation": "“再次”表示又一次做同样的事，与“帮我看一下”的请求相符。"}, {"text": "从来", "is_correct": false, "explanation": "语义：“从来”表示一直以来都没有，与表示请求的“能……吗”语境冲突。"}], "explanations": {"很": "搭配：“很”修饰形容词，不能修饰“能”后面的动作，这里不成立。", "已经": "语义：“已经”表示动作已经完成，与“能……帮我看一下”这种请求语境冲突。", "再次": "“再次”表示又一次做同样的事，与“帮我看一下”的请求相符。", "从来": "语义：“从来”表示一直以来都没有，与表示请求的“能……吗”语境冲突。"}, "sentence_index": 6, "correct_answer": "再次"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她第一次踢足球，却再次进了一个球。", "explanation": "这里不用“再次”。句中说“第一次踢足球”，“再次”要求此前已经做过同样的事，与“第一次”矛盾，应去掉“再次”。"}, {"text": "这个房间再次很干净。", "explanation": "这里不用“再次”。“再次”不直接修饰“很干净”这类静态形容词。"}, {"text": "他每天都再次吃早饭。", "explanation": "这里不用“再次”。“再次”指某次动作又发生一次，习惯性的重复应说“总是”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '91e180dd-508b-4434-8fa4-cf412f9f8831') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88055, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "小明忘了再次伞。", "corrected_sentence": "小明忘了带伞。", "error_description": "“再次”是副词，只能放在动词之前修饰动作，不能放在“忘了”和名词“伞”之间。这里应把“再次”换成动词“带”，写作“小明忘了带伞”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '91e180dd-508b-4434-8fa4-cf412f9f8831') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88055, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他借了我的书再次。", "corrected_sentence": "他借了我的书一次。", "error_description": "“再次”是副词，须放在动词之前，不能放在句末。若要表示次数，句末应改用数量词“一次”，写作“他借了我的书一次”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '91e180dd-508b-4434-8fa4-cf412f9f8831') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
