INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88056, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "副词，表示动作又一次发生。", "primary_collocate": null, "pronunciation": "zài cì", "ipa": "tsai˥˩ tsʰɨ˥˩", "syllable_count": 2, "sentences": [{"text": "他再次打开了门。", "target_word": "再次", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们明年再次见面。", "target_word": "再次", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师再次说明了作业要求。", "target_word": "再次", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她再次看了看手机。", "target_word": "再次", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家店再次开门了。", "target_word": "再次", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你再次检查一下答案。", "target_word": "再次", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今天他再次迟到了。", "target_word": "再次", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想再次去那个城市旅游。", "target_word": "再次", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比赛中他再次得了第一名。", "target_word": "再次", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子再次哭了起来。", "target_word": "再次", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性偏书面", "sense_fingerprint": "副词，动作又一次发生", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7b9c7047-c41d-4dd6-a29e-9eca3dfeee0a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88056, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "必须", "is_correct": false, "explanation": "语义：“必须”表示必要或义务，指向未来或尚未发生的事，与表示已完成动作的“了”不相容。"}, {"text": "再次", "is_correct": true, "explanation": "“再次”表示动作又一次发生，与“打开了门”的已完成语义相符。"}, {"text": "很", "is_correct": false, "explanation": "搭配：“很”修饰形容词或心理动词，不修饰“打开”这类动作动词。"}, {"text": "正在", "is_correct": false, "explanation": "体貌：“正在”表示动作进行中，不能与表示完成的“了”同用。"}], "explanations": {"必须": "语义：“必须”表示必要或义务，指向未来或尚未发生的事，与表示已完成动作的“了”不相容。", "再次": "“再次”表示动作又一次发生，与“打开了门”的已完成语义相符。", "很": "搭配：“很”修饰形容词或心理动词，不修饰“打开”这类动作动词。", "正在": "体貌：“正在”表示动作进行中，不能与表示完成的“了”同用。"}, "sentence_index": 0, "correct_answer": "再次"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他一直再次哭个不停。", "explanation": "这里应该用“又”表示反复哭，不用“再次”。“再次”强调某个动作又发生一次，与“一直……个不停”所表示的持续状态相矛盾。"}, {"text": "我第一次再次去北京。", "explanation": "这里不用“再次”。句子说的是第一次去北京，“再次”要求此前已经去过同一地方，与“初次”的意思相冲突，表示初次时应换用“初次”。"}, {"text": "我每天再次吃早饭。", "explanation": "这里不用“再次”。“再次”指某次动作又发生一次，习惯性的重复应说“总是”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '91e180dd-508b-4434-8fa4-cf412f9f8831') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88056, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "赶快", "is_correct": false, "explanation": "语义：“赶快”表示催促尽快行动，与已经发生的“迟到了”不相容。"}, {"text": "再次", "is_correct": true, "explanation": "“再次”表示又一次发生，与“今天……迟到了”的单次事件相符。"}, {"text": "从来", "is_correct": false, "explanation": "搭配：“从来”一般与否定词“不”连用，不能修饰已经发生的“迟到了”。"}, {"text": "将要", "is_correct": false, "explanation": "语义：“将要”表示即将发生，与已经发生的“迟到了”冲突。"}], "explanations": {"赶快": "语义：“赶快”表示催促尽快行动，与已经发生的“迟到了”不相容。", "再次": "“再次”表示又一次发生，与“今天……迟到了”的单次事件相符。", "从来": "搭配：“从来”一般与否定词“不”连用，不能修饰已经发生的“迟到了”。", "将要": "语义：“将要”表示即将发生，与已经发生的“迟到了”冲突。"}, "sentence_index": 6, "correct_answer": "再次"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他先洗手，再次吃饭。", "explanation": "这里应该用“然后”，不用“再次”。“再次”表示同一动作又发生一次，不用于表示先后顺序。"}, {"text": "他第一次参加比赛，却再次拿了冠军。", "explanation": "这里不用“再次”。句中说是“第一次参加比赛”，“再次”要求此前已经发生过同样的事，与“第一次”矛盾，应去掉“再次”。"}, {"text": "这座城市我从没来过，但我再次来到了这里。", "explanation": "这里不用“再次”。“再次”要求此前已经发生过同样的动作，句中说“从没来过”，前提不成立；表示初次时应说“第一次”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '91e180dd-508b-4434-8fa4-cf412f9f8831') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88056, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他关上了再次窗户。", "corrected_sentence": "他关上了一扇窗户。", "error_description": "“再次”是副词，应放在动词之前，不能夹在“关上了”和“窗户”之间。这里应把“再次”换成量词短语“一扇”，写作“他关上了一扇窗户”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '91e180dd-508b-4434-8fa4-cf412f9f8831') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88056, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我去了再次北京。", "corrected_sentence": "我去了一趟北京。", "error_description": "“再次”是副词，不能夹在“去了”和地名“北京”之间。这里应把“再次”换成量词短语“一趟”，写作“我去了一趟北京”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '91e180dd-508b-4434-8fa4-cf412f9f8831') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
