INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88061, 1, 'prompt1_core', '{"pos": "连词", "semantic_class": "function", "definition": "及其是说前面的东西，和它的某一部分。", "primary_collocate": null, "pronunciation": "jí qí", "ipa": "tɕi˧˥ tɕʰi˧˥", "syllable_count": 2, "sentences": [{"text": "我们参观了这座寺庙及其后院。", "target_word": "及其", "complexity_tier": "T3", "furigana": "wǒ men cān guān le zhè zuò sì miào jí qí hòu yuàn.", "sentence_source": "generated"}, {"text": "他买了一台电视及其遥控器。", "target_word": "及其", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医院及其大门前都有人。", "target_word": "及其", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座博物馆及其展厅都很有名。", "target_word": "及其", "complexity_tier": "T3", "furigana": "zhè zuò bó wù guǎn jí qí zhǎn tīng dōu hěn yǒu míng.", "sentence_source": "generated"}, {"text": "公园及其湖水都很干净。", "target_word": "及其", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请检查汽车及其轮子。", "target_word": "及其", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "房子及其院子都卖了。", "target_word": "及其", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她画了一棵树及其叶子。", "target_word": "及其", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师讲了这个故事及其结尾。", "target_word": "及其", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校及其图书馆今天开门。", "target_word": "及其", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "连词；前面的事物和它的某一部分；整体及其部分", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4e5d9128-ce98-4150-aea3-14a63da0a28d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88061, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "及其", "is_correct": true, "explanation": "正确答案：及其，读 jí qí，连词，表示前面的事物及其一部分。"}, {"text": "集起", "is_correct": false, "explanation": "集起 jíqǐ：jí 与“及”相同，qǐ（第三声）与 qí（第二声）声调不同，意思是聚集起来。"}, {"text": "习气", "is_correct": false, "explanation": "习气 xíqì：xí（第二声）与 jí（第二声）声母不同，qì（第四声）与 qí（第二声）声调不同，意思是习惯性的不良作风。"}, {"text": "集气", "is_correct": false, "explanation": "集气 jíqì：jí 与“及”相同，qì（第四声）与 qí（第二声）声调不同，意思是聚集力气、集中精神。"}, {"text": "继起", "is_correct": false, "explanation": "继起 jìqǐ：jì（第四声）与 jí（第二声）声调不同，qǐ（第三声）与 qí（第二声）声调不同，意思是接连发生。"}], "explanations": {"及其": "正确答案：及其，读 jí qí，连词，表示前面的事物及其一部分。", "集起": "集起 jíqǐ：jí 与“及”相同，qǐ（第三声）与 qí（第二声）声调不同，意思是聚集起来。", "习气": "习气 xíqì：xí（第二声）与 jí（第二声）声母不同，qì（第四声）与 qí（第二声）声调不同，意思是习惯性的不良作风。", "集气": "集气 jíqì：jí 与“及”相同，qì（第四声）与 qí（第二声）声调不同，意思是聚集力气、集中精神。", "继起": "继起 jìqǐ：jì（第四声）与 jí（第二声）声调不同，qǐ（第三声）与 qí（第二声）声调不同，意思是接连发生。"}, "sentence_index": null, "correct_answer": "及其"}, "level_3": {"options": [{"text": "及其", "is_correct": true, "explanation": "及其：表示“寺庙”和它的一部分“后院”。"}, {"text": "因此", "is_correct": false, "explanation": "配价：“因此”要引出结果小句，不能直接连接“寺庙”和“后院”两个名词。"}, {"text": "但是", "is_correct": false, "explanation": "语义：“但是”表示转折，“寺庙”与“后院”之间没有对立，与参观两处的意思不合。"}, {"text": "虽然", "is_correct": false, "explanation": "配价：“虽然”要引出让步小句，后面不能直接接名词“后院”，句子不通。"}], "explanations": {"及其": "及其：表示“寺庙”和它的一部分“后院”。", "因此": "配价：“因此”要引出结果小句，不能直接连接“寺庙”和“后院”两个名词。", "但是": "语义：“但是”表示转折，“寺庙”与“后院”之间没有对立，与参观两处的意思不合。", "虽然": "配价：“虽然”要引出让步小句，后面不能直接接名词“后院”，句子不通。"}, "sentence_index": 0, "correct_answer": "及其"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们买了牛奶及其面包。", "explanation": "这里应该用〈以及〉。及其表示前面的事物和它的一部分，面包不是牛奶的一部分，两样并列的东西要用以及。"}, {"text": "小猫及其小狗在院子里玩。", "explanation": "这里应该用〈和〉。及其的后项必须是前项的一部分，小狗不是小猫的一部分，并列两种动物应用和。"}, {"text": "我想喝茶及其咖啡。", "explanation": "这里应该用〈或者〉。“或者”表示选择，只能喝其中一种；及其表示整体与部分，咖啡不是茶的一部分。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ed880c2a-f0c2-4fac-8d1e-932e3919a069') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88061, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "及其", "is_correct": true, "explanation": "正确答案：及其，读 jí qí，连词，表示前面的事物及其一部分。"}, {"text": "机器", "is_correct": false, "explanation": "机器 jīqì：jī（第一声）与 jí（第二声）声调不同，qì（第四声）与 qí（第二声）声调不同，意思是机器。"}, {"text": "集起", "is_correct": false, "explanation": "集起 jíqǐ：jí 与“及”相同，qǐ（第三声）与 qí（第二声）声调不同，意思是聚集起来。"}, {"text": "记起", "is_correct": false, "explanation": "记起 jìqǐ：jì（第四声）与 jí（第二声）声调不同，qǐ（第三声）与 qí（第二声）声调不同，意思是想起来。"}, {"text": "积起", "is_correct": false, "explanation": "积起 jīqǐ：jī（第一声）与 jí（第二声）声调不同，qǐ（第三声）与 qí（第二声）声调不同，意思是积累起来。"}], "explanations": {"及其": "正确答案：及其，读 jí qí，连词，表示前面的事物及其一部分。", "机器": "机器 jīqì：jī（第一声）与 jí（第二声）声调不同，qì（第四声）与 qí（第二声）声调不同，意思是机器。", "集起": "集起 jíqǐ：jí 与“及”相同，qǐ（第三声）与 qí（第二声）声调不同，意思是聚集起来。", "记起": "记起 jìqǐ：jì（第四声）与 jí（第二声）声调不同，qǐ（第三声）与 qí（第二声）声调不同，意思是想起来。", "积起": "积起 jīqǐ：jī（第一声）与 jí（第二声）声调不同，qǐ（第三声）与 qí（第二声）声调不同，意思是积累起来。"}, "sentence_index": null, "correct_answer": "及其"}, "level_3": {"options": [{"text": "及其", "is_correct": true, "explanation": "及其：表示“房子”和它的一部分“院子”。"}, {"text": "因为", "is_correct": false, "explanation": "配价：“因为”要引出原因小句，不能直接接名词“院子”，句子不通。"}, {"text": "所以", "is_correct": false, "explanation": "配价：“所以”要引出结果小句，不能直接连接“房子”和“院子”两个名词。"}, {"text": "然而", "is_correct": false, "explanation": "语义：“然而”表示转折，“房子”与“院子”之间没有相反的意思，与“都卖了”的语境不合。"}], "explanations": {"及其": "及其：表示“房子”和它的一部分“院子”。", "因为": "配价：“因为”要引出原因小句，不能直接接名词“院子”，句子不通。", "所以": "配价：“所以”要引出结果小句，不能直接连接“房子”和“院子”两个名词。", "然而": "语义：“然而”表示转折，“房子”与“院子”之间没有相反的意思，与“都卖了”的语境不合。"}, "sentence_index": 6, "correct_answer": "及其"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "篮球及其足球都是运动。", "explanation": "这里应该用〈与〉。及其要求后项是前项的一部分，足球不是篮球的一部分，两种运动并列要用与。"}, {"text": "书架上有字典及其小说。", "explanation": "这里应该用〈还有〉。“还有”用于再列出一样东西，字典与小说是并列的两样；及其表示整体与部分，小说不是字典的一部分。"}, {"text": "猫及其狗都很可爱。", "explanation": "这里应该用〈跟〉。猫和狗是并列的两种动物，狗不是猫的一部分，应说“猫跟狗”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ed880c2a-f0c2-4fac-8d1e-932e3919a069') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88061, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这家饭店及其都很漂亮。", "corrected_sentence": "这家饭店及其花园都很漂亮。", "error_description": "错误：“及其”后面缺少它的一部分。“及其”后应接前项的部分事物，应为“这家饭店及其花园”，不能直接接“都”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ed880c2a-f0c2-4fac-8d1e-932e3919a069') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88061, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他擦了桌子及其的抽屉。", "corrected_sentence": "他擦了桌子及其抽屉。", "error_description": "错误：“及其”后面多加了“的”。“及其”后直接接名词，应为“及其抽屉”，写成“及其的抽屉”不通。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ed880c2a-f0c2-4fac-8d1e-932e3919a069') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
