INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88067, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "召开是把大家叫到一起来开会。", "primary_collocate": null, "pronunciation": "zhào kāi", "ipa": "ʈʂɑʊ˥˩ kʰaɪ˥", "syllable_count": 2, "sentences": [{"text": "学校明天召开家长会。", "target_word": "召开", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司下午要召开会议。", "target_word": "召开", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师召开了一次班会。", "target_word": "召开", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "村里召开大会，大家都去了。", "target_word": "召开", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个会是上个月召开的。", "target_word": "召开", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经理想召开一次会议，说说新计划。", "target_word": "召开", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们在大楼里召开会议。", "target_word": "召开", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校召开会议，请家长一起来。", "target_word": "召开", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司每个月都召开一次会议。", "target_word": "召开", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们决定在周五召开大会。", "target_word": "召开", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "召开了", "label": "体标"}, {"form": "召开过", "label": "体标"}], "register": "正式", "sense_fingerprint": "把人叫到一起，开会议或大会", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f8530ce5-0286-4987-b867-f019ea50f76c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88067, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "召开", "is_correct": true, "explanation": "正确：召开（zhào kāi）意思是把大家叫到一起开会。"}, {"text": "绕开", "is_correct": false, "explanation": "rào 与 zhào 声母不同（r 与 zh），意思是绕过、避开。"}, {"text": "闹开", "is_correct": false, "explanation": "nào 与 zhào 声母不同（n 与 zh），意思是事情传开、闹起来。"}, {"text": "找开", "is_correct": false, "explanation": "zhǎo（第三声）与 zhào（第四声）声调不同，意思是找零钱。"}], "explanations": {"召开": "正确：召开（zhào kāi）意思是把大家叫到一起开会。", "绕开": "rào 与 zhào 声母不同（r 与 zh），意思是绕过、避开。", "闹开": "nào 与 zhào 声母不同（n 与 zh），意思是事情传开、闹起来。", "找开": "zhǎo（第三声）与 zhào（第四声）声调不同，意思是找零钱。"}, "sentence_index": null, "correct_answer": "召开"}, "level_3": {"options": [{"text": "召开", "is_correct": true, "explanation": "正确：“召开”搭配会议、大会，与“家长会”相配，句意为学校明天召开家长会。"}, {"text": "修理", "is_correct": false, "explanation": "搭配：“修理”的对象是器物，不能说修理家长会。"}, {"text": "拆", "is_correct": false, "explanation": "语义：“拆”表示拆开、拆除，不能用于家长会。"}, {"text": "参观", "is_correct": false, "explanation": "语义：“参观”指去看场所或展品，家长会不能被参观。"}], "explanations": {"召开": "正确：“召开”搭配会议、大会，与“家长会”相配，句意为学校明天召开家长会。", "修理": "搭配：“修理”的对象是器物，不能说修理家长会。", "拆": "语义：“拆”表示拆开、拆除，不能用于家长会。", "参观": "语义：“参观”指去看场所或展品，家长会不能被参观。"}, "sentence_index": 0, "correct_answer": "召开"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "学校明天召开运动会。", "explanation": "这里应该用〈举行〉。召开只用于会议、大会，运动会要用举行。"}, {"text": "这所学校每年召开音乐会。", "explanation": "这里应该用〈举办〉。召开只用于会议，音乐会等文娱活动要用举办。"}, {"text": "医生正在召开手术。", "explanation": "这里应该用〈进行〉。召开只用于会议，手术要用进行。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '48c93dd2-8733-4a1a-82c1-dc57833b3687') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88067, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "召开", "is_correct": true, "explanation": "正确：“召开会议”是常用搭配，句意为他们在大楼里开会。"}, {"text": "游览", "is_correct": false, "explanation": "语义：“游览”指参观风景或名胜，会议不能被游览。"}, {"text": "入住", "is_correct": false, "explanation": "搭配：“入住”用于酒店、住所，不能说入住会议。"}, {"text": "搬运", "is_correct": false, "explanation": "搭配：“搬运”的对象是有形的物品，不能说搬运会议。"}], "explanations": {"召开": "正确：“召开会议”是常用搭配，句意为他们在大楼里开会。", "游览": "语义：“游览”指参观风景或名胜，会议不能被游览。", "入住": "搭配：“入住”用于酒店、住所，不能说入住会议。", "搬运": "搭配：“搬运”的对象是有形的物品，不能说搬运会议。"}, "sentence_index": 6, "correct_answer": "召开"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他们去年召开了读书活动。", "explanation": "这里应该用〈开展〉。召开只用于会议，读书、宣传等活动要用开展。"}, {"text": "他在会上召开了讲话。", "explanation": "这里应该用〈发表〉。讲话、看法要用发表，召开只用于会议本身。"}, {"text": "学校召开了一场篮球赛。", "explanation": "这里应该用〈举行〉。召开只用于会议、大会，比赛要用举行。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '48c93dd2-8733-4a1a-82c1-dc57833b3687') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88067, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "教务处下周召开过一次座谈会。", "corrected_sentence": "教务处下周召开一次座谈会。", "error_description": "错误在“过”。“过”表示曾经经历，与“下周”这样的将来时间不能搭配；应去掉“过”，说“召开一次座谈会”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '48c93dd2-8733-4a1a-82c1-dc57833b3687') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88067, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "研讨会召开的很顺利。", "corrected_sentence": "研讨会召开得很顺利。", "error_description": "错误在补语的助词。描述动作结果的补语要用“得”，不能用“的”；应说“召开得很顺利”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '48c93dd2-8733-4a1a-82c1-dc57833b3687') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
