INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88084, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "许多年；很长一段时间。", "primary_collocate": null, "pronunciation": "duō nián", "ipa": "tuɔ˥ njɛn˧˥", "syllable_count": 2, "sentences": [{"text": "我们多年没见面了。", "target_word": "多年", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "多年以后，他又回到了这里。", "target_word": "多年", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "多年前，这里只有一条小路。", "target_word": "多年", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "过了多年，她还记得那天的事。", "target_word": "多年", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "多年不下雪，今年冬天却下了大雪。", "target_word": "多年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件事已经过去多年了。", "target_word": "多年", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "多年不见，你一点儿都没变。", "target_word": "多年", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "多年后，我们在北京又见面了。", "target_word": "多年", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他多年没回老家，那里变化很大。", "target_word": "多年", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "多年过去了，小城的样子完全变了。", "target_word": "多年", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "多年前", "label": "复合"}, {"form": "多年后", "label": "复合"}], "register": "中性", "sense_fingerprint": "多年：许多年，一段很长的时间，常作时间词", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4b1fc457-8ada-4586-9ab8-800b096dd014') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88084, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "多年", "is_correct": true, "explanation": "正确：多年（duō nián），意思是很多年。"}, {"text": "大年", "is_correct": false, "explanation": "dà（第四声）与 duō（第一声）声母相同，韵母和声调都不同，意思是丰收的年份，与“多年”不同。"}, {"text": "多难", "is_correct": false, "explanation": "nán 与 nián 只差介音 i，意思是困难很多，与“多年”不同。"}, {"text": "多言", "is_correct": false, "explanation": "yán 与 nián 只差声母 n，意思是话多，与“多年”不同。"}, {"text": "多念", "is_correct": false, "explanation": "niàn（第四声）与 nián（第二声）声调不同，意思是多次诵读，与“多年”不同。"}], "explanations": {"多年": "正确：多年（duō nián），意思是很多年。", "大年": "dà（第四声）与 duō（第一声）声母相同，韵母和声调都不同，意思是丰收的年份，与“多年”不同。", "多难": "nán 与 nián 只差介音 i，意思是困难很多，与“多年”不同。", "多言": "yán 与 nián 只差声母 n，意思是话多，与“多年”不同。", "多念": "niàn（第四声）与 nián（第二声）声调不同，意思是多次诵读，与“多年”不同。"}, "sentence_index": null, "correct_answer": "多年"}, "level_3": {"options": [{"text": "多年", "is_correct": true, "explanation": "正确：“多年”表示很长时间，与“没见面了”相符。"}, {"text": "立刻", "is_correct": false, "explanation": "语义：“立刻”表示马上，与长时间没见面的意思矛盾。"}, {"text": "刚刚", "is_correct": false, "explanation": "搭配：“刚刚”通常用于刚发生的事，不能用来说明没见面的时长。"}, {"text": "偶尔", "is_correct": false, "explanation": "语义：“偶尔”表示次数少，与“没见面”的长时间状态矛盾。"}], "explanations": {"多年": "正确：“多年”表示很长时间，与“没见面了”相符。", "立刻": "语义：“立刻”表示马上，与长时间没见面的意思矛盾。", "刚刚": "搭配：“刚刚”通常用于刚发生的事，不能用来说明没见面的时长。", "偶尔": "语义：“偶尔”表示次数少，与“没见面”的长时间状态矛盾。"}, "sentence_index": 0, "correct_answer": "多年"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他来这儿只住了多年，就走了。", "explanation": "这里应该用〈几天〉。多年指很长时间，与“就走了”的短暂停留矛盾。"}, {"text": "这场雨下了多年就停了。", "explanation": "这里应该用〈几分钟〉。多年指很长时间，不能用于一场很快停下的雨。"}, {"text": "请你稍等多年，我马上过来。", "explanation": "这里应该用〈一会儿〉。多年指很长时间，与“马上过来”矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5b07d782-30c7-4f8f-bb66-34d0efb7eb3e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88084, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "多年", "is_correct": true, "explanation": "正确：“多年”表示很长时间，与“不见”和“一点儿都没变”的对比相符。"}, {"text": "每天", "is_correct": false, "explanation": "语义：“每天”表示天天，与“不见”的长时间状态矛盾。"}, {"text": "仅仅", "is_correct": false, "explanation": "搭配：“仅仅”后面一般接数量或动作，不能直接用来修饰“不见”。"}, {"text": "每周", "is_correct": false, "explanation": "语义：“每周”表示按周重复，与“不见”的意思矛盾。"}], "explanations": {"多年": "正确：“多年”表示很长时间，与“不见”和“一点儿都没变”的对比相符。", "每天": "语义：“每天”表示天天，与“不见”的长时间状态矛盾。", "仅仅": "搭配：“仅仅”后面一般接数量或动作，不能直接用来修饰“不见”。", "每周": "语义：“每周”表示按周重复，与“不见”的意思矛盾。"}, "sentence_index": 6, "correct_answer": "多年"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这张画我只用了多年就画完了。", "explanation": "这里应该用〈半小时〉。多年指很长时间，与“就画完了”的快速完成矛盾。"}, {"text": "这个汤只要炖多年就行了。", "explanation": "这里应该用〈一刻钟〉。多年指很长时间，不能用于炖汤这种短时间的事。"}, {"text": "这份报告我多年就写完了。", "explanation": "这里应该用〈一天〉。多年指很长时间，与“就写完了”的快速完成矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5b07d782-30c7-4f8f-bb66-34d0efb7eb3e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88084, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这座小城变了很多，我离开它已经一多年了。", "corrected_sentence": "这座小城变了很多，我离开它已经多年了。", "error_description": "错误：“多年”前面加了数词“一”。正确：应直接说“已经多年了”，“多年”本身已经表示很长时间。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5b07d782-30c7-4f8f-bb66-34d0efb7eb3e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88084, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我在这家工厂干着多年。", "corrected_sentence": "我在这家工厂干了多年。", "error_description": "错误：“干”后面用了“着”，表示持续的状态，与表示经历时长的“多年”不搭。正确：应说“干了多年”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5b07d782-30c7-4f8f-bb66-34d0efb7eb3e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
