INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88095, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "此次是说这一次。", "primary_collocate": null, "pronunciation": "cǐ cì", "ipa": "/tsʰɨ˨˩˦ tsʰɨ˥˩/", "syllable_count": 2, "sentences": [{"text": "此次我们在北京住了一个星期。", "target_word": "此次", "complexity_tier": "T3", "furigana": "cǐ cì", "sentence_source": "generated"}, {"text": "此次的天气比上次好。", "target_word": "此次", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "此次见面，我们谈了很久。", "target_word": "此次", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "此次考试我没有迟到。", "target_word": "此次", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "此次我只想休息一下。", "target_word": "此次", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "对此次的结果，大家都很高兴。", "target_word": "此次", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "此次放假一共有七天。", "target_word": "此次", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "此次的宴席菜品精致，大家赞不绝口。", "target_word": "此次", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "此次去日本，他买了很多东西。", "target_word": "此次", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请大家记住此次的教训。", "target_word": "此次", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "说话时指当前的这一次", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a298fe30-4cb1-44d1-ba83-8e5984f2584b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88095, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "此次", "is_correct": true, "explanation": "正确。“此次”指这一次，即目标词。"}, {"text": "此字", "is_correct": false, "explanation": "“此字”与“此次”第二个音节声母不同（z 与 c），声调相同，意思是这个字，不指这一次。"}, {"text": "此词", "is_correct": false, "explanation": "“此词”与“此次”第二个音节只差声调（cí 与 cì），意思是这首词，不指这一次。"}, {"text": "此事", "is_correct": false, "explanation": "“此事”与“此次”第二个音节声母不同（sh 与 c），意思是这件事，不指这一次。"}], "explanations": {"此次": "正确。“此次”指这一次，即目标词。", "此字": "“此字”与“此次”第二个音节声母不同（z 与 c），声调相同，意思是这个字，不指这一次。", "此词": "“此词”与“此次”第二个音节只差声调（cí 与 cì），意思是这首词，不指这一次。", "此事": "“此事”与“此次”第二个音节声母不同（sh 与 c），意思是这件事，不指这一次。"}, "sentence_index": null, "correct_answer": "此次"}, "level_3": {"options": [{"text": "此次", "is_correct": true, "explanation": "正确。“此次我们在北京住了一个星期”指这一次的经历，与句意相符。"}, {"text": "此地", "is_correct": false, "explanation": "语义：“此地”指地点，不指时间或次数，与“住了一个星期”的时段不合。"}, {"text": "明天", "is_correct": false, "explanation": "时间：“明天”指将来，与句中已完成的“住了”冲突。"}, {"text": "本地", "is_correct": false, "explanation": "语义：“本地”指本地区，不是这一次，句子说的是在北京住的时间。"}], "explanations": {"此次": "正确。“此次我们在北京住了一个星期”指这一次的经历，与句意相符。", "此地": "语义：“此地”指地点，不指时间或次数，与“住了一个星期”的时段不合。", "明天": "时间：“明天”指将来，与句中已完成的“住了”冲突。", "本地": "语义：“本地”指本地区，不是这一次，句子说的是在北京住的时间。"}, "sentence_index": 0, "correct_answer": "此次"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "此次我正在家里休息。", "explanation": "这里应该用〈此刻〉。“此次”指一次事件，不表示当下的时刻。"}, {"text": "此次的小狗很可爱，大家都喜欢它。", "explanation": "这里应该用〈这只〉。“此次”只修饰活动、事件，修饰小狗这类动物要用“这只”。"}, {"text": "此次我们去年去了北京。", "explanation": "这里应该用〈上次〉。“此次”指当前这一次，指过去的一次要说“上次”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '73ed49ee-02fe-4815-a4f8-121fa8aa9f1c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88095, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "此次", "is_correct": true, "explanation": "正确。“此次放假一共有七天”指这一次放假的天数，与句意相符。"}, {"text": "周末", "is_correct": false, "explanation": "语义：周末只有两天，不能说“周末放假一共有七天”。"}, {"text": "上午", "is_correct": false, "explanation": "语义：上午只是一天中的一段时间，不能是一个七天的假期。"}, {"text": "今晚", "is_correct": false, "explanation": "语义：“今晚”指今天晚上，不能说“今晚放假一共有七天”，句意不通。"}], "explanations": {"此次": "正确。“此次放假一共有七天”指这一次放假的天数，与句意相符。", "周末": "语义：周末只有两天，不能说“周末放假一共有七天”。", "上午": "语义：上午只是一天中的一段时间，不能是一个七天的假期。", "今晚": "语义：“今晚”指今天晚上，不能说“今晚放假一共有七天”，句意不通。"}, "sentence_index": 6, "correct_answer": "此次"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "咱俩此次去逛街吧！", "explanation": "语域：“此次”是书面语，不用于口语邀请，应说“这次”，这里的用法不对。"}, {"text": "此次的电视很大，大家都在看。", "explanation": "这里应该用〈这台〉。“此次”只修饰活动、事件，修饰电视这类物品要用“这台”。"}, {"text": "此次的老师很严格，我们都很怕她。", "explanation": "这里应该用〈这位〉。“此次”只修饰活动、事件，修饰老师这类人要用“这位”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '73ed49ee-02fe-4815-a4f8-121fa8aa9f1c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88095, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们为一个此次会议准备了很久。", "corrected_sentence": "我们为此次会议准备了很久。", "error_description": "错误：“此次”是指示性修饰语，前面不能再加数量词“一个”，应说“为此次会议”，不能说“为一个此次会议”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '73ed49ee-02fe-4815-a4f8-121fa8aa9f1c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88095, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "此次地会议很重要。", "corrected_sentence": "此次的会议很重要。", "error_description": "错误：“此次”后修饰名词要用“的”，不能用“地”（“地”用于修饰动词、形容词）。应说“此次的会议”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '73ed49ee-02fe-4815-a4f8-121fa8aa9f1c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
