INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88096, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "这一次；本次。", "primary_collocate": null, "pronunciation": "cǐ cì", "ipa": "/tsʰɨ˨˩˦ tsʰɨ˥˩/", "syllable_count": 2, "sentences": [{"text": "此次考试一共有三个部分。", "target_word": "此次", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "此次会议在北京举行。", "target_word": "此次", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "此次活动很成功。", "target_word": "此次", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "谢谢大家参加此次比赛。", "target_word": "此次", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "此次旅行我们去了三个城市。", "target_word": "此次", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "此次的作业比上次难。", "target_word": "此次", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师对此次考试很满意。", "target_word": "此次", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "此次出差，他带了两个箱子。", "target_word": "此次", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "此次比赛的第一名是小王。", "target_word": "此次", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "此次来中国，我想学做饭。", "target_word": "此次", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "指这一次、本次（书面）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a298fe30-4cb1-44d1-ba83-8e5984f2584b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88096, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "此次", "is_correct": true, "explanation": "正确。“此次”指这一次，即目标词。"}, {"text": "此字", "is_correct": false, "explanation": "“此字”与“此次”第二个音节声母不同（z 与 c），声调相同，意思是这个字，不指这一次。"}, {"text": "此词", "is_correct": false, "explanation": "“此词”与“此次”第二个音节只差声调（cí 与 cì），意思是这首词，不指这一次。"}, {"text": "此事", "is_correct": false, "explanation": "“此事”与“此次”第二个音节声母不同（sh 与 c），意思是这件事，不指这一次。"}], "explanations": {"此次": "正确。“此次”指这一次，即目标词。", "此字": "“此字”与“此次”第二个音节声母不同（z 与 c），声调相同，意思是这个字，不指这一次。", "此词": "“此词”与“此次”第二个音节只差声调（cí 与 cì），意思是这首词，不指这一次。", "此事": "“此事”与“此次”第二个音节声母不同（sh 与 c），意思是这件事，不指这一次。"}, "sentence_index": null, "correct_answer": "此次"}, "level_3": {"options": [{"text": "此次", "is_correct": true, "explanation": "正确。“此次考试”指这一次的考试，与句中“一共有三个部分”相符。"}, {"text": "此人", "is_correct": false, "explanation": "语义：“此人”指某个人，不能修饰“考试”，句子说的是考试的构成。"}, {"text": "此物", "is_correct": false, "explanation": "语义：“此物”指事物，不能修饰“考试”，句子说的是考试的构成。"}, {"text": "本人", "is_correct": false, "explanation": "语义：“本人”指说话人自己，不能修饰“考试”，句意不通。"}], "explanations": {"此次": "正确。“此次考试”指这一次的考试，与句中“一共有三个部分”相符。", "此人": "语义：“此人”指某个人，不能修饰“考试”，句子说的是考试的构成。", "此物": "语义：“此物”指事物，不能修饰“考试”，句子说的是考试的构成。", "本人": "语义：“本人”指说话人自己，不能修饰“考试”，句意不通。"}, "sentence_index": 0, "correct_answer": "此次"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "此次我正在吃饭。", "explanation": "这里应该用〈此时〉。“此次”指一次活动或事件，不表示当下的时刻。"}, {"text": "此次的房间很大，大家都很喜欢。", "explanation": "这里应该用〈这间〉。“此次”只修饰活动、事件，修饰房间这类具体事物要用“这间”。"}, {"text": "此次我们去年去了北京。", "explanation": "这里应该用〈上次〉。“此次”指当前这一次，指过去的一次要说“上次”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '73ed49ee-02fe-4815-a4f8-121fa8aa9f1c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88096, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "此次", "is_correct": true, "explanation": "正确。“对此次考试很满意”指对这一次考试满意，与句意相符。"}, {"text": "此刻", "is_correct": false, "explanation": "语义：“此刻”指当下的时刻，不能用来指一次具体的考试。"}, {"text": "当初", "is_correct": false, "explanation": "体貌：“当初”指过去的起始时间，与句中对已经进行的考试的评价不符。"}, {"text": "下次", "is_correct": false, "explanation": "语义：“下次”指尚未发生的考试，老师不可能对它表示满意。"}], "explanations": {"此次": "正确。“对此次考试很满意”指对这一次考试满意，与句意相符。", "此刻": "语义：“此刻”指当下的时刻，不能用来指一次具体的考试。", "当初": "体貌：“当初”指过去的起始时间，与句中对已经进行的考试的评价不符。", "下次": "语义：“下次”指尚未发生的考试，老师不可能对它表示满意。"}, "sentence_index": 6, "correct_answer": "此次"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "咱们此次去吃火锅吧！", "explanation": "语域：“此次”是书面语，用于正式场合；口语邀请里应说“这次”，这里的用法不对。"}, {"text": "此次的书包很重，我背不动。", "explanation": "这里应该用〈这个〉。“此次”只修饰活动、事件，修饰书包这类物品要用“这个”。"}, {"text": "此次我去年就到了中国。", "explanation": "这里应该用〈上次〉。“此次”指当前这一次，指过去的一次要说“上次”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '73ed49ee-02fe-4815-a4f8-121fa8aa9f1c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88096, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "一个此次会议很重要，请大家准时参加。", "corrected_sentence": "此次会议很重要，请大家准时参加。", "error_description": "错误：“此次”已含“这一次”的指示意义，前面不能再加“一个”。应说“此次会议”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '73ed49ee-02fe-4815-a4f8-121fa8aa9f1c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88096, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "同学们对那此次活动很满意。", "corrected_sentence": "同学们对此次活动很满意。", "error_description": "错误：“此次”已含指示意义，前面不能再加“那”。两个指示词不能并用，应说“对此次活动很满意”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '73ed49ee-02fe-4815-a4f8-121fa8aa9f1c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
