INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88112, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "对人或事物发表意见、作出评价。", "primary_collocate": null, "pronunciation": "píng lùn", "ipa": "pʰiŋ˧˥ lu̯ən˥˩", "syllable_count": 2, "sentences": [{"text": "大家都在评论这部新电影。", "target_word": "评论", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师认真地评论了每个同学的作文。", "target_word": "评论", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不喜欢评论别人。", "target_word": "评论", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "记者请专家评论一下这件事。", "target_word": "评论", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比赛结束后，电视里的人开始评论球员的表现。", "target_word": "评论", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你评论一下我的画儿。", "target_word": "评论", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "网友们纷纷评论这位歌手的新歌。", "target_word": "评论", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "对这个问题，我不想随便评论。", "target_word": "评论", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板当着大家的面评论了他的工作。", "target_word": "评论", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她常常在网上评论朋友们发的照片。", "target_word": "评论", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "评论了", "label": "体标"}, {"form": "评论过", "label": "体标"}, {"form": "评论评论", "label": "重叠"}, {"form": "評論", "label": "繁体"}], "register": "中性", "sense_fingerprint": "对人或事发表意见、作出评价", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b14ed482-1297-4790-a8d0-57fd5bb1c971') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88112, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "评论", "is_correct": true, "explanation": "正确。“评论”表示对电影发表意见，符合“大家都在……这部新电影”的语境。"}, {"text": "吃", "is_correct": false, "explanation": "语义：“吃”的对象不能是电影，这句话语义不通。"}, {"text": "打扫", "is_correct": false, "explanation": "搭配：“打扫”搭配房间、场地等，不能搭配“电影”。"}, {"text": "喝", "is_correct": false, "explanation": "语义：“喝”只用于饮品，不能用于电影。"}], "explanations": {"评论": "正确。“评论”表示对电影发表意见，符合“大家都在……这部新电影”的语境。", "吃": "语义：“吃”的对象不能是电影，这句话语义不通。", "打扫": "搭配：“打扫”搭配房间、场地等，不能搭配“电影”。", "喝": "语义：“喝”只用于饮品，不能用于电影。"}, "sentence_index": 0, "correct_answer": "评论"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "老师评论了他的作业，却一个字也没说。", "explanation": "这里应该用〈批改〉。“评论”要求说出看法，句中却说“一个字也没说”，前后矛盾；只是批改作业时，不需要发表议论。"}, {"text": "他评论了那只杯子，结果杯子摔碎了。", "explanation": "这里应该用〈碰〉。“评论”只是发表看法，不会使杯子摔碎；造成破损要用“碰”这类动作动词。"}, {"text": "老师评论了这扇窗，结果玻璃碎了一地。", "explanation": "这里应该用〈砸〉。“评论”是发表看法，不会使玻璃碎裂；造成碎裂要用“砸”这类动作动词。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4458b0e9-2ef5-428a-8c1e-3b89dfc44717') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88112, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "评论", "is_correct": true, "explanation": "正确。“评论”表示对歌手的新歌发表意见，符合语境。"}, {"text": "洗", "is_correct": false, "explanation": "语义：“洗”的对象应是衣物或身体，不能用于歌曲。"}, {"text": "煮", "is_correct": false, "explanation": "语义：“煮”的对象是食物，不能用于歌曲，句子不通。"}, {"text": "切", "is_correct": false, "explanation": "语义：“切”指把东西分开，用在歌曲上语义不通。"}], "explanations": {"评论": "正确。“评论”表示对歌手的新歌发表意见，符合语境。", "洗": "语义：“洗”的对象应是衣物或身体，不能用于歌曲。", "煮": "语义：“煮”的对象是食物，不能用于歌曲，句子不通。", "切": "语义：“切”指把东西分开，用在歌曲上语义不通。"}, "sentence_index": 6, "correct_answer": "评论"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她把这篇文章评论成了英文，朋友们都看懂了。", "explanation": "这里应该用〈翻译〉。“评论”指发表看法，不能改变文字的语言；把文章变成另一种语言要用“翻译”。"}, {"text": "她在网上评论了那只碗，结果碗摔碎了。", "explanation": "这里应该用〈碰〉。“评论”只是发表看法，不会使碗摔碎；造成破损要用“碰”这类动作动词。"}, {"text": "她把坏了的手机评论好了，又放回了桌子上。", "explanation": "这里应该用〈修〉。“评论”指发表看法，不能使器物恢复正常；修好手机要用“修”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4458b0e9-2ef5-428a-8c1e-3b89dfc44717') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88112, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我昨天评论了过这部电影。", "corrected_sentence": "我昨天评论过这部电影。", "error_description": "“评论”后面的体标只能用一个：表示曾经发生用“过”，不能同时用“了”和“过”。应说“评论过这部电影”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4458b0e9-2ef5-428a-8c1e-3b89dfc44717') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88112, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她把老师的文章评论。", "corrected_sentence": "她把老师的文章评论了一遍。", "error_description": "“把”字句中的动词后面要有补语或其他成分说明结果，“评论”后应加“了一遍”，不能只说“她把老师的文章评论”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4458b0e9-2ef5-428a-8c1e-3b89dfc44717') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
