INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88117, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "部队是由很多军人组成的一队人。", "primary_collocate": null, "pronunciation": "bù duì", "ipa": "pu˥˩ tweɪ˥˩", "syllable_count": 2, "sentences": [{"text": "一支部队正在山路上前进。", "target_word": "部队", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这支部队有五百多个人。", "target_word": "部队", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "部队早上六点就出发了。", "target_word": "部队", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们是从北方来的部队。", "target_word": "部队", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "部队在河边停下来休息。", "target_word": "部队", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那支部队的车开过了桥。", "target_word": "部队", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老百姓给路过的部队送水。", "target_word": "部队", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "部队晚上到了小村子。", "target_word": "部队", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山下来了部队，大家都出来看。", "target_word": "部队", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这支部队里有很多年轻人。", "target_word": "部队", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "支", "label": "量词"}, {"form": "野战部队", "label": "复合"}], "register": "中性", "sense_fingerprint": "一队军人，具体的一支队伍", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f8530ce5-0286-4987-b867-f019ea50f76c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88117, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "部队", "is_correct": true, "explanation": "正确：“一支”是部队的量词，“正在山路上前进”符合队伍行军的语境。"}, {"text": "书本", "is_correct": false, "explanation": "搭配：量词“支”用于队伍，不能用来数“书本”，书本也不会在山路上前进。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头不会前进，与“正在山路上前进”冲突。"}, {"text": "乌云", "is_correct": false, "explanation": "搭配：“一支”不能用来数乌云，且乌云不是能成队行进的队伍。"}], "explanations": {"部队": "正确：“一支”是部队的量词，“正在山路上前进”符合队伍行军的语境。", "书本": "搭配：量词“支”用于队伍，不能用来数“书本”，书本也不会在山路上前进。", "石头": "语义：石头不会前进，与“正在山路上前进”冲突。", "乌云": "搭配：“一支”不能用来数乌云，且乌云不是能成队行进的队伍。"}, "sentence_index": 0, "correct_answer": "部队"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "门口的部队很高，夏天可以乘凉。", "explanation": "这里应该用〈大树〉。部队指一队军人，不能用来指树。"}, {"text": "他是一名部队，从北方来。", "explanation": "这里应该用〈军人〉。部队指一支军队或军队组织，不能用来指单个人。"}, {"text": "我和部队一起上学。", "explanation": "这里应该用〈同学〉。部队是军队组织，不能指一起上学的人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '48c93dd2-8733-4a1a-82c1-dc57833b3687') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88117, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "部队", "is_correct": true, "explanation": "正确：部队是可以接受帮助、经过路过的队伍，符合“给路过的……送水”的语境。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头不喝水，不需要被送水。"}, {"text": "空气", "is_correct": false, "explanation": "语义：空气不需要被送水，与语境不合。"}, {"text": "桌子", "is_correct": false, "explanation": "搭配：“送水”的对象应该能喝水，“桌子”与这一搭配不合。"}], "explanations": {"部队": "正确：部队是可以接受帮助、经过路过的队伍，符合“给路过的……送水”的语境。", "石头": "语义：石头不喝水，不需要被送水。", "空气": "语义：空气不需要被送水，与语境不合。", "桌子": "搭配：“送水”的对象应该能喝水，“桌子”与这一搭配不合。"}, "sentence_index": 6, "correct_answer": "部队"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "公司的各个部队都很忙。", "explanation": "这里应该用〈部门〉。部队指军队，公司的内部机构要用部门。"}, {"text": "每周三，部队都来图书馆读书，大家很认真。", "explanation": "这里应该用〈社团〉。部队指军队组织，不能指一起来图书馆读书的学生社团成员。"}, {"text": "我家的部队很热情。", "explanation": "这里应该用〈邻居〉。部队指军队组织，不能指邻里之间热情的人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '48c93dd2-8733-4a1a-82c1-dc57833b3687') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88117, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这支部队们是从北方来的。", "corrected_sentence": "这支部队是从北方来的。", "error_description": "错误：“部队”后加了复数词尾“们”。“部队”是集合名词，不能加“们”，应直接说“部队”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '48c93dd2-8733-4a1a-82c1-dc57833b3687') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88117, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那只部队昨天到了这里。", "corrected_sentence": "那支部队昨天到了这里。", "error_description": "错误：量词“只”用错。部队作为队伍应用“支”，“只”用于动物。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '48c93dd2-8733-4a1a-82c1-dc57833b3687') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
