INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88118, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "军队的组织，也泛指军队。", "primary_collocate": null, "pronunciation": "bù duì", "ipa": "pu˥˩ tweɪ˥˩", "syllable_count": 2, "sentences": [{"text": "他十八岁就进了部队。", "target_word": "部队", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "哥哥在部队工作了五年。", "target_word": "部队", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他从部队回来以后，找了新工作。", "target_word": "部队", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "部队里的生活很有规律。", "target_word": "部队", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在部队学会了开车。", "target_word": "部队", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷年轻时在部队里当过兵。", "target_word": "部队", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "部队有严格的纪律。", "target_word": "部队", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想去部队当兵，不想上大学。", "target_word": "部队", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国家的部队要保护人民。", "target_word": "部队", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的爸爸是部队的医生。", "target_word": "部队", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "野战部队", "label": "复合"}, {"form": "部队长", "label": "复合"}], "register": "中性", "sense_fingerprint": "军队这个组织，军营生活与工作", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f8530ce5-0286-4987-b867-f019ea50f76c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88118, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "部队", "is_correct": true, "explanation": "正确：“十八岁就进了部队”指参军，符合语境。"}, {"text": "大海", "is_correct": false, "explanation": "语义：“进了大海”不能表示参军或工作的意思。"}, {"text": "天空", "is_correct": false, "explanation": "语义：天空不能表示一个可以进入工作的地方，语境不合。"}, {"text": "石头", "is_correct": false, "explanation": "搭配：“进了”后面的处所要能进入，石头不能进入。"}], "explanations": {"部队": "正确：“十八岁就进了部队”指参军，符合语境。", "大海": "语义：“进了大海”不能表示参军或工作的意思。", "天空": "语义：天空不能表示一个可以进入工作的地方，语境不合。", "石头": "搭配：“进了”后面的处所要能进入，石头不能进入。"}, "sentence_index": 0, "correct_answer": "部队"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他是一名部队。", "explanation": "这里应该用〈军人〉。部队指军队组织，不指个人，不能用“一名部队”。"}, {"text": "这家公司的各个部队都很忙。", "explanation": "这里应该用〈部门〉。部队指军队组织，公司的内部机构应说部门。"}, {"text": "我家的部队很大，有三间卧室。", "explanation": "这里应该用〈房子〉。部队指军队组织，不能用来说房子的大小和房间数。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '48c93dd2-8733-4a1a-82c1-dc57833b3687') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88118, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "部队", "is_correct": true, "explanation": "正确：部队是有组织、讲纪律的集体，“有严格的纪律”符合其特点。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头没有纪律可言，“石头有严格的纪律”不成立。"}, {"text": "天气", "is_correct": false, "explanation": "搭配：“有……纪律”的主语须是组织或团体，天气不能有纪律。"}, {"text": "月亮", "is_correct": false, "explanation": "语义：月亮不是组织，“月亮有严格的纪律”与常识不符。"}], "explanations": {"部队": "正确：部队是有组织、讲纪律的集体，“有严格的纪律”符合其特点。", "石头": "语义：石头没有纪律可言，“石头有严格的纪律”不成立。", "天气": "搭配：“有……纪律”的主语须是组织或团体，天气不能有纪律。", "月亮": "语义：月亮不是组织，“月亮有严格的纪律”与常识不符。"}, "sentence_index": 6, "correct_answer": "部队"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个部队很可爱，我每天都抱着它睡觉。", "explanation": "这里应该用〈玩具〉。部队指军队组织，不能像玩具一样被抱着睡觉。"}, {"text": "这个部队很好开，我想把它买下来。", "explanation": "这里应该用〈汽车〉。部队指军队组织，不能指可以驾驶、购买的车。"}, {"text": "部队在院子里玩。", "explanation": "这里应该用〈小孩〉。部队是军队组织，不能像小孩一样在院子里玩耍。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '48c93dd2-8733-4a1a-82c1-dc57833b3687') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88118, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他部队待过三年。", "corrected_sentence": "他在部队待过三年。", "error_description": "错误：漏掉介词“在”。表示处所要说“在部队”，不能直接说“部队待过”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '48c93dd2-8733-4a1a-82c1-dc57833b3687') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88118, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他在一所部队里当过兵。", "corrected_sentence": "他在一支部队里当过兵。", "error_description": "错误：量词“所”用错。部队应用“支”，“所”用于学校、医院等机构。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '48c93dd2-8733-4a1a-82c1-dc57833b3687') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88119, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "不满", "is_correct": true, "explanation": "反义：“满意”的反义词是“不满”，指心里不称心。"}, {"text": "结实", "is_correct": false, "explanation": "无关：“结实”与“满意”在这一义项上没有反义关系。"}, {"text": "干净", "is_correct": false, "explanation": "无关：“干净”与“满意”在这一义项上没有反义关系。"}, {"text": "安静", "is_correct": false, "explanation": "无关：“安静”与“满意”在这一义项上没有反义关系。"}], "correct_answer": "不满", "explanations": {"不满": "反义：“满意”的反义词是“不满”，指心里不称心。", "结实": "无关：“结实”与“满意”在这一义项上没有反义关系。", "干净": "无关：“干净”与“满意”在这一义项上没有反义关系。", "安静": "无关：“安静”与“满意”在这一义项上没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '040634d2-eecc-4f2b-ac40-4e35c0af5098') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88119, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "不满", "is_correct": true, "explanation": "反义：“满意”的反义词是“不满”，指心里不称心。"}, {"text": "美丽", "is_correct": false, "explanation": "无关：“美丽”与“满意”在这一义项上没有反义关系。"}, {"text": "聪明", "is_correct": false, "explanation": "无关：“聪明”与“满意”在这一义项上没有反义关系。"}, {"text": "整齐", "is_correct": false, "explanation": "无关：“整齐”与“满意”在这一义项上没有反义关系。"}], "correct_answer": "不满", "explanations": {"不满": "反义：“满意”的反义词是“不满”，指心里不称心。", "美丽": "无关：“美丽”与“满意”在这一义项上没有反义关系。", "聪明": "无关：“聪明”与“满意”在这一义项上没有反义关系。", "整齐": "无关：“整齐”与“满意”在这一义项上没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '040634d2-eecc-4f2b-ac40-4e35c0af5098') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88119, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "满意是心里觉得很好，没有不高兴的地方。", "primary_collocate": null, "pronunciation": "mǎn yì", "ipa": "man˨˩˦ i˥˩", "syllable_count": 2, "sentences": [{"text": "她脸上带着满意的笑。", "target_word": "满意", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈看了看，满意地点了点头。", "target_word": "满意", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他点点头，一脸满意。", "target_word": "满意", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "现在的生活很安稳，我心里很满意。", "target_word": "满意", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "吃完这顿饭，大家的心里都很满意。", "target_word": "满意", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他一直皱着眉，心里很不满意。", "target_word": "满意", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "听到好消息，爸爸露出了满意的表情。", "target_word": "满意", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家听完，心里都满意了。", "target_word": "满意", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "朋友来帮忙，我心里很满意。", "target_word": "满意", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她看着新家，心里非常满意。", "target_word": "满意", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "满意地", "label": "状语形式"}, {"form": "满意度", "label": "复合词"}], "register": "通用", "sense_fingerprint": "满意：心里觉得很好、没有不高兴，表示内心的感受，常见于神情和心情", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd8d3828f-e88f-4827-ada6-b99a5aa80d30') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88119, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "满意", "is_correct": true, "explanation": "正确：「满意」形容心里很称心的神情，与“脸上带着……的笑”搭配。"}, {"text": "方便", "is_correct": false, "explanation": "语义：“方便”指便利，不能用来形容笑的神情。"}, {"text": "深刻", "is_correct": false, "explanation": "语义：“深刻”多形容印象、思想，不说“深刻的笑”。"}, {"text": "整齐", "is_correct": false, "explanation": "搭配：“整齐”多用于排列或服饰，不能用来形容笑。"}], "explanations": {"满意": "正确：「满意」形容心里很称心的神情，与“脸上带着……的笑”搭配。", "方便": "语义：“方便”指便利，不能用来形容笑的神情。", "深刻": "语义：“深刻”多形容印象、思想，不说“深刻的笑”。", "整齐": "搭配：“整齐”多用于排列或服饰，不能用来形容笑。"}, "sentence_index": 0, "correct_answer": "满意"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的父亲去世了，他心里很满意。", "explanation": "语义：这里误用了“满意”，它表示心里没有不高兴，与“去世”所带来的悲伤情境矛盾，应该用〈难过〉。"}, {"text": "他听到噩耗，很满意地哭了。", "explanation": "语义：这里误用了“满意”，它表示心里没有不高兴，与“噩耗”和“哭”的伤心情绪矛盾，应该用〈伤心〉。"}, {"text": "他为了这件事很满意地生气了。", "explanation": "语义：这里误用了“满意”，它表示心里没有不高兴，与“生气”的不满情绪矛盾，应该用〈不满〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '040634d2-eecc-4f2b-ac40-4e35c0af5098') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88119, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "满意", "is_correct": true, "explanation": "正确：「满意」形容爸爸对好消息的称心表情，与句意一致。"}, {"text": "悲伤", "is_correct": false, "explanation": "语义：“悲伤”与“好消息”的情境矛盾。"}, {"text": "无奈", "is_correct": false, "explanation": "语义：“无奈”表示没有办法，与“好消息”的情境矛盾。"}, {"text": "圆满", "is_correct": false, "explanation": "搭配：“圆满”形容事情的结果，不能修饰“表情”。"}], "explanations": {"满意": "正确：「满意」形容爸爸对好消息的称心表情，与句意一致。", "悲伤": "语义：“悲伤”与“好消息”的情境矛盾。", "无奈": "语义：“无奈”表示没有办法，与“好消息”的情境矛盾。", "圆满": "搭配：“圆满”形容事情的结果，不能修饰“表情”。"}, "sentence_index": 6, "correct_answer": "满意"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个方案对谁都没有好处，他却心里很满意。", "explanation": "语义：“满意”表示心里没有不高兴，与“对谁都没有好处”的情境矛盾，应该用〈不满〉。"}, {"text": "他的房子被大水冲走了，他却很满意地站在一旁。", "explanation": "语义：“满意”表示心里没有不高兴，与房子被冲走的情境矛盾，应该用〈心疼〉。"}, {"text": "我很满意地等待着那个坏消息。", "explanation": "语义：这里误用了“满意”，它表示心里没有不高兴，与“坏消息”的情境矛盾，应该用〈担心〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '040634d2-eecc-4f2b-ac40-4e35c0af5098') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88119, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他脸上露出满意地神情。", "corrected_sentence": "他脸上露出满意的神情。", "error_description": "结构助词错误：“满意”修饰名词“神情”时要用“的”，“地”用于修饰动词，不能放在名词前面。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '040634d2-eecc-4f2b-ac40-4e35c0af5098') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88119, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "客人走后，他满意了地叹了口气。", "corrected_sentence": "客人走后，他满意地叹了口气。", "error_description": "标记错误：“满意”后面不能加“了”再接“地”，修饰动词时直接说“满意地”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '040634d2-eecc-4f2b-ac40-4e35c0af5098') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88120, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "不满", "is_correct": true, "explanation": "反义：“满意”的反义词是“不满”，指对结果或事物不称心。"}, {"text": "美丽", "is_correct": false, "explanation": "无关：“美丽”与“满意”在这一义项上没有反义关系。"}, {"text": "清楚", "is_correct": false, "explanation": "无关：“清楚”与“满意”在这一义项上没有反义关系。"}, {"text": "健康", "is_correct": false, "explanation": "无关：“健康”与“满意”在这一义项上没有反义关系。"}], "correct_answer": "不满", "explanations": {"不满": "反义：“满意”的反义词是“不满”，指对结果或事物不称心。", "美丽": "无关：“美丽”与“满意”在这一义项上没有反义关系。", "清楚": "无关：“清楚”与“满意”在这一义项上没有反义关系。", "健康": "无关：“健康”与“满意”在这一义项上没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '040634d2-eecc-4f2b-ac40-4e35c0af5098') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
