INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88120, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "对结果或事物感到称心如意。", "primary_collocate": null, "pronunciation": "mǎn yì", "ipa": "man˨˩˦ i˥˩", "syllable_count": 2, "sentences": [{"text": "老师对我的作业很满意。", "target_word": "满意", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这次考试的成绩，我很满意。", "target_word": "满意", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你对新房子满意吗？", "target_word": "满意", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "客人对饭店的服务非常满意。", "target_word": "满意", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我对这份工作不太满意。", "target_word": "满意", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他看了看房间，说他很满意。", "target_word": "满意", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈对我的新手机很满意。", "target_word": "满意", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个价格，你满意不满意？", "target_word": "满意", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他的回答让我很满意。", "target_word": "满意", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "老板对这次的结果十分满意。", "target_word": "满意", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "满意度", "label": "复合词"}], "register": "通用", "sense_fingerprint": "满意：对某个结果或事物（成绩、服务、工作）感到称心，常说“对……满意”", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd8d3828f-e88f-4827-ada6-b99a5aa80d30') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88120, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "满意", "is_correct": true, "explanation": "正确：「满意」表示对作业感到称心，可以用“对……很满意”的结构。"}, {"text": "迅速", "is_correct": false, "explanation": "搭配：“迅速”形容动作的快慢，不能用来修饰“作业”。"}, {"text": "沙哑", "is_correct": false, "explanation": "搭配：“沙哑”形容嗓音，不能用来修饰“作业”。"}, {"text": "饥饿", "is_correct": false, "explanation": "搭配：“饥饿”形容人的生理状态，不能用来评价“作业”。"}], "explanations": {"满意": "正确：「满意」表示对作业感到称心，可以用“对……很满意”的结构。", "迅速": "搭配：“迅速”形容动作的快慢，不能用来修饰“作业”。", "沙哑": "搭配：“沙哑”形容嗓音，不能用来修饰“作业”。", "饥饿": "搭配：“饥饿”形容人的生理状态，不能用来评价“作业”。"}, "sentence_index": 0, "correct_answer": "满意"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这次比赛失利，大家都很满意。", "explanation": "近义：“满意”表示称心，比赛失利后的心情应用〈遗憾〉。"}, {"text": "他的愿望终于满意了。", "explanation": "近义：“满意”说的是对结果的称心，对愿望、需求应用〈满足〉。"}, {"text": "见到老朋友，我很满意。", "explanation": "近义：“满意”不用于表达见面时的开心，这里应用〈高兴〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '040634d2-eecc-4f2b-ac40-4e35c0af5098') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88120, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "满意", "is_correct": true, "explanation": "正确：「满意」表示对手机的评价称心，与“对……很满意”的结构搭配。"}, {"text": "迟钝", "is_correct": false, "explanation": "搭配：“迟钝”形容人的反应，不能用来评价手机。"}, {"text": "沉默", "is_correct": false, "explanation": "搭配：“沉默”形容人不说话的状态，不能用来评价手机。"}, {"text": "尊敬", "is_correct": false, "explanation": "搭配：“尊敬”的对象一般是人，不能用于“新手机”。"}], "explanations": {"满意": "正确：「满意」表示对手机的评价称心，与“对……很满意”的结构搭配。", "迟钝": "搭配：“迟钝”形容人的反应，不能用来评价手机。", "沉默": "搭配：“沉默”形容人不说话的状态，不能用来评价手机。", "尊敬": "搭配：“尊敬”的对象一般是人，不能用于“新手机”。"}, "sentence_index": 6, "correct_answer": "满意"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我找不到钥匙，急得团团转，心里却很满意。", "explanation": "语义：“满意”表示称心，与“急得团团转”的焦急心情矛盾，应该用〈焦急〉。"}, {"text": "孩子在考试中作弊被抓了，妈妈却很满意。", "explanation": "语义：“满意”表示称心，孩子作弊被抓的情况应用〈失望〉。"}, {"text": "他看到自己的成绩，很满意地发了脾气。", "explanation": "语义：这里误用了“满意”，它表示称心，与“发了脾气”所表达的〈不满〉情绪矛盾，应该用〈不满〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '040634d2-eecc-4f2b-ac40-4e35c0af5098') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88120, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他向这个结果很满意。", "corrected_sentence": "他对这个结果很满意。", "error_description": "介词错误：“满意”表示对某事称心，应用介词“对”，不能用“向”，应说“对这个结果很满意”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '040634d2-eecc-4f2b-ac40-4e35c0af5098') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
